import {TupleSet} from '../support/tuple-map.js';

// Transient execution authority, per ADR 0037.
//
// An authority context is execution state, never program data. It has no canonical Value
// representation, cannot enter the graph, and carries no readable grants: the context object
// itself is empty, and everything about it lives privately in the service that minted it.
// A context the service did not mint is therefore rejected rather than interpreted, because
// it is simply absent from the private table.
//
// The v0 grant algebra is deliberately the dullest one that works: exact-match
// {operation, resource} pairs. `require` matches exactly, `attenuate` selects a subset of
// grants already held. No wildcards, inheritance, resource trees, deny rules or precedence,
// because each of those is a place where "narrower" becomes arguable and none is needed until
// object capabilities create real pressure.
const AUTHORITY_GRANT_ALGEBRA_V0 = 'authority-grant/v0';

class AuthorityError extends Error {
  constructor(message, {operation = null, resource = null} = {}) {
    super(message);
    this.name = 'AuthorityError';
    this.operation = operation;
    this.resource = resource;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function normalizeGrant(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const keys = Object.keys(value).sort();
  if (keys.length !== 2 || keys[0] !== 'operation' || keys[1] !== 'resource') {
    throw new TypeError(`${label} must contain exactly operation, resource`);
  }
  return Object.freeze({
    operation: requiredText(value.operation, `${label} operation`),
    resource: requiredText(value.resource, `${label} resource`),
  });
}

// A tuple set, not a set of joined strings. Operation and resource are both arbitrary non-empty
// text, so joining them is not injective: a grant of operation `object/read<NUL>x` on resource `y`
// produced the same key as `object/read` on `x<NUL>y`, and holding either would then satisfy a
// `require` for the other. A fail-open collision is exactly the defect ADR 0039 removed from
// resource names, and the grant table must not reintroduce it one layer up.
function normalizeGrants(values, label) {
  if (!Array.isArray(values)) throw new TypeError(`${label} must be an array`);
  const grants = new TupleSet(2);
  for (const [index, value] of values.entries()) {
    const {operation, resource} = normalizeGrant(value, `${label} ${index}`);
    grants.add([operation, resource]);
  }
  return grants;
}

// The context is intentionally an empty frozen object. There is nothing on it to read, stash,
// serialize or forge, and no field that could tempt a caller to branch on it.
class AuthorityContext {
  constructor() {
    Object.freeze(this);
  }
}

function createAuthorityService() {
  // WeakMap rather than a field on the context: the grant table cannot be reached from the
  // object handed out, and an object from anywhere else is not present here at all.
  const records = new WeakMap();

  function recordOf(context, label) {
    if (!(context instanceof AuthorityContext)) {
      throw new AuthorityError(`${label} must be an authority context issued by this service`);
    }
    const record = records.get(context);
    if (!record) throw new AuthorityError(`${label} was not issued by this service`);
    return record;
  }

  // Revocation walks upward rather than tracking descendants, so revoking a parent
  // invalidates everything derived from it without holding strong references to children.
  function revokedAncestor(record) {
    for (let current = record; current !== null; current = current.parent) {
      if (current.revoked) return true;
    }
    return false;
  }

  return Object.freeze({
    algebra: AUTHORITY_GRANT_ALGEBRA_V0,

    // Control-plane surface. Whoever may call this is by definition an authority root, which
    // is why the service is never placed in an executor context.
    issue({principal, grants = []} = {}) {
      const context = new AuthorityContext();
      records.set(context, {
        principal: requiredText(principal, 'authority principal'),
        grants: normalizeGrants(grants, 'authority grants'),
        parent: null,
        revoked: false,
      });
      return context;
    },

    // Narrowing only. There is no widening operation at all, so escalation is impossible by
    // construction rather than by check.
    attenuate(context, {grants = []} = {}) {
      const parent = recordOf(context, 'attenuated authority context');
      if (revokedAncestor(parent)) throw new AuthorityError('cannot attenuate a revoked authority context');
      const requested = normalizeGrants(grants, 'attenuated authority grants');
      for (const [operation, resource] of requested) {
        if (!parent.grants.has([operation, resource])) {
          throw new AuthorityError(
            `attenuation may only narrow: ${operation} on ${resource} is not held by the parent context`,
            {operation, resource},
          );
        }
      }
      const child = new AuthorityContext();
      records.set(child, {
        principal: parent.principal,
        grants: requested,
        parent,
        revoked: false,
      });
      return child;
    },

    revoke(context) {
      recordOf(context, 'revoked authority context').revoked = true;
    },

    // Host-side audit only. Deliberately not reachable from an executor context, so
    // `principal != capability` cannot degrade into branching on the principal.
    principalOf(context) {
      return recordOf(context, 'authority context').principal;
    },

    // Execution-time surface, and the only authority operation that ever crosses into an
    // executor. Check-only: it returns nothing, so there is no grant object to stash,
    // forward or outlive the check that produced it.
    require(context, demand) {
      const wanted = normalizeGrant(demand, 'authority demand');
      const record = recordOf(context, 'authority context');
      if (revokedAncestor(record)) {
        throw new AuthorityError(
          `authority revoked: ${wanted.operation} on ${wanted.resource}`,
          wanted,
        );
      }
      if (!record.grants.has([wanted.operation, wanted.resource])) {
        throw new AuthorityError(
          `not authorized: ${wanted.operation} on ${wanted.resource}`,
          wanted,
        );
      }
    },
  });
}

export {
  AUTHORITY_GRANT_ALGEBRA_V0,
  AuthorityContext,
  AuthorityError,
  createAuthorityService,
};

import {base64urlDecode, base64urlEncode, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';

// Canonical authority resource names for image objects, per ADR 0039 decision 5.
//
// Concatenating identifiers is unsafe. Neither imageId nor objectId forbids a separator, so
// `imageId + '/' + objectId` is not injective — both of these are accepted today and collide:
//
//   imageId "a/b", objectId "c"    ->  "a/b/c"
//   imageId "a",   objectId "b/c"  ->  "a/b/c"
//
// Two distinct objects in two distinct images would share one authority resource, so a grant
// for one would authorize the other. base64url is used because its alphabet excludes the
// separator, which makes the encoding injective by construction rather than by convention.
//
// This is the only permitted way to name an object resource. A hand-built string is exactly
// how the collision returns.
const OBJECT_RESOURCE_V0 = 'object-resource/v0';
const OBJECT_READ_OPERATION = 'object/read';
// ADR 0042: the object-scoped write operation (the read's mutation counterpart).
const OBJECT_WRITE_OPERATION = 'object/write';
const OBJECT_RESOURCE_SEPARATOR = '.';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function encodePart(value) {
  return base64urlEncode(utf8Encode(value));
}

function objectResource(imageId, objectId) {
  return encodePart(requiredText(imageId, 'object resource imageId'))
    + OBJECT_RESOURCE_SEPARATOR
    + encodePart(requiredText(objectId, 'object resource objectId'));
}

// Provided so a host or test can confirm what a resource names, never so a caller can build
// one from parts. Decoding is the inverse of an injective function, which is what makes the
// round trip meaningful.
function parseObjectResource(resource) {
  const text = requiredText(resource, 'object resource');
  const index = text.indexOf(OBJECT_RESOURCE_SEPARATOR);
  if (index < 0 || text.indexOf(OBJECT_RESOURCE_SEPARATOR, index + 1) >= 0) {
    throw new TypeError(`invalid ${OBJECT_RESOURCE_V0}: ${resource}`);
  }
  const decode = (part, label) => {
    const decoded = base64urlDecode(part);
    if (base64urlEncode(decoded) !== part) throw new TypeError(`invalid ${OBJECT_RESOURCE_V0} ${label}`);
    return utf8DecodeLossy(decoded);
  };
  return Object.freeze({
    imageId: decode(text.slice(0, index), 'imageId'),
    objectId: decode(text.slice(index + 1), 'objectId'),
  });
}

export {
  OBJECT_READ_OPERATION,
  OBJECT_RESOURCE_V0,
  OBJECT_WRITE_OPERATION,
  objectResource,
  parseObjectResource,
};

const REQUIRED_TRANSACTION_METHODS = Object.freeze([
  'get',
  'put',
  'scan',
  'append',
  'readStream',
  // Read-only stream-head read: the current committed high-water revision of a
  // stream. The backend owns stream persistence/head mechanics; this is a direct
  // head read, never a scan/reconstruction. Kept about STREAM HEADS only — the
  // backend has no notion of an Image frontier or a Project.
  'streamHead',
]);

const REQUIRED_BACKEND_METHODS = Object.freeze([
  'start',
  'stop',
  ...REQUIRED_TRANSACTION_METHODS,
  'transaction',
]);

class BackendContractError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BackendContractError';
  }
}

class VersionConflictError extends Error {
  constructor({collection, key, expectedVersion, actualVersion}) {
    super(
      `version conflict for ${collection}/${key}: expected ${expectedVersion}, actual ${actualVersion}`,
    );
    this.name = 'VersionConflictError';
    this.collection = collection;
    this.key = key;
    this.expectedVersion = expectedVersion;
    this.actualVersion = actualVersion;
  }
}

function assertMethods(value, methods, label) {
  if (!value || typeof value !== 'object') {
    throw new BackendContractError(`${label} must be an object`);
  }

  const missing = methods.filter(
    (method) => typeof value[method] !== 'function',
  );

  if (missing.length > 0) {
    throw new BackendContractError(
      `${label} is missing required methods: ${missing.join(', ')}`,
    );
  }

  return value;
}

function assertBackendTransaction(transaction) {
  return assertMethods(transaction, REQUIRED_TRANSACTION_METHODS, 'backend transaction');
}

function assertBackend(backend) {
  return assertMethods(backend, REQUIRED_BACKEND_METHODS, 'backend');
}

export {
  BackendContractError,
  REQUIRED_BACKEND_METHODS,
  REQUIRED_TRANSACTION_METHODS,
  VersionConflictError,
  assertBackend,
  assertBackendTransaction,
};

import {assertBackend} from './backend-contract.js';
import {LagrangeBackend} from './lagrange-backend.js';
import {MockBackend} from './mock-backend.js';

const DEFAULT_LAGRANGE_SPECIFIER = 'lagrange-server';

class LagrangeIntegrationError extends Error {
  constructor(message, {cause} = {}) {
    super(message, {cause});
    this.name = 'LagrangeIntegrationError';
  }
}

async function tryImportLagrange(specifier = DEFAULT_LAGRANGE_SPECIFIER) {
  try {
    const module = await import(specifier);
    return {
      available: true,
      module,
      version: module.VERSION ?? null,
      error: null,
    };
  } catch (error) {
    const packageMissing =
      error?.code === 'ERR_MODULE_NOT_FOUND' &&
      String(error.message).includes(specifier);

    if (!packageMissing) throw error;

    return {
      available: false,
      module: null,
      version: null,
      error,
    };
  }
}

async function createLagrangeBackend({loaded, lagrangeFactory, options}) {
  if (typeof lagrangeFactory === 'function') {
    const backend = await lagrangeFactory({
      namespace: options.namespace ?? 'lagrange-images',
      module: loaded.module,
    });
    assertBackend(backend);
    if (!backend.kind) backend.kind = 'lagrange';
    return backend;
  }

  if (typeof loaded.module.createEmbeddedLagrange === 'function') {
    return new LagrangeBackend({
      createEmbeddedLagrange: loaded.module.createEmbeddedLagrange,
      configuration: options.configuration ?? {},
      namespace: options.namespace ?? 'lagrange-images',
    });
  }

  const legacyFactory = loaded.module.createImageBackend;
  if (typeof legacyFactory !== 'function') return null;
  const backend = await legacyFactory({
    namespace: options.namespace ?? 'lagrange-images',
    module: loaded.module,
  });
  assertBackend(backend);
  if (!backend.kind) backend.kind = 'lagrange';
  return backend;
}

async function createBackend(options = {}) {
  // A pre-built backend instance passes straight through: the caller owns its lifecycle up to
  // here, and `createRuntime` starts and stops it exactly as one built from a mode. This is how a
  // forked MockBackend gets a runtime wrapped around it.
  if (options.instance) {
    assertBackend(options.instance);
    return options.instance;
  }

  // `process.env` is a Node host API. Read it defensively so this module stays
  // loadable/usable on a portable JS host with no `process` global: an explicit
  // `options.mode` (what the portable composition root always passes) never touches
  // it, and a host without `process` simply gets the 'auto' default rather than a
  // ReferenceError. Node behavior is unchanged.
  const envBackend = typeof process !== 'undefined' && process.env ? process.env.LAGRANGE_BACKEND : undefined;
  const mode = options.mode ?? envBackend ?? 'auto';

  if (!['auto', 'mock', 'lagrange'].includes(mode)) {
    throw new Error(`unknown backend mode: ${mode}`);
  }

  if (mode === 'mock') {
    return new MockBackend({
      integration: {selectedBy: 'explicit'},
    });
  }

  const loaded = await tryImportLagrange(
    options.lagrangeSpecifier ?? DEFAULT_LAGRANGE_SPECIFIER,
  );

  if (loaded.available) {
    const backend = await createLagrangeBackend({
      loaded,
      lagrangeFactory: options.lagrangeFactory,
      options,
    });

    if (backend) return backend;

    if (mode === 'lagrange') {
      throw new LagrangeIntegrationError(
        'lagrange-server was imported, but it exposes neither createEmbeddedLagrange nor an image backend factory',
      );
    }

    return new MockBackend({
      integration: {
        selectedBy: 'auto-fallback',
        lagrangeLoaded: true,
        lagrangeVersion: loaded.version,
        reason: 'image-backend-adapter-not-available',
      },
    });
  }

  if (mode === 'lagrange') {
    throw new LagrangeIntegrationError(
      `cannot import ${options.lagrangeSpecifier ?? DEFAULT_LAGRANGE_SPECIFIER}`,
      {cause: loaded.error},
    );
  }

  return new MockBackend({
    integration: {
      selectedBy: 'auto-fallback',
      lagrangeLoaded: false,
      reason: 'lagrange-package-not-installed',
    },
  });
}

export {
  DEFAULT_LAGRANGE_SPECIFIER,
  LagrangeIntegrationError,
  createBackend,
  tryImportLagrange,
};

import {VersionConflictError} from './backend-contract.js';
import {
  LAGRANGE_IMAGE_SCHEMA,
  LAGRANGE_IMAGE_TABLES,
  collectionRecord,
  collectionScanRange,
  eventId,
  streamRoute,
} from './lagrange-schema.js';

function cloneWithout(value, field) {
  const cloned = structuredClone(value);
  if (!cloned || typeof cloned !== 'object' || Array.isArray(cloned)) {
    throw new TypeError('backend values and events must be records');
  }
  delete cloned[field];
  return cloned;
}

function encodePayload(value, field) {
  const encoded = JSON.stringify(cloneWithout(value, field));
  if (encoded === undefined) throw new TypeError('backend value is not JSON encodable');
  return encoded;
}

function decodePayload(payload) {
  const source = Buffer.isBuffer(payload) ? payload.toString('utf8') : payload;
  if (typeof source !== 'string') throw new TypeError('stored payload must be text');
  return JSON.parse(source);
}

function rows(result) {
  return Array.isArray(result?.rows) ? result.rows : [];
}

function changed(result) {
  const count = result?.affectedRows ?? result?.rowCount ?? result?.changes ?? result?.count;
  return Number.isInteger(count) ? count > 0 : rows(result).length > 0;
}

function storedRecord(row) {
  return {...decodePayload(row.payload), _version: Number(row.version)};
}

function storedEvent(row) {
  return {...decodePayload(row.payload), revision: Number(row.revision)};
}

function assertWork(work) {
  if (typeof work !== 'function') throw new TypeError('backend transaction work must be a function');
}

async function selectRecord(database, target) {
  const result = await database.query(
    `SELECT version, payload FROM ${target.table} WHERE id = ?`,
    [target.id],
  );
  return rows(result)[0] ?? null;
}

async function putRecord(database, collection, key, value, {expectedVersion} = {}) {
  const target = collectionRecord(collection, key);
  const current = await selectRecord(database, target);
  const actualVersion = current ? Number(current.version) : 0;
  if (expectedVersion !== undefined && expectedVersion !== actualVersion) {
    throw new VersionConflictError({collection, key, expectedVersion, actualVersion});
  }

  const version = actualVersion + 1;
  const payload = encodePayload(value, '_version');
  if (!current) {
    await database.query(
      `INSERT INTO ${target.table} (id, record_key, version, payload) VALUES (?, ?, ?, ?)`,
      [target.id, target.recordKey, version, payload],
    );
  } else {
    const result = await database.query(
      `UPDATE ${target.table} SET payload = ?, version = ? WHERE id = ? AND version = ?`,
      [payload, version, target.id, actualVersion],
    );
    if (!changed(result)) {
      throw new VersionConflictError({
        collection,
        key,
        expectedVersion: actualVersion,
        actualVersion: null,
      });
    }
  }
  return {...decodePayload(payload), _version: version};
}

async function getRecord(database, collection, key) {
  const row = await selectRecord(database, collectionRecord(collection, key));
  return row ? storedRecord(row) : undefined;
}

async function scanRecords(database, collection, {prefix = ''} = {}) {
  const range = collectionScanRange(collection, prefix);
  const result = range.lower === null ?
    await database.query(
      `SELECT id, record_key, version, payload FROM ${range.table} ORDER BY id`,
    ) :
    await database.query(
      `SELECT id, record_key, version, payload FROM ${range.table} WHERE id >= ? AND id < ? ORDER BY id`,
      [range.lower, range.upper],
    );
  return rows(result)
    .map((row) => ({key: row.record_key, value: storedRecord(row)}))
    .filter(({key}) => key.startsWith(prefix))
    .sort(({key: left}, {key: right}) => left.localeCompare(right));
}

async function appendEvent(database, stream, event) {
  const route = streamRoute(stream);
  const result = await database.query(
    `SELECT revision FROM ${LAGRANGE_IMAGE_TABLES.streamHeads} WHERE id = ?`,
    [route.id],
  );
  const current = rows(result)[0] ?? null;
  const revision = current ? Number(current.revision) + 1 : 1;
  if (current) {
    const update = await database.query(
      `UPDATE ${LAGRANGE_IMAGE_TABLES.streamHeads} SET revision = ? WHERE id = ? AND revision = ?`,
      [revision, route.id, Number(current.revision)],
    );
    if (!changed(update)) throw new Error(`stream revision conflict: ${stream}`);
  } else {
    await database.query(
      `INSERT INTO ${LAGRANGE_IMAGE_TABLES.streamHeads} (id, revision) VALUES (?, ?)`,
      [route.id, revision],
    );
  }

  const payload = encodePayload(event, 'revision');
  await database.query(
    `INSERT INTO ${LAGRANGE_IMAGE_TABLES.events} (id, stream_id, revision, payload) VALUES (?, ?, ?, ?)`,
    [eventId(route.id, revision), route.id, revision, payload],
  );
  return {...decodePayload(payload), revision};
}

async function readEvents(database, stream, {afterRevision = 0} = {}) {
  if (!Number.isSafeInteger(afterRevision) || afterRevision < 0) {
    throw new RangeError('afterRevision must be a non-negative safe integer');
  }
  const route = streamRoute(stream);
  const result = await database.query(
    `SELECT revision, payload FROM ${LAGRANGE_IMAGE_TABLES.events} WHERE id >= ? AND id < ? AND revision > ? ORDER BY id`,
    [route.lower, route.upper, afterRevision],
  );
  return rows(result).map(storedEvent);
}

// The current committed head revision of a stream: the dedicated stream-heads row
// this backend already maintains at append (CAS high-water mark), read directly —
// O(1), never a scan/reconstruction of the event log. 0 for a stream with no
// committed events (no row yet).
async function readStreamHead(database, stream) {
  const route = streamRoute(stream);
  const result = await database.query(
    `SELECT revision FROM ${LAGRANGE_IMAGE_TABLES.streamHeads} WHERE id = ?`,
    [route.id],
  );
  const current = rows(result)[0] ?? null;
  return current ? Number(current.revision) : 0;
}

function transactionView(database, isActive) {
  const activeDatabase = () => {
    if (!isActive()) throw new TypeError('backend transaction is no longer active');
    return database;
  };
  return Object.freeze({
    async get(collection, key) {
      return await getRecord(activeDatabase(), collection, key);
    },
    async put(collection, key, value, options = {}) {
      return await putRecord(activeDatabase(), collection, key, value, options);
    },
    async scan(collection, options = {}) {
      return await scanRecords(activeDatabase(), collection, options);
    },
    async append(stream, event) {
      return await appendEvent(activeDatabase(), stream, event);
    },
    async readStream(stream, options = {}) {
      return await readEvents(activeDatabase(), stream, options);
    },
    async streamHead(stream) {
      return await readStreamHead(activeDatabase(), stream);
    },
  });
}

class LagrangeBackend {
  constructor({createEmbeddedLagrange, configuration = {}, namespace = 'lagrange-images', runtime = null} = {}) {
    if (!runtime && typeof createEmbeddedLagrange !== 'function') {
      throw new TypeError('createEmbeddedLagrange must be a function');
    }
    if (typeof namespace !== 'string' || namespace.length === 0) {
      throw new TypeError('namespace must be a non-empty string');
    }
    this.kind = 'lagrange';
    this.durable = true;
    this.integration = Object.freeze({namespace});
    this.createEmbeddedLagrange = createEmbeddedLagrange;
    this.configuration = structuredClone(configuration);
    this.namespace = namespace;
    this.runtime = runtime;
    this.database = null;
    this.state = 'created';
  }

  assertStarted() {
    if (this.state !== 'started' || !this.database) throw new TypeError('Lagrange backend is not started');
    return this.database;
  }

  async start() {
    if (this.state === 'started') return this;
    if (this.state !== 'created') throw new TypeError('Lagrange backend cannot be restarted');
    this.runtime ??= this.createEmbeddedLagrange({configuration: this.configuration});
    this.state = 'starting';
    try {
      await this.runtime.start();
      this.database = this.runtime.openApplicationDatabase({applicationId: this.namespace});
      for (const statement of LAGRANGE_IMAGE_SCHEMA) await this.database.query(statement);
      this.state = 'started';
      return this;
    } catch (error) {
      this.state = 'failed';
      try {
        await this.runtime.stop();
      } catch {
        // Preserve the startup/schema failure as the primary failure.
      }
      throw error;
    }
  }

  async stop() {
    if (this.state === 'stopped') return;
    if (this.state === 'created') {
      this.state = 'stopped';
      return;
    }
    try {
      await this.runtime?.stop();
    } finally {
      this.database = null;
      this.state = 'stopped';
    }
  }

  async get(collection, key) {
    return await getRecord(this.assertStarted(), collection, key);
  }

  async put(collection, key, value, options = {}) {
    return await this.transaction((transaction) => transaction.put(collection, key, value, options));
  }

  async scan(collection, options = {}) {
    return await scanRecords(this.assertStarted(), collection, options);
  }

  async append(stream, event) {
    return await this.transaction((transaction) => transaction.append(stream, event));
  }

  async readStream(stream, options = {}) {
    return await readEvents(this.assertStarted(), stream, options);
  }

  async streamHead(stream) {
    return await readStreamHead(this.assertStarted(), stream);
  }

  async transaction(work) {
    assertWork(work);
    const database = this.assertStarted();
    return await database.transaction(async (sqlTransaction) => {
      let active = true;
      const transaction = transactionView(sqlTransaction, () => active);
      try {
        return await work(transaction);
      } finally {
        active = false;
      }
    });
  }
}

export {LagrangeBackend};

import {bytesToHex, utf8Encode} from '../support/portable-bytes.js';
const LAGRANGE_IMAGE_TABLES = Object.freeze({
  images: 'lagrange_images_images',
  records: 'lagrange_images_records',
  snapshots: 'lagrange_images_snapshots',
  streamHeads: 'lagrange_images_stream_heads',
  events: 'lagrange_images_events',
});

const LAGRANGE_IMAGE_SCHEMA = Object.freeze([
  `CREATE TABLE IF NOT EXISTS ${LAGRANGE_IMAGE_TABLES.images} (
    id TEXT PRIMARY KEY,
    record_key TEXT NOT NULL,
    version INTEGER NOT NULL,
    payload TEXT NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS ${LAGRANGE_IMAGE_TABLES.records} (
    id TEXT PRIMARY KEY,
    record_key TEXT NOT NULL,
    version INTEGER NOT NULL,
    payload TEXT NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS ${LAGRANGE_IMAGE_TABLES.snapshots} (
    id TEXT PRIMARY KEY,
    record_key TEXT NOT NULL,
    version INTEGER NOT NULL,
    payload TEXT NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS ${LAGRANGE_IMAGE_TABLES.streamHeads} (
    id TEXT PRIMARY KEY,
    revision INTEGER NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS ${LAGRANGE_IMAGE_TABLES.events} (
    id TEXT PRIMARY KEY,
    stream_id TEXT NOT NULL,
    revision INTEGER NOT NULL,
    payload TEXT NOT NULL
  )`,
]);

const IMAGE_COLLECTION = 'images';
const IMAGE_COLLECTION_PREFIX = 'image:';
const OBJECT_COLLECTION_SUFFIX = ':objects';
const SNAPSHOT_COLLECTION_SUFFIX = ':snapshots';
const HISTORY_STREAM_SUFFIX = ':history';
const RANGE_TERMINATOR = 'g';
const REVISION_WIDTH = 16;

function assertStorageName(value, label) {
  if (typeof value !== 'string') throw new TypeError(`${label} must be a string`);
  return value;
}

function encodePart(value, label) {
  return bytesToHex(utf8Encode(assertStorageName(value, label)));
}

function imageIdFrom(name, suffix) {
  if (!name.startsWith(IMAGE_COLLECTION_PREFIX) || !name.endsWith(suffix)) return null;
  return name.slice(IMAGE_COLLECTION_PREFIX.length, -suffix.length);
}

function encodedRange(prefix) {
  return Object.freeze({lower: prefix, upper: `${prefix}${RANGE_TERMINATOR}`});
}

function collectionRoute(collection) {
  assertStorageName(collection, 'collection');
  if (collection === IMAGE_COLLECTION) {
    return Object.freeze({
      table: LAGRANGE_IMAGE_TABLES.images,
      base: 'i/',
    });
  }

  const imageId = imageIdFrom(collection, OBJECT_COLLECTION_SUFFIX);
  if (imageId !== null) {
    return Object.freeze({
      table: LAGRANGE_IMAGE_TABLES.records,
      base: `i/${encodePart(imageId, 'image id')}/`,
    });
  }

  const snapshotImageId = imageIdFrom(collection, SNAPSHOT_COLLECTION_SUFFIX);
  if (snapshotImageId !== null) {
    return Object.freeze({
      table: LAGRANGE_IMAGE_TABLES.snapshots,
      base: `i/${encodePart(snapshotImageId, 'image id')}/`,
    });
  }

  return Object.freeze({
    table: LAGRANGE_IMAGE_TABLES.records,
    base: `c/${encodePart(collection, 'collection')}/`,
  });
}

function collectionRecord(collection, key) {
  const route = collectionRoute(collection);
  const recordKey = assertStorageName(key, 'key');
  return Object.freeze({
    ...route,
    id: `${route.base}${encodePart(recordKey, 'key')}`,
    recordKey,
  });
}

function collectionScanRange(collection, prefix = '') {
  const route = collectionRoute(collection);
  const keyPrefix = assertStorageName(prefix, 'scan prefix');
  return Object.freeze({...route, ...encodedRange(`${route.base}${encodePart(keyPrefix, 'scan prefix')}`)});
}

function streamRoute(stream) {
  assertStorageName(stream, 'stream');
  const imageId = imageIdFrom(stream, HISTORY_STREAM_SUFFIX);
  const id = imageId === null ?
    `s/${encodePart(stream, 'stream')}` :
    `i/${encodePart(imageId, 'image id')}`;
  return Object.freeze({id, ...encodedRange(`${id}/`)});
}

function eventId(streamId, revision) {
  if (!Number.isSafeInteger(revision) || revision < 1) {
    throw new RangeError('stream revision must be a positive safe integer');
  }
  return `${streamId}/${String(revision).padStart(REVISION_WIDTH, '0')}`;
}

export {
  LAGRANGE_IMAGE_SCHEMA,
  LAGRANGE_IMAGE_TABLES,
  collectionRecord,
  collectionScanRange,
  eventId,
  streamRoute,
};

import {VersionConflictError} from './backend-contract.js';

function clone(value) {
  return value === undefined ? undefined : structuredClone(value);
}

function cloneCollections(collections) {
  return new Map([...collections].map(([name, bucket]) => [
    name,
    new Map([...bucket].map(([key, value]) => [key, clone(value)])),
  ]));
}

function cloneStreams(streams) {
  return new Map([...streams].map(([name, events]) => [name, clone(events)]));
}

function getFrom(state, collection, key) {
  return clone(state.collections.get(collection)?.get(key));
}

function putInto(state, collection, key, value, {expectedVersion} = {}) {
  let bucket = state.collections.get(collection);
  if (!bucket) {
    bucket = new Map();
    state.collections.set(collection, bucket);
  }

  const current = bucket.get(key);
  const actualVersion = current?._version ?? 0;

  if (expectedVersion !== undefined && expectedVersion !== actualVersion) {
    throw new VersionConflictError({
      collection,
      key,
      expectedVersion,
      actualVersion,
    });
  }

  const stored = {
    ...clone(value),
    _version: actualVersion + 1,
  };
  bucket.set(key, stored);
  return clone(stored);
}

function scanFrom(state, collection, {prefix = ''} = {}) {
  const bucket = state.collections.get(collection);
  if (!bucket) return [];

  return [...bucket.entries()]
    .filter(([key]) => key.startsWith(prefix))
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, value]) => ({key, value: clone(value)}));
}

function appendTo(state, stream, event) {
  let events = state.streams.get(stream);
  if (!events) {
    events = [];
    state.streams.set(stream, events);
  }

  const stored = {
    ...clone(event),
    revision: events.length + 1,
  };
  events.push(stored);
  return clone(stored);
}

function readStreamFrom(state, stream, {afterRevision = 0} = {}) {
  const events = state.streams.get(stream) ?? [];
  return clone(events.filter((event) => event.revision > afterRevision));
}

// The current committed head revision of a stream: the last appended event's
// revision, or 0 for a stream with no events. Read-only; a direct head read from
// the stream's own state, never a scan.
function streamHeadFrom(state, stream) {
  const events = state.streams.get(stream) ?? [];
  return events.length === 0 ? 0 : events[events.length - 1].revision;
}

function transactionView(state, isActive) {
  const active = () => {
    if (!isActive()) throw new TypeError('backend transaction is no longer active');
  };

  return Object.freeze({
    async get(collection, key) {
      active();
      return getFrom(state, collection, key);
    },
    async put(collection, key, value, options = {}) {
      active();
      return putInto(state, collection, key, value, options);
    },
    async scan(collection, options = {}) {
      active();
      return scanFrom(state, collection, options);
    },
    async append(stream, event) {
      active();
      return appendTo(state, stream, event);
    },
    async readStream(stream, options = {}) {
      active();
      return readStreamFrom(state, stream, options);
    },
    async streamHead(stream) {
      active();
      return streamHeadFrom(state, stream);
    },
  });
}

class MockBackend {
  constructor({integration = {}} = {}) {
    this.kind = 'mock';
    this.durable = false;
    this.integration = Object.freeze({...integration});
    this.collections = new Map();
    this.streams = new Map();
    this.started = false;
    this.writeTail = Promise.resolve();
  }

  async exclusive(operation) {
    const result = this.writeTail.then(operation, operation);
    this.writeTail = result.then(() => undefined, () => undefined);
    return await result;
  }

  async start() {
    this.started = true;
    return this;
  }

  async stop() {
    await this.writeTail;
    this.started = false;
  }

  async get(collection, key) {
    return getFrom(this, collection, key);
  }

  async put(collection, key, value, options = {}) {
    return await this.exclusive(() => putInto(this, collection, key, value, options));
  }

  async scan(collection, options = {}) {
    return scanFrom(this, collection, options);
  }

  async append(stream, event) {
    return await this.exclusive(() => appendTo(this, stream, event));
  }

  async readStream(stream, options = {}) {
    return readStreamFrom(this, stream, options);
  }

  async streamHead(stream) {
    return streamHeadFrom(this, stream);
  }

  // An independent MockBackend holding a deep copy of this one's current state — versions,
  // streams and all — through the same clone helpers a transaction draft uses. Writes to either
  // side are invisible to the other. Mock-only on purpose: a durable backend cannot promise a
  // cheap whole-state copy, so this is a testing seam (the exhaustive recovery sweeps fork one
  // prepared base image per iteration instead of rebuilding it), not part of the backend contract.
  fork() {
    const forked = new MockBackend({integration: this.integration});
    forked.collections = cloneCollections(this.collections);
    forked.streams = cloneStreams(this.streams);
    return forked;
  }

  async transaction(work) {
    if (typeof work !== 'function') throw new TypeError('backend transaction work must be a function');

    return await this.exclusive(async () => {
      const draft = {
        collections: cloneCollections(this.collections),
        streams: cloneStreams(this.streams),
      };
      let active = true;
      const transaction = transactionView(draft, () => active);

      try {
        const result = await work(transaction);
        this.collections = draft.collections;
        this.streams = draft.streams;
        return result;
      } finally {
        active = false;
      }
    });
  }
}

export {MockBackend};

import {canonicalizeValue, isObjectRef} from '../value/index.js';
import {parseAnyCallableInterfaceArtifact} from './interface-v2-artifacts.js';

// Every implementation binding points at the callable interface it implements through
// this role. The interface never points back, so one interface artifact can be shared
// by any number of lanes without knowing they exist.
const CALLABLE_INTERFACE_DEPENDENCY_ROLE = 'interface';

function normalizeObjectRef(value, label) {
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) throw new TypeError(`${label} must be an unpinned object ref`);
  return ref;
}

function bindingDependencyRef(artifact, role, label) {
  const matches = (artifact.dependencies ?? []).filter((dependency) => dependency.role === role);
  if (matches.length !== 1) {
    throw new TypeError(`${label} must declare exactly one ${role} dependency`);
  }
  return normalizeObjectRef(matches[0].artifact, `${label} ${role}`);
}

function assertBindingDependencies(artifact, roles, label) {
  const actual = (artifact.dependencies ?? []).map((dependency) => dependency.role).sort();
  const expected = [...roles].sort();
  if (actual.length !== expected.length || actual.some((role, index) => role !== expected[index])) {
    throw new TypeError(`${label} must declare exactly the dependencies ${expected.join(', ')}`);
  }
  return artifact;
}

async function resolveCallableInterface(images, bindingArtifact, label) {
  const ref = bindingDependencyRef(bindingArtifact, CALLABLE_INTERFACE_DEPENDENCY_ROLE, label);
  const artifact = await images.getCodeArtifact(ref.imageId, ref.objectId);
  if (!artifact) throw new TypeError(`${label} interface not found: ${ref.imageId}/${ref.objectId}`);
  return Object.freeze({descriptor: parseAnyCallableInterfaceArtifact(artifact), ref});
}

async function resolveBindingDependency(images, bindingArtifact, role, label) {
  const ref = bindingDependencyRef(bindingArtifact, role, label);
  const artifact = await images.getCodeArtifact(ref.imageId, ref.objectId);
  if (!artifact) throw new TypeError(`${label} ${role} not found: ${ref.imageId}/${ref.objectId}`);
  return Object.freeze({artifact, ref});
}

export {
  CALLABLE_INTERFACE_DEPENDENCY_ROLE,
  assertBindingDependencies,
  bindingDependencyRef,
  normalizeObjectRef,
  resolveBindingDependency,
  resolveCallableInterface,
};

import {base64Decode, bytesEqual, concatBytes, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';
import {VALUE_KIND, bytesValue, canonicalizeValue, isReference} from '../value/index.js';
import {isPrimitiveType, resolveDeclaredType, typeFingerprint} from './type-grammar.js';

// interface-composite/v0
//
// A schema-directed envelope carrying one composite InterfaceValue as canonical bytes. The
// payload carries no type tags whatsoever: the declared interface type says what every byte
// means, so decoding without that type is impossible by construction. That is the property
// which keeps this from becoming the generic nested collection Value the substrate rejects.
//
//   offset 0   'LGIC'                       magic
//   offset 4   version u8 = 0
//   offset 5   fingerprint, 32 bytes        sha256 of the normalized type schema
//   offset 37  payload                      schema-directed, untagged
//
// The fingerprint is over the type, never over the interface artifact identity, so the
// envelope hides no graph relationship.
const INTERFACE_COMPOSITE_V0 = 'interface-composite/v0';
const MAGIC = utf8Encode('LGIC');
const VERSION = 0;
const FINGERPRINT_LENGTH = 32;
const HEADER_LENGTH = MAGIC.length + 1 + FINGERPRINT_LENGTH;

// Bounds keep a malformed envelope from costing unbounded memory or time.
const MAX_VALUE_DEPTH = 32;
const MAX_LIST_LENGTH = 1_000_000;
const MAX_PAYLOAD_BYTES = 64 * 1024 * 1024;

const S32_MIN = -(2n ** 31n);
const S32_MAX = 2n ** 31n - 1n;
const S64_MIN = -(2n ** 63n);
const S64_MAX = 2n ** 63n - 1n;

class InterfaceCompositeError extends TypeError {
  constructor(message) {
    super(message);
    this.name = 'InterfaceCompositeError';
  }
}

function fail(message) {
  throw new InterfaceCompositeError(message);
}

class Writer {
  constructor() {
    this.chunks = [];
    this.length = 0;
  }

  push(buffer) {
    this.length += buffer.length;
    if (this.length > MAX_PAYLOAD_BYTES) fail(`composite payload exceeds ${MAX_PAYLOAD_BYTES} bytes`);
    this.chunks.push(buffer);
  }

  u8(value) { const b = new Uint8Array(1); new DataView(b.buffer).setUint8(0, value); this.push(b); }
  u32(value) { const b = new Uint8Array(4); new DataView(b.buffer).setUint32(0, value, false); this.push(b); }
  s32(value) { const b = new Uint8Array(4); new DataView(b.buffer).setInt32(0, value, false); this.push(b); }
  s64(value) { const b = new Uint8Array(8); new DataView(b.buffer).setBigInt64(0, value, false); this.push(b); }
  f32(value) { const b = new Uint8Array(4); new DataView(b.buffer).setFloat32(0, value, false); this.push(b); }
  f64(value) { const b = new Uint8Array(8); new DataView(b.buffer).setFloat64(0, value, false); this.push(b); }
  bytes(bytes) { this.u32(bytes.length); this.push(bytes); }

  contents() { return concatBytes(this.chunks); }
}

class Reader {
  constructor(buffer) {
    this.buffer = buffer;
    this.offset = 0;
  }

  take(count) {
    if (count < 0 || this.offset + count > this.buffer.length) fail('composite payload ended early');
    const slice = this.buffer.subarray(this.offset, this.offset + count);
    this.offset += count;
    return slice;
  }

  u8() { const s = this.take(1); return new DataView(s.buffer, s.byteOffset, s.byteLength).getUint8(0); }
  u32() { const s = this.take(4); return new DataView(s.buffer, s.byteOffset, s.byteLength).getUint32(0, false); }
  s32() { const s = this.take(4); return new DataView(s.buffer, s.byteOffset, s.byteLength).getInt32(0, false); }
  s64() { const s = this.take(8); return new DataView(s.buffer, s.byteOffset, s.byteLength).getBigInt64(0, false); }
  f32() { const s = this.take(4); return new DataView(s.buffer, s.byteOffset, s.byteLength).getFloat32(0, false); }
  f64() { const s = this.take(8); return new DataView(s.buffer, s.byteOffset, s.byteLength).getFloat64(0, false); }
  bytes() { return this.take(this.u32()); }

  atEnd() { return this.offset === this.buffer.length; }
}

// An InterfaceValue is a plain host value: a primitive, an array, or a plain record object.
// It may never contain a canonical ref, because the graph walker is flat and would not see
// a reference buried inside an envelope.
function assertRefFree(value, label) {
  if (value && typeof value === 'object' && !Array.isArray(value) && value.kind !== undefined) {
    const canonical = (() => {
      try { return canonicalizeValue(value); } catch { return null; }
    })();
    if (canonical && isReference(canonical)) {
      fail(`${label} contains a reference; InterfaceValues must be ref-free`);
    }
  }
  return value;
}

function writeValue(writer, value, type, types, label, depth) {
  if (depth > MAX_VALUE_DEPTH) fail(`${label} exceeds the maximum value depth of ${MAX_VALUE_DEPTH}`);
  assertRefFree(value, label);

  if (isPrimitiveType(type)) {
    switch (type) {
      case 'bool':
        if (typeof value !== 'boolean') fail(`${label} must be a boolean`);
        return writer.u8(value ? 1 : 0);
      case 's32': {
        if (typeof value !== 'number' && typeof value !== 'bigint') fail(`${label} must be an integer`);
        const n = BigInt(value);
        if (n < S32_MIN || n > S32_MAX) fail(`${label} is outside s32 range`);
        return writer.s32(Number(n));
      }
      case 's64': {
        if (typeof value !== 'number' && typeof value !== 'bigint') fail(`${label} must be an integer`);
        const n = BigInt(value);
        if (n < S64_MIN || n > S64_MAX) fail(`${label} is outside s64 range`);
        return writer.s64(n);
      }
      case 'f32':
        if (typeof value !== 'number') fail(`${label} must be a number`);
        return writer.f32(Math.fround(value));
      case 'f64':
        if (typeof value !== 'number') fail(`${label} must be a number`);
        return writer.f64(value);
      case 'string':
        if (typeof value !== 'string') fail(`${label} must be a string`);
        return writer.bytes(utf8Encode(value));
      case 'list<u8>': {
        if (!(value instanceof Uint8Array) && !Array.isArray(value)) fail(`${label} must be a byte sequence`);
        return writer.bytes(value instanceof Uint8Array ? value : Uint8Array.from(value));
      }
      default:
        return fail(`${label} has unsupported primitive type ${type}`);
    }
  }

  const resolved = resolveDeclaredType(type, types);
  if (resolved.kind === 'list') {
    if (!Array.isArray(value)) fail(`${label} must be an array`);
    if (value.length > MAX_LIST_LENGTH) fail(`${label} exceeds ${MAX_LIST_LENGTH} elements`);
    writer.u32(value.length);
    value.forEach((element, index) => {
      writeValue(writer, element, resolved.element, types, `${label}[${index}]`, depth + 1);
    });
    return undefined;
  }
  if (resolved.kind === 'record') {
    if (!value || typeof value !== 'object' || Array.isArray(value)) fail(`${label} must be a record object`);
    const extra = Object.keys(value).filter((key) => !resolved.fields.some((field) => field.name === key));
    if (extra.length > 0) fail(`${label} has fields not in the type: ${extra.join(', ')}`);
    // Declared field order, not object key order: the layout is part of the type.
    for (const field of resolved.fields) {
      if (!Object.hasOwn(value, field.name)) fail(`${label} is missing field ${field.name}`);
      writeValue(writer, value[field.name], field.type, types, `${label}.${field.name}`, depth + 1);
    }
    return undefined;
  }
  return fail(`${label} has unsupported type constructor ${resolved.kind}`);
}

function readValue(reader, type, types, label, depth) {
  if (depth > MAX_VALUE_DEPTH) fail(`${label} exceeds the maximum value depth of ${MAX_VALUE_DEPTH}`);

  if (isPrimitiveType(type)) {
    switch (type) {
      case 'bool': {
        const raw = reader.u8();
        if (raw > 1) fail(`${label} has invalid boolean encoding`);
        return raw === 1;
      }
      case 's32': return reader.s32();
      case 's64': return reader.s64();
      case 'f32': return reader.f32();
      case 'f64': return reader.f64();
      case 'string': return utf8DecodeLossy(reader.bytes());
      case 'list<u8>': return reader.bytes().slice();
      default: return fail(`${label} has unsupported primitive type ${type}`);
    }
  }

  const resolved = resolveDeclaredType(type, types);
  if (resolved.kind === 'list') {
    const count = reader.u32();
    if (count > MAX_LIST_LENGTH) fail(`${label} declares more than ${MAX_LIST_LENGTH} elements`);
    const items = [];
    for (let index = 0; index < count; index++) {
      items.push(readValue(reader, resolved.element, types, `${label}[${index}]`, depth + 1));
    }
    return items;
  }
  if (resolved.kind === 'record') {
    const record = {};
    for (const field of resolved.fields) {
      record[field.name] = readValue(reader, field.type, types, `${label}.${field.name}`, depth + 1);
    }
    return record;
  }
  return fail(`${label} has unsupported type constructor ${resolved.kind}`);
}

function packCompositeValue(value, type, types = {}, label = 'composite') {
  const writer = new Writer();
  writeValue(writer, value, type, types, label, 0);
  const envelope = concatBytes([
    MAGIC,
    new Uint8Array([VERSION]),
    typeFingerprint(type, types),
    writer.contents(),
  ]);
  return bytesValue(envelope);
}

function envelopeFingerprint(envelope) {
  return envelope.slice(MAGIC.length + 1, HEADER_LENGTH);
}

// A lane whose transport the host controls at both ends may carry the payload alone. The
// header exists to protect an envelope that floats around as an opaque Value; inside such a
// transport the host has already verified the incoming fingerprint and is the one entitled
// to assert the outgoing type, because it is the side that knows it.
//
// This is what lets the Cuis image handle any composite type without computing SHA-256.
function compositePayloadOf(value, label = 'composite') {
  const canonical = canonicalizeValue(value);
  if (canonical.kind !== VALUE_KIND.BYTES) fail(`${label} must be a bytes Value`);
  const envelope = base64Decode(canonical.base64);
  if (envelope.length < HEADER_LENGTH) fail(`${label} envelope is too short`);
  return bytesValue(new Uint8Array(envelope.subarray(HEADER_LENGTH)));
}

function compositeEnvelopeOf(payload, type, types = {}, label = 'composite') {
  const canonical = canonicalizeValue(payload);
  if (canonical.kind !== VALUE_KIND.BYTES) fail(`${label} payload must be a bytes Value`);
  const bytes = base64Decode(canonical.base64);
  // Decoding against the declared type is what earns the right to stamp its fingerprint.
  const reader = new Reader(bytes);
  const decoded = readValue(reader, type, types, label, 0);
  if (!reader.atEnd()) fail(`${label} payload has trailing bytes`);
  return packCompositeValue(decoded, type, types, label);
}

function unpackCompositeValue(value, type, types = {}, label = 'composite') {
  const canonical = canonicalizeValue(value);
  if (canonical.kind !== VALUE_KIND.BYTES) {
    fail(`${label} must be a bytes Value carrying an ${INTERFACE_COMPOSITE_V0} envelope`);
  }
  const envelope = base64Decode(canonical.base64);
  if (envelope.length < HEADER_LENGTH) fail(`${label} envelope is too short`);
  if (!bytesEqual(envelope.subarray(0, MAGIC.length), MAGIC)) {
    fail(`${label} is not an ${INTERFACE_COMPOSITE_V0} envelope`);
  }
  const version = envelope[MAGIC.length];
  if (version !== VERSION) fail(`${label} envelope declares unsupported version ${version}`);

  // The fingerprint check is what makes decoding require the *exact* expected type rather
  // than merely a structurally compatible one.
  const expected = typeFingerprint(type, types);
  if (!bytesEqual(envelopeFingerprint(envelope), expected)) {
    fail(`${label} envelope was encoded against a different interface type`);
  }

  const reader = new Reader(envelope.subarray(HEADER_LENGTH));
  const decoded = readValue(reader, type, types, label, 0);
  if (!reader.atEnd()) fail(`${label} envelope has trailing bytes`);
  return decoded;
}

export {
  HEADER_LENGTH as INTERFACE_COMPOSITE_HEADER_LENGTH,
  INTERFACE_COMPOSITE_V0,
  InterfaceCompositeError,
  MAX_LIST_LENGTH,
  MAX_VALUE_DEPTH,
  compositeEnvelopeOf,
  compositePayloadOf,
  envelopeFingerprint,
  packCompositeValue,
  unpackCompositeValue,
};

