// ADR 0067. An authorized atomic image-local creation batch: N create specs in ONE call, committed
// in ONE backend.transaction (all records + history, or none). The novel authorization rule is
// transaction-local fresh-object provenance: an edge to an EXISTING object T requires
// object/edge-write(T); an edge to a member created in THIS SAME batch is justified by that
// member's own object/create grant. Local names are request-syntax only, never ObjectRef/Value/
// authority, and never leak.
const IMAGE_CREATION_BATCH_BINDING_V1 = 'image-creation-batch-binding/v1';

// Reserved member-record fields: `class` (the member's class-id, required) and `name` (the local
// name, optional). Neither becomes a durable slot value; both are consumed by the batch lane.
const RESERVED_MEMBER_FIELDS = new Set(['class', 'name']);

// create-many(values: list<member-record>) -> string
// Each member record carries `class` (required, a class-id string), `name` (optional, the local
// name), plus the per-class data fields the binding maps. The binding's `fields` is a per-class
// map: class-id -> field list (same normalized shape as the single lane's).
//
// The member-record type is the union of all fields across all mapped classes. Each class's
// mapping covers a subset of the record fields; validate that subset, not exact bidirectional
// coverage (a Presentation member does not carry the Perspective-only `presentations` field).
function assertBatchCreationInterface(descriptor, fieldsByClass = {}) {
  const {parameters, result, types = {}} = descriptor;
  if (parameters.length !== 1) {
    throw new TypeError(
      `${IMAGE_CREATION_BATCH_BINDING_V1} requires parameters (values: list<member-record>)`,
    );
  }
  if (result !== 'string') {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} must return the version tokens as string`);
  }
  const list = resolveDeclaredType(parameters[0], types);
  if (!list || list.kind !== 'list') {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} values parameter must be a list type`);
  }
  const record = resolveDeclaredType(list.element, types);
  if (!record || record.kind !== 'record') {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} values element must be a declared record type`);
  }
  // Validate the reserved fields.
  const classField = record.fields.find((f) => f.name === 'class');
  if (!classField || classField.type !== 'string') {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member record must declare a class field of type string`);
  }
  const nameField = record.fields.find((f) => f.name === 'name');
  if (nameField && nameField.type !== 'string') {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member record name field must be string when present`);
  }
  const recordFieldsByName = new Map(record.fields.map((f) => [f.name, f]));
  // Validate every class's mapping against the interface record.
  for (const [classId, fields] of Object.entries(fieldsByClass)) {
    const indexedFields = new Map(fields.filter((f) => f.indexed).map((f) => [f.name, f.edge]));
    for (const field of fields) {
      const recordField = recordFieldsByName.get(field.name);
      if (!recordField) {
        throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} class ${classId} maps ${field.name}, which the member record does not declare`);
      }
      if (indexedFields.has(field.name)) {
        assertIndexedFieldType(recordField, types, `${IMAGE_CREATION_BATCH_BINDING_V1} class ${classId} indexed field ${field.name}`, indexedFields.get(field.name));
        continue;
      }
      if (!CALLABLE_TYPES.includes(recordField.type)) {
        throw new TypeError(
          `${IMAGE_CREATION_BATCH_BINDING_V1} class ${classId} field ${field.name} must be a leaf type; v1 does not write nested values`,
        );
      }
    }
  }
  return record;
}

// The indexed-field type check is identical to the single lane's; it is re-exported from
// image-creation-binding.js to keep the two lanes byte-identical.

function normalizeBatchFields(fieldsByClass, label) {
  if (!fieldsByClass || typeof fieldsByClass !== 'object' || Array.isArray(fieldsByClass)) {
    throw new TypeError(`${label} fields must be an object keyed by class-id`);
  }
  const normalized = {};
  for (const [classId, fields] of Object.entries(fieldsByClass)) {
    normalized[classId] = normalizeCreationFields(fields, `${label} class ${classId}`);
  }
  return Object.freeze(normalized);
}

function parseImageCreationBatchBindingArtifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== IMAGE_CREATION_BATCH_BINDING_V1) {
    throw new TypeError(`artifact must be ${IMAGE_CREATION_BATCH_BINDING_V1}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError('image creation batch binding content must be a text Value');
  assertBindingDependencies(artifact, [CALLABLE_INTERFACE_DEPENDENCY_ROLE], IMAGE_CREATION_BATCH_BINDING_V1);
  let decoded;
  try {
    decoded = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError('image creation batch binding content must be valid JSON', {cause: error});
  }
  const expected = ['abi', 'fields'];
  const actual = Object.keys(decoded).sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} descriptor must contain exactly ${expected.join(', ')}`);
  }
  if (decoded.abi !== IMAGE_CREATION_BATCH_BINDING_V1) {
    throw new TypeError(`unsupported image creation batch binding ABI: ${decoded.abi}`);
  }
  return Object.freeze({fields: normalizeBatchFields(decoded.fields, IMAGE_CREATION_BATCH_BINDING_V1)});
}

async function installImageCreationBatchBinding({
  images,
  callableInterface,
  fields,
  imageId = null,
  bindingId = randomUUID(),
  blockId = randomUUID(),
  bindingMetadata = {},
  blockMetadata = {},
} = {}) {
  const imageService = assertImages(images);
  const interfaceRef = normalizeObjectRef(callableInterface, 'image creation batch binding interface');
  const interfaceArtifact = await imageService.getCodeArtifact(interfaceRef.imageId, interfaceRef.objectId);
  if (!interfaceArtifact) {
    throw new TypeError(`callable interface not found: ${interfaceRef.imageId}/${interfaceRef.objectId}`);
  }
  const targetImageId = imageId ?? interfaceRef.imageId;
  const normalizedFields = normalizeBatchFields(fields, IMAGE_CREATION_BATCH_BINDING_V1);

  const {descriptor} = await resolveCallableInterface(
    imageService,
    {dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}]},
    IMAGE_CREATION_BATCH_BINDING_V1,
  );
  assertBatchCreationInterface(descriptor, normalizedFields);

  const bindingArtifact = await imageService.putCodeArtifact(targetImageId, {
    id: bindingId,
    representation: IMAGE_CREATION_BATCH_BINDING_V1,
    content: textValue(JSON.stringify({
      abi: IMAGE_CREATION_BATCH_BINDING_V1,
      fields: Object.fromEntries(Object.entries(normalizedFields).map(([classId, fields]) => [
        classId,
        fields.map((f) => (f.indexed ? {name: f.name, indexed: true, edge: f.edge} : {name: f.name, slot: f.slot, edge: f.edge})),
      ])),
    })),
    dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}],
    metadata: bindingMetadata,
  });
  const block = await imageService.putBlock(targetImageId, {
    id: blockId,
    code: objectRef(targetImageId, bindingArtifact.id),
    environment: null,
    metadata: blockMetadata,
  });
  return Object.freeze({bindingArtifact, block, interfaceRef});
}

// The local-name prefix for intra-batch edge references. `local:<name>` refers to the member whose
// `name` field equals <name>. This is request-syntax only; it never becomes a durable Value.
const LOCAL_PREFIX = 'local:';

function isLocalRef(text) {
  return typeof text === 'string' && text.startsWith(LOCAL_PREFIX);
}

function localNameOf(text) {
  return text.slice(LOCAL_PREFIX.length);
}

function createImageCreationBatchBindingV1Executor({newObjectId = randomUUID, maxIdentityAttempts = 8} = {}) {
  return Object.freeze({
    async execute({activation, code}, {images, require}) {
      if (!code || code.representation !== IMAGE_CREATION_BATCH_BINDING_V1) {
        throw new TypeError(`image creation batch executor requires ${IMAGE_CREATION_BATCH_BINDING_V1}`);
      }
      assertBlockApplicationReceiver(activation, IMAGE_CREATION_BATCH_BINDING_V1);
      if (activation.environment !== null) {
        throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} does not accept a lexical environment`);
      }
      const binding = parseImageCreationBatchBindingArtifact(code);
      const {descriptor} = await resolveCallableInterface(images, code, IMAGE_CREATION_BATCH_BINDING_V1);
      const record = assertBatchCreationInterface(descriptor, binding.fields);

      const args = assertCallableInterfaceArguments(descriptor, activation.arguments, descriptor.function);
      const imageId = code.imageId;

      const values = unpackCompositeValue(
        args[0], descriptor.parameters[0], descriptor.types ?? {}, `${descriptor.function} values`,
      );
      if (!Array.isArray(values) || values.length === 0) {
        throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} values must be a non-empty list`);
      }

      // Parse local names first: collect every member's `name` and reject duplicates. Names are
      // batch-global; a name collision across different classes is still a duplicate.
      const localNames = new Map();
      for (const [index, value] of values.entries()) {
        if (Object.hasOwn(value, 'name')) {
          const name = value.name;
          if (typeof name !== 'string' || name.length === 0) {
            throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member ${index} name must be a non-empty string`);
          }
          if (localNames.has(name)) {
            throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} duplicate local name: ${name}`);
          }
          localNames.set(name, index);
        }
      }

      // Phase A: authorize ALL and build ALL records before any durable write. Each member carries
      // its own class; require(object/create) fires per member's class (ADR 0067 §2a).
      const nil = objectRef(imageId, KERNEL_NIL_ID);
      const built = [];
      for (const [index, value] of values.entries()) {
        if (!Object.hasOwn(value, 'class')) {
          throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member ${index} must declare a class`);
        }
        const classId = value.class;
        if (typeof classId !== 'string' || classId.length === 0) {
          throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member ${index} class must be a non-empty string`);
        }
        const classFields = binding.fields[classId];
        if (!classFields) {
          throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member ${index} class ${classId} is not mapped by this binding`);
        }

        // Per-class require: object/create on this member's own class.
        require({operation: OBJECT_CREATE_OPERATION, resource: objectResource(imageId, classId)});

        // Then the class read, within the granted scope.
        const classRecord = await images.getObject(imageId, classId);
        if (!classRecord) throw new TypeError(`class not found: ${imageId}/${classId}`);
        const instanceShapeRef = assertBehaviorRecord(classRecord, imageId, classId);
        if (instanceShapeRef.objectId === KERNEL_NIL_ID) {
          throw new TypeError(`class ${imageId}/${classId} is not instantiable: instanceShape is nil`);
        }
        const shape = await images.getShape(instanceShapeRef.imageId, instanceShapeRef.objectId);
        if (!shape) throw new TypeError(`instance Shape not found: ${instanceShapeRef.imageId}/${instanceShapeRef.objectId}`);

        // Build the field mapping for this class directly from its normalized field list. The
        // member-record type is the union of all classes' fields; this class's mapping covers only
        // its own subset, so assertFieldMappingCovers (exact bidirectional coverage) is not the
        // right check here.
        const mapped = new Map(classFields.map((f) => [f.name, f.indexed ? {indexed: true, edge: f.edge} : {slot: f.slot, edge: f.edge}]));

        // Fail closed (ADR 0062 parity): the member-record type is the union of all classes'
        // fields, so a caller can set a field this member's class does NOT map — e.g. the
        // Perspective-only `presentations` edge field on a Presentation member. Dropping that
        // value silently would be fail-open (caller intent, possibly an edge reference, vanishing
        // without authorization or error). Reject any provided data key the class does not map,
        // before any slot is built, matching the single lane's "extra slot fails the shape match"
        // philosophy at the mapping layer.
        //
        // The composite codec requires every declared union field to be present on every member, so
        // a class-inappropriate field always arrives; the only value that carries NO caller intent
        // and NO edge reference is the empty list (the codec's zero for an indexed/list field). That
        // single case is tolerated. Everything else — a non-empty list (which could hold a ref or a
        // `local:` string) or any scalar (whose value is always caller-chosen, there being no zero
        // distinct from intent) — is rejected outright.
        for (const key of Object.keys(value)) {
          if (RESERVED_MEMBER_FIELDS.has(key)) continue;
          if (mapped.has(key)) continue;
          const supplied = value[key];
          const isCodecZeroList = Array.isArray(supplied) && supplied.length === 0;
          if (!isCodecZeroList) {
            throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} member ${index} supplies field ${key}, which class ${imageId}/${classId} does not map`);
          }
        }

        const slots = Object.fromEntries((shape.slots ?? []).map(({id}) => [id, nil]));
        const shapeSlotIds = new Set((shape.slots ?? []).map(({id}) => id));
        const isIndexed = shape.indexed === SHAPE_INDEXED.VALUES;
        let indexed = isIndexed ? [] : null;
        const localRefs = []; // {slotId, localName} or {indexedIndex, localName}

        for (const field of record.fields) {
          if (RESERVED_MEMBER_FIELDS.has(field.name)) continue;
          if (!Object.hasOwn(value, field.name)) continue;
          const mapping = mapped.get(field.name);
          // Unreachable for data keys (the fail-closed check above already rejected them); kept as
          // a defensive backstop so a future refactor cannot silently re-open the drop.
          if (!mapping) continue;
          if (mapping.indexed) {
            if (!isIndexed) {
              throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} supplies indexed field ${field.name}, but class ${imageId}/${classId} is not indexed`);
            }
            const listValue = value[field.name];
            if (!Array.isArray(listValue)) {
              throw new TypeError(`indexed field ${field.name} must be a list, got ${typeof listValue}`);
            }
            const elementType = resolveDeclaredType(field.type, descriptor.types ?? {}).element;
            indexed = listValue.map((element, elementIndex) => {
              const label = `indexed field ${field.name}[${elementIndex}]`;
              if (mapping.edge) {
                if (isLocalRef(element)) {
                  const name = localNameOf(element);
                  if (!localNames.has(name)) {
                    throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} unknown local name in ${label}: ${name}`);
                  }
                  localRefs.push({kind: 'indexed', index: elementIndex, localName: name});
                  return null; // placeholder, substituted in Phase B
                }
                const parsed = parseEdgeTarget(imageId, element, label);
                require({operation: OBJECT_EDGE_WRITE_OPERATION, resource: objectResource(imageId, parsed.objectId)});
                return parsed;
              }
              return hostLeafToCanonical(element, elementType, label);
            });
            continue;
          }
          const {slot, edge} = mapping;
          if (!shapeSlotIds.has(slot)) {
            throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} maps field ${field.name} to slot ${slot}, which the instance Shape does not declare`);
          }
          if (edge) {
            const text = value[field.name];
            if (isLocalRef(text)) {
              const name = localNameOf(text);
              if (!localNames.has(name)) {
                throw new TypeError(`${IMAGE_CREATION_BATCH_BINDING_V1} unknown local name in edge field ${field.name}: ${name}`);
              }
              localRefs.push({kind: 'slot', slotId: slot, localName: name});
              slots[slot] = null; // placeholder, substituted in Phase B
            } else {
              const parsed = parseEdgeTarget(imageId, text, `edge field ${field.name}`);
              require({operation: OBJECT_EDGE_WRITE_OPERATION, resource: objectResource(imageId, parsed.objectId)});
              slots[slot] = parsed;
            }
          } else {
            slots[slot] = hostLeafToCanonical(value[field.name], field.type, `field ${field.name}`);
          }
        }

        built.push({index, classId, instanceShapeRef, slots, indexed, localRefs});
      }

      // Phase B: mint all N ids and substitute local-name targets with the minted ids. On
      // VersionConflictError the whole putObjects transaction aborts; retry with freshly minted
      // ids, bounded by maxIdentityAttempts.
      for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
        const mintedIds = built.map(() => {
          const candidate = newObjectId();
          if (typeof candidate !== 'string' || candidate.length === 0) {
            throw new TypeError('object identity generator must answer non-empty text');
          }
          return candidate;
        });

        // Substitute local refs with minted ids and build the putObjects inputs.
        const inputs = [];
        for (const member of built) {
          const slots = {...member.slots};
          for (const ref of member.localRefs) {
            const targetIndex = localNames.get(ref.localName);
            const targetId = mintedIds[targetIndex];
            if (ref.kind === 'slot') {
              slots[ref.slotId] = objectRef(imageId, targetId);
            } else {
              member.indexed[ref.index] = objectRef(imageId, targetId);
            }
          }
          inputs.push({
            id: mintedIds[member.index],
            shape: member.instanceShapeRef,
            behavior: objectRef(imageId, member.classId),
            slots,
            ...(member.indexed === null ? {} : {indexed: member.indexed}),
            metadata: {},
          });
        }

        // Phase C: ONE backend.transaction committing all N put+append.
        try {
          const storedList = await images.putObjects(imageId, inputs, {expectedVersion: 0});
          const tokens = storedList.map((stored) => objectVersionToken(imageId, stored.id, stored._version));
          return textValue(tokens.join(','));
        } catch (error) {
          if (error?.name !== 'VersionConflictError') throw error;
          // A collision aborts the whole transaction; retry with freshly minted ids.
        }
      }
      throw new ObjectCreationConflictError(
        imageId,
        `could not find free object identities after ${maxIdentityAttempts} attempts`,
      );
    },
  });
}

export {
  IMAGE_CREATION_BATCH_BINDING_V1,
  OBJECT_CREATE_OPERATION,
  OBJECT_EDGE_WRITE_OPERATION,
  createImageCreationBatchBindingV1Executor,
  installImageCreationBatchBinding,
  parseImageCreationBatchBindingArtifact,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {isTransientObjectId} from '../value/transient-ref.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {objectRef, pinnedRef, textValue} from '../value/index.js';
import {assertBlockApplicationReceiver} from '../execution/block-application.js';
import {objectResource} from '../authority/object-resource.js';
import {objectVersionToken} from '../object/version-token.js';
import {
  CALLABLE_INTERFACE_DEPENDENCY_ROLE,
  assertBindingDependencies,
  normalizeObjectRef,
  resolveCallableInterface,
} from './binding-artifacts.js';
import {CALLABLE_TYPES, assertImages, hostLeafToCanonical} from './interface-artifacts.js';
import {assertCallableInterfaceArguments} from './interface-v2-artifacts.js';
import {unpackCompositeValue} from './composite-codec.js';
import {resolveDeclaredType} from './type-grammar.js';

// A fifth implementation lane: creating an image object, per ADR 0062. Symmetric with the
// projection/mutation lanes — an ordinary callable Block, nothing beyond `require` in the executor
// context, and no privileged write API for foreign code.
//
// The grant is per (image, class): `object/create` on `objectResource(imageId, classId)`. The lane
// derives `shape = class.instanceShape` and `behavior = class` exactly as `basicNew` does (ADR 0046),
// nil-fills the complete layout, mints the id itself, and commits insert-only in one transaction.
// Initial ref slots are authorized separately, per target, by `object/edge-write`.
const IMAGE_CREATION_BINDING_V1 = 'image-creation-binding/v1';
const OBJECT_CREATE_OPERATION = 'object/create';
const OBJECT_EDGE_WRITE_OPERATION = 'object/edge-write';

// The callable layer must not import `src/language` (it would close a dependency cycle through
// `src/execution` — see the composition-root note in runtime.js). These are the kernel's fixed,
// well-known ids, duplicated here with that constraint named. They are stable by ADR 0044 decision
// 1 (a Behavior's Shape never changes); if the kernel ever reissues them, this lane must move.
const BEHAVIOR_SHAPE_ID = 'smalltalk/behavior-shape/v1';
const BEHAVIOR_INSTANCE_SHAPE_SLOT = 'behavior-instance-shape';
const KERNEL_NIL_ID = 'smalltalk/nil';

// The string form of an edge field's value: either a plain object id (a plain ref) or
// `pin:<objectId>@<revision>` (a pinned ref). The callable type language has no ref type (ADR 0042
// §7), so a ref target can only arrive as text; the lane parses and canonicalizes it host-side.
const PIN_PREFIX = 'pin:';

class ObjectCreationConflictError extends Error {
  // The mutation lane translates VersionConflictError so the backend's actualVersion stays
  // unreachable. Here embedding the class/image id is safe: the caller already supplied the class id,
  // so nothing new leaks. The terminal id-exhaustion path reports only the attempt count.
  constructor(imageId, detail) {
    super(`object creation conflict in ${imageId}: ${detail}`);
    this.name = 'ObjectCreationConflictError';
    this.imageId = imageId;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

// Field mapping, mirroring the mutation lane's, plus two optional flags. `edge: true` marks a slot
// field whose string value is a ref *target id*: the lane canonicalizes it to a ref/pinned-ref and
// requires a separate per-target `object/edge-write` grant. A non-edge field stores its string as
// text and can never mint a graph edge — the composite codec already refuses embedded refs.
//
// ADR 0064: a field marked `indexed: true` is the indexed-part field. It names no slot; its value
// is a `list<leaf-or-ref-string>` whose elements populate the ordered indexed part. At most one
// field may be the indexed field, and it is mutually exclusive with naming a `slot`. `edge` on the
// indexed field marks a ref-list: every (string) element is a ref target authorized per-element;
// without `edge` it is a leaf-list.
function normalizeCreationFields(values, label) {
  if (!Array.isArray(values) || values.length === 0) {
    throw new TypeError(`${label} fields must be a non-empty array`);
  }
  const names = new Set();
  const slots = new Set();
  let indexedField = null;
  const normalized = values.map((entry, index) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError(`${label} field ${index} must be an object`);
    }
    const keys = Object.keys(entry).sort();
    const allowed = ['edge', 'indexed', 'name', 'slot'];
    if (!keys.includes('name') || keys.some((key) => !allowed.includes(key))) {
      throw new TypeError(`${label} field ${index} must contain name, optionally slot, and optionally edge/indexed`);
    }
    const name = requiredText(entry.name, `${label} field ${index} name`);
    const edge = entry.edge === undefined ? false : entry.edge === true;
    const indexed = entry.indexed === undefined ? false : entry.indexed === true;
    if (typeof edge !== 'boolean') throw new TypeError(`${label} field ${index} edge must be a boolean when present`);
    if (typeof indexed !== 'boolean') throw new TypeError(`${label} field ${index} indexed must be a boolean when present`);
    if (names.has(name)) throw new TypeError(`${label} maps field ${name} twice`);
    names.add(name);

    if (indexed) {
      // The indexed field names no slot. `edge` on it marks a ref-list: every (string) element is a
      // ref target authorized per-element. Without `edge` it is a leaf-list. There is exactly one.
      if (Object.hasOwn(entry, 'slot')) throw new TypeError(`${label} indexed field ${name} must not name a slot`);
      if (indexedField) throw new TypeError(`${label} declares a second indexed field ${name}; at most one is allowed`);
      indexedField = name;
      return Object.freeze({name, indexed: true, edge});
    }

    // A slot field: stable slot IDs, not slot names — a rename must not change what a creation writes.
    if (!keys.includes('slot')) throw new TypeError(`${label} field ${index} (${name}) must name a slot unless it is the indexed field`);
    const slot = requiredText(entry.slot, `${label} field ${index} slot`);
    if (slots.has(slot)) throw new TypeError(`${label} maps slot ${slot} twice`);
    slots.add(slot);
    return Object.freeze({name, slot, edge});
  });
  return Object.freeze(normalized);
}

function parseImageCreationBindingArtifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== IMAGE_CREATION_BINDING_V1) {
    throw new TypeError(`artifact must be ${IMAGE_CREATION_BINDING_V1}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError('image creation binding content must be a text Value');
  assertBindingDependencies(artifact, [CALLABLE_INTERFACE_DEPENDENCY_ROLE], IMAGE_CREATION_BINDING_V1);
  let decoded;
  try {
    decoded = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError('image creation binding content must be valid JSON', {cause: error});
  }
  const expected = ['abi', 'fields'];
  const actual = Object.keys(decoded).sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`${IMAGE_CREATION_BINDING_V1} descriptor must contain exactly ${expected.join(', ')}`);
  }
  if (decoded.abi !== IMAGE_CREATION_BINDING_V1) {
    throw new TypeError(`unsupported image creation binding ABI: ${decoded.abi}`);
  }
  return Object.freeze({fields: normalizeCreationFields(decoded.fields, IMAGE_CREATION_BINDING_V1)});
}

// create-item(class-id: string, value: <record>) -> string (the initial object-scoped version token)
// `fields` is the binding's field mapping, so the indexed field's list type can be carved out of the
// leaf-type rule precisely: only the field the binding marks `indexed` may be a non-leaf list.
function assertCreationInterface(descriptor, fields = []) {
  const {parameters, result, types = {}} = descriptor;
  if (parameters.length !== 2 || parameters[0] !== 'string') {
    throw new TypeError(
      `${IMAGE_CREATION_BINDING_V1} requires parameters (class-id: string, value: record)`,
    );
  }
  if (result !== 'string') {
    throw new TypeError(`${IMAGE_CREATION_BINDING_V1} must return the initial version token as string`);
  }
  const record = resolveDeclaredType(parameters[1], types);
  if (!record || record.kind !== 'record') {
    throw new TypeError(`${IMAGE_CREATION_BINDING_V1} value parameter must be a declared record type`);
  }
  const indexedFields = new Map(fields.filter((f) => f.indexed).map((f) => [f.name, f.edge]));
  for (const field of record.fields) {
    if (indexedFields.has(field.name)) {
      assertIndexedFieldType(field, types, `${IMAGE_CREATION_BINDING_V1} indexed field ${field.name}`, indexedFields.get(field.name));
      continue;
    }
    // Ref targets travel as strings; every other field must be a leaf type (no nested writes in v1).
    if (!CALLABLE_TYPES.includes(field.type)) {
      throw new TypeError(
        `${IMAGE_CREATION_BINDING_V1} field ${field.name} must be a leaf type; v1 does not write nested values`,
      );
    }
  }
  return record;
}

// ADR 0064 §1: the indexed field is a `list` whose elements are leaf scalars or ref-target strings —
// never a nested record/list (that would violate ADR 0035's Value model). `list<u8>` is bytes, not
// an element list, so it is refused here for the same reason it is not a slot. An `edge` indexed
// field is a ref-list: its elements are ref-target strings, so its element type must be `string`.
function assertIndexedFieldType(field, types, label, edge) {
  const resolved = resolveDeclaredType(field.type, types);
  if (!resolved || resolved.kind !== 'list') {
    throw new TypeError(`${label} must be a {kind:'list', element:<leaf>} type`);
  }
  const element = resolveDeclaredType(resolved.element, types);
  if (typeof element !== 'string' || !CALLABLE_TYPES.includes(element) || element === 'list<u8>') {
    throw new TypeError(`${label} element must be a leaf scalar (bool/s32/s64/f32/f64/string); nested composites are not writable`);
  }
  if (edge && element !== 'string') {
    throw new TypeError(`${label} is an edge (ref) list, so its element type must be string, got ${element}`);
  }
}

function assertFieldMappingCovers(record, fields, label) {
  const mapped = new Map(fields.map((f) => [f.name, f.indexed ? {indexed: true, edge: f.edge} : {slot: f.slot, edge: f.edge}]));
  for (const field of record.fields) {
    if (!mapped.has(field.name)) throw new TypeError(`${label} does not map record field ${field.name}`);
  }
  for (const name of mapped.keys()) {
    if (!record.fields.some((field) => field.name === name)) {
      throw new TypeError(`${label} maps ${name}, which the interface record does not declare`);
    }
  }
  return mapped;
}

async function installImageCreationBinding({
  images,
  callableInterface,
  fields,
  imageId = null,
  bindingId = randomUUID(),
  blockId = randomUUID(),
  bindingMetadata = {},
  blockMetadata = {},
} = {}) {
  const imageService = assertImages(images);
  const interfaceRef = normalizeObjectRef(callableInterface, 'image creation binding interface');
  const interfaceArtifact = await imageService.getCodeArtifact(interfaceRef.imageId, interfaceRef.objectId);
  if (!interfaceArtifact) {
    throw new TypeError(`callable interface not found: ${interfaceRef.imageId}/${interfaceRef.objectId}`);
  }
  const targetImageId = imageId ?? interfaceRef.imageId;
  const normalizedFields = normalizeCreationFields(fields, IMAGE_CREATION_BINDING_V1);

  const {descriptor} = await resolveCallableInterface(
    imageService,
    {dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}]},
    IMAGE_CREATION_BINDING_V1,
  );
  assertFieldMappingCovers(assertCreationInterface(descriptor, normalizedFields), normalizedFields, IMAGE_CREATION_BINDING_V1);

  const bindingArtifact = await imageService.putCodeArtifact(targetImageId, {
    id: bindingId,
    representation: IMAGE_CREATION_BINDING_V1,
    content: textValue(JSON.stringify({
      abi: IMAGE_CREATION_BINDING_V1,
      fields: normalizedFields.map((f) => (f.indexed ? {name: f.name, indexed: true, edge: f.edge} : {name: f.name, slot: f.slot, edge: f.edge})),
    })),
    dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}],
    metadata: bindingMetadata,
  });
  const block = await imageService.putBlock(targetImageId, {
    id: blockId,
    code: objectRef(targetImageId, bindingArtifact.id),
    environment: null,
    metadata: blockMetadata,
  });
  return Object.freeze({bindingArtifact, block, interfaceRef});
}

// Parse an edge field's string into a canonical ref or pinned-ref in `imageId`, enforcing that the
// target is durable (never a reserved transient id) before any grant check or write.
function parseEdgeTarget(imageId, text, label) {
  if (text.startsWith(PIN_PREFIX)) {
    const rest = text.slice(PIN_PREFIX.length);
    const at = rest.lastIndexOf('@');
    if (at <= 0 || at === rest.length - 1) {
      throw new TypeError(`${label} must be pin:<object-id>@<revision>, got ${text}`);
    }
    const objectId = rest.slice(0, at);
    const revision = rest.slice(at + 1);
    if (isTransientObjectId(objectId)) {
      throw new ObjectCreationConflictError(imageId, `edge target ${objectId} is transient; only durable objects can be edge targets`);
    }
    return pinnedRef(imageId, objectId, revision);
  }
  if (isTransientObjectId(text)) {
    throw new ObjectCreationConflictError(imageId, `edge target ${text} is transient; only durable objects can be edge targets`);
  }
  return objectRef(imageId, text);
}

// ADR 0064 §2–3. Build the ordered indexed part from the field's list value. Each element is either
// a leaf scalar (canonicalized host-side, no edge) or — when the binding marks the field `edge` — a
// ref-target string canonicalized with a separate per-target `object/edge-write` grant. The grant
// fires at exactly the canonicalize step, so no edge is created without it, and a transient-looking
// element is refused before any write (parseEdgeTarget), with the write-seam guard as backstop.
function buildIndexedPart(imageId, listValue, field, edge, types, require) {
  if (!Array.isArray(listValue)) {
    throw new TypeError(`indexed field ${field.name} must be a list, got ${typeof listValue}`);
  }
  const elementType = resolveDeclaredType(field.type, types).element;
  return listValue.map((element, index) => {
    const label = `indexed field ${field.name}[${index}]`;
    if (edge) {
      const parsed = parseEdgeTarget(imageId, element, label);
      require({operation: OBJECT_EDGE_WRITE_OPERATION, resource: objectResource(imageId, parsed.objectId)});
      return parsed;
    }
    return hostLeafToCanonical(element, elementType, label);
  });
}

// A Behavior is a record in THIS image whose Shape is THIS image's fixed behavior Shape, and whose
// instanceShape slot is a local unpinned ref (or nil). This is `isBehaviorObject` plus the
// instanceShape half of `readBehavior` — deliberately narrower than `readBehavior`, which also
// checks name/superclass/methods. Creation never reads those, so a Behavior with a foreign methods
// edge is usable here even though `readBehavior` would refuse it; that is intentional, not a gap.
function assertBehaviorRecord(record, imageId, classId) {
  const shapeRef = record.shape;
  const isLocalBehaviorShape = shapeRef
    && shapeRef.kind === 'ref'
    && shapeRef.imageId === imageId
    && shapeRef.objectId === BEHAVIOR_SHAPE_ID;
  if (!isLocalBehaviorShape) {
    throw new TypeError(`object ${imageId}/${classId} is not a Behavior in ${imageId}`);
  }
  const instanceShapeRef = record.slots?.[BEHAVIOR_INSTANCE_SHAPE_SLOT];
  if (instanceShapeRef === undefined || instanceShapeRef.kind !== 'ref' || instanceShapeRef.imageId !== imageId) {
    throw new TypeError(`Behavior ${imageId}/${classId} has no local instanceShape`);
  }
  return instanceShapeRef;
}

function createImageCreationBindingV1Executor({newObjectId = randomUUID, maxIdentityAttempts = 8} = {}) {
  return Object.freeze({
    async execute({activation, code}, {images, require}) {
      if (!code || code.representation !== IMAGE_CREATION_BINDING_V1) {
        throw new TypeError(`image creation executor requires ${IMAGE_CREATION_BINDING_V1}`);
      }
      assertBlockApplicationReceiver(activation, IMAGE_CREATION_BINDING_V1);
      if (activation.environment !== null) {
        throw new TypeError(`${IMAGE_CREATION_BINDING_V1} does not accept a lexical environment`);
      }
      const binding = parseImageCreationBindingArtifact(code);
      const {descriptor} = await resolveCallableInterface(images, code, IMAGE_CREATION_BINDING_V1);
      const record = assertCreationInterface(descriptor, binding.fields);
      const mapped = assertFieldMappingCovers(record, binding.fields, IMAGE_CREATION_BINDING_V1);

      const args = assertCallableInterfaceArguments(descriptor, activation.arguments, descriptor.function);
      const classId = args[0].value;
      // The image comes from the binding, never the caller.
      const imageId = code.imageId;

      // Authority first: a caller without object/create learns nothing, not even whether the class
      // exists. This is the only grant needed to create with no edges.
      require({operation: OBJECT_CREATE_OPERATION, resource: objectResource(imageId, classId)});

      // Then the class read, within the granted scope: naming a wrong id is an existence oracle over
      // ids the caller already supplied, which ADR 0062 §3 accepts.
      const classRecord = await images.getObject(imageId, classId);
      if (!classRecord) throw new TypeError(`class not found: ${imageId}/${classId}`);
      const instanceShapeRef = assertBehaviorRecord(classRecord, imageId, classId);
      if (instanceShapeRef.objectId === KERNEL_NIL_ID) {
        throw new TypeError(`class ${imageId}/${classId} is not instantiable: instanceShape is nil`);
      }
      const shape = await images.getShape(instanceShapeRef.imageId, instanceShapeRef.objectId);
      if (!shape) throw new TypeError(`instance Shape not found: ${instanceShapeRef.imageId}/${instanceShapeRef.objectId}`);

      const value = unpackCompositeValue(
        args[1], descriptor.parameters[1], descriptor.types ?? {}, `${descriptor.function} value`,
      );

      // Build the complete layout: every Shape slot nil-filled (as basicNew), then the mapped
      // fields. A field for a slot the Shape does not declare is an extra slot and fails the shape
      // match below; a non-edge field stores text and can never mint an edge.
      const nil = objectRef(imageId, KERNEL_NIL_ID);
      const slots = Object.fromEntries((shape.slots ?? []).map(({id}) => [id, nil]));
      const shapeSlotIds = new Set((shape.slots ?? []).map(({id}) => id));
      // ADR 0064: the indexed part is built from the indexed field's list, not nil-filled. An indexed
      // class with no indexed field supplied begins at the zero-length form (basicNew parity).
      const isIndexed = shape.indexed === SHAPE_INDEXED.VALUES;
      let indexed = isIndexed ? [] : null;
      for (const field of record.fields) {
        if (!Object.hasOwn(value, field.name)) continue;
        const mapping = mapped.get(field.name);
        if (mapping.indexed) {
          // The indexed field routes to the indexed part. Refusing a non-indexed class here — before
          // any element is authorized or written — keeps the failure clean rather than a shape-match
          // surprise at commit (ADR 0064 §1).
          if (!isIndexed) {
            throw new TypeError(`${IMAGE_CREATION_BINDING_V1} supplies indexed field ${field.name}, but class ${imageId}/${classId} is not indexed`);
          }
          indexed = buildIndexedPart(imageId, value[field.name], field, mapping.edge, descriptor.types ?? {}, require);
          continue;
        }
        const {slot, edge} = mapping;
        if (!shapeSlotIds.has(slot)) {
          throw new TypeError(`${IMAGE_CREATION_BINDING_V1} maps field ${field.name} to slot ${slot}, which the instance Shape does not declare`);
        }
        if (edge) {
          // A separate per-target grant: create-on-class must not become broad reach (ADR 0042 §7).
          // Parse first, then authorize the canonical TARGET id — for a pinned spelling the raw
          // string is `pin:<id>@<revision>`, and the grant is scoped to the target, not the pin text.
          const parsed = parseEdgeTarget(imageId, value[field.name], `edge field ${field.name}`);
          require({operation: OBJECT_EDGE_WRITE_OPERATION, resource: objectResource(imageId, parsed.objectId)});
          slots[slot] = parsed;
        } else {
          slots[slot] = hostLeafToCanonical(value[field.name], field.type, `field ${field.name}`);
        }
      }

      // The lane mints the candidate id and passes it explicitly — never putObject's default — so a
      // retry after a lost acknowledgement preserves the identity (ADR 0046 §6). Insert-only, and
      // state + history commit in one backend transaction (or neither) via putWithHistory.
      const behavior = objectRef(imageId, classId);
      for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
        const candidate = newObjectId();
        if (typeof candidate !== 'string' || candidate.length === 0) {
          throw new TypeError('object identity generator must answer non-empty text');
        }
        try {
          const stored = await images.putObject(imageId, {
            id: candidate,
            shape: instanceShapeRef,
            behavior,
            slots,
            ...(indexed === null ? {} : {indexed}),
            metadata: {},
          }, {expectedVersion: 0});
          return textValue(objectVersionToken(imageId, stored.id, stored._version));
        } catch (error) {
          if (error?.name !== 'VersionConflictError') throw error;
        }
      }
      throw new ObjectCreationConflictError(
        imageId,
        `could not find a free object identity after ${maxIdentityAttempts} attempts`,
      );
    },
  });
}

export {
  BEHAVIOR_SHAPE_ID,
  IMAGE_CREATION_BINDING_V1,
  KERNEL_NIL_ID,
  OBJECT_CREATE_OPERATION,
  OBJECT_EDGE_WRITE_OPERATION,
  ObjectCreationConflictError,
  assertBehaviorRecord,
  assertCreationInterface,
  assertFieldMappingCovers,
  assertIndexedFieldType,
  buildIndexedPart,
  createImageCreationBindingV1Executor,
  installImageCreationBinding,
  normalizeCreationFields,
  parseEdgeTarget,
  parseImageCreationBindingArtifact,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {canonicalizeValue, isReference, objectRef, pinnedRef, textValue} from '../value/index.js';
import {isTransientObjectId} from '../value/transient-ref.js';
import {assertBlockApplicationReceiver} from '../execution/block-application.js';
import {OBJECT_WRITE_OPERATION, objectResource} from '../authority/object-resource.js';
import {
  ObjectMutationConflictError,
  objectVersionToken,
  parseObjectVersionToken,
  putObjectAtExpectedVersion,
} from '../object/version-token.js';
import {
  CALLABLE_INTERFACE_DEPENDENCY_ROLE,
  assertBindingDependencies,
  normalizeObjectRef,
  resolveCallableInterface,
} from './binding-artifacts.js';
import {CALLABLE_TYPES, assertImages, hostLeafToCanonical} from './interface-artifacts.js';
import {assertCallableInterfaceArguments} from './interface-v2-artifacts.js';
import {unpackCompositeValue} from './composite-codec.js';
import {resolveDeclaredType} from './type-grammar.js';

// A fourth implementation lane: mutating an image object, per ADR 0042. Symmetric with the
// projection lane — an ordinary callable Block, nothing beyond `require` in the executor
// context, and no privileged write API for foreign code.
const IMAGE_MUTATION_BINDING_V1 = 'image-mutation-binding/v1';
// ADR 0065 §2: adding a ref element to an existing object's indexed part is edge creation, honored
// per ADR 0042 §7 with the same per-target grant creation uses (ADR 0062 §4) — never plain object/write.
const OBJECT_EDGE_WRITE_OPERATION = 'object/edge-write';
const PIN_PREFIX = 'pin:';

// A stale token surfaces as ObjectMutationConflictError, translated by the ONE conditional
// persistence seam (`putObjectAtExpectedVersion`, src/object/version-token.js): a conflict says
// only that the caller's assumption was stale. OBJECT_WRITE_OPERATION and the error class are
// re-exported from here for existing consumers; their owners are the authority resource module
// and the version-token module.

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

// ADR 0065: a field marked `indexed: true` is the indexed-part field. It names no slot; its value
// is a ref-free `list` replacing the indexed part under the version-token CAS. `edge` on it marks a
// ref-list (each added string element is a ref target, authorized per-target). At most one indexed
// field per binding; it is mutually exclusive with naming a slot. A plain `{name, slot}` field is a
// leaf slot write exactly as ADR 0042.
function normalizeMutationFields(values, label) {
  if (!Array.isArray(values) || values.length === 0) {
    throw new TypeError(`${label} fields must be a non-empty array`);
  }
  const names = new Set();
  const slots = new Set();
  let indexedField = null;
  const normalized = values.map((entry, index) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError(`${label} field ${index} must be an object`);
    }
    const keys = Object.keys(entry).sort();
    const allowed = ['edge', 'indexed', 'name', 'slot'];
    if (!keys.includes('name') || keys.some((key) => !allowed.includes(key))) {
      throw new TypeError(`${label} field ${index} must contain name, optionally slot, and optionally edge/indexed`);
    }
    const name = requiredText(entry.name, `${label} field ${index} name`);
    const edge = entry.edge === undefined ? false : entry.edge === true;
    const indexed = entry.indexed === undefined ? false : entry.indexed === true;
    if (typeof edge !== 'boolean') throw new TypeError(`${label} field ${index} edge must be a boolean when present`);
    if (typeof indexed !== 'boolean') throw new TypeError(`${label} field ${index} indexed must be a boolean when present`);
    if (names.has(name)) throw new TypeError(`${label} maps field ${name} twice`);
    names.add(name);

    if (indexed) {
      if (Object.hasOwn(entry, 'slot')) throw new TypeError(`${label} indexed field ${name} must not name a slot`);
      if (indexedField) throw new TypeError(`${label} declares a second indexed field ${name}; at most one is allowed`);
      indexedField = name;
      return Object.freeze({name, indexed: true, edge});
    }

    // A leaf slot field. Stable slot IDs, not slot names: a rename must not change what a mutation writes.
    if (edge) throw new TypeError(`${label} slot field ${name} must not be an edge field; v1 slot writes are leaf-only (ADR 0042 §7)`);
    if (!keys.includes('slot')) throw new TypeError(`${label} field ${index} (${name}) must name a slot unless it is the indexed field`);
    const slot = requiredText(entry.slot, `${label} field ${index} slot`);
    if (slots.has(slot)) throw new TypeError(`${label} maps slot ${slot} twice`);
    slots.add(slot);
    return Object.freeze({name, slot});
  });
  return Object.freeze(normalized);
}

function parseImageMutationBindingArtifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== IMAGE_MUTATION_BINDING_V1) {
    throw new TypeError(`artifact must be ${IMAGE_MUTATION_BINDING_V1}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError('image mutation binding content must be a text Value');
  assertBindingDependencies(artifact, [CALLABLE_INTERFACE_DEPENDENCY_ROLE], IMAGE_MUTATION_BINDING_V1);
  let decoded;
  try {
    decoded = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError('image mutation binding content must be valid JSON', {cause: error});
  }
  const expected = ['abi', 'fields'];
  const actual = Object.keys(decoded).sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`${IMAGE_MUTATION_BINDING_V1} descriptor must contain exactly ${expected.join(', ')}`);
  }
  if (decoded.abi !== IMAGE_MUTATION_BINDING_V1) {
    throw new TypeError(`unsupported image mutation binding ABI: ${decoded.abi}`);
  }
  return Object.freeze({fields: normalizeMutationFields(decoded.fields, IMAGE_MUTATION_BINDING_V1)});
}

// write-item(object-id: string, version-token: string, value: <record>) -> string
// `fields` is the binding's field mapping, so the indexed field's list type can be carved out of the
// leaf-type rule precisely: only the field the binding marks `indexed` may be a non-leaf list.
function assertMutationInterface(descriptor, fields = []) {
  const {parameters, result, types = {}} = descriptor;
  if (parameters.length !== 3 || parameters[0] !== 'string' || parameters[1] !== 'string') {
    throw new TypeError(
      `${IMAGE_MUTATION_BINDING_V1} requires parameters (object-id: string, version-token: string, value: record)`,
    );
  }
  if (result !== 'string') {
    throw new TypeError(`${IMAGE_MUTATION_BINDING_V1} must return the next version token as string`);
  }
  const record = resolveDeclaredType(parameters[2], types);
  if (!record || record.kind !== 'record') {
    throw new TypeError(`${IMAGE_MUTATION_BINDING_V1} value parameter must be a declared record type`);
  }
  const indexedFields = new Map(fields.filter((f) => f.indexed).map((f) => [f.name, f.edge]));
  for (const field of record.fields) {
    if (indexedFields.has(field.name)) {
      assertIndexedFieldType(field, types, `${IMAGE_MUTATION_BINDING_V1} indexed field ${field.name}`, indexedFields.get(field.name));
      continue;
    }
    if (!CALLABLE_TYPES.includes(field.type)) {
      throw new TypeError(
        `${IMAGE_MUTATION_BINDING_V1} field ${field.name} must be a leaf type; v1 does not write nested values`,
      );
    }
  }
  return record;
}

// ADR 0065 §1: the indexed field is a ref-free `list` whose elements are leaf scalars or (for an
// `edge` list) ref-target strings — never a nested composite (ADR 0035). An `edge` list's element
// must be `string`, since ref targets travel as strings (ADR 0042 §7).
function assertIndexedFieldType(field, types, label, edge) {
  const resolved = resolveDeclaredType(field.type, types);
  if (!resolved || resolved.kind !== 'list') {
    throw new TypeError(`${label} must be a {kind:'list', element:<leaf>} type`);
  }
  const element = resolveDeclaredType(resolved.element, types);
  if (typeof element !== 'string' || !CALLABLE_TYPES.includes(element) || element === 'list<u8>') {
    throw new TypeError(`${label} element must be a leaf scalar (bool/s32/s64/f32/f64/string); nested composites are not writable`);
  }
  if (edge && element !== 'string') {
    throw new TypeError(`${label} is an edge (ref) list, so its element type must be string, got ${element}`);
  }
}

function assertFieldMappingCovers(record, fields, label) {
  const mapped = new Map(fields.map((f) => [f.name, f.indexed ? {indexed: true, edge: f.edge} : {slot: f.slot}]));
  for (const field of record.fields) {
    if (!mapped.has(field.name)) throw new TypeError(`${label} does not map record field ${field.name}`);
  }
  for (const name of mapped.keys()) {
    if (!record.fields.some((field) => field.name === name)) {
      throw new TypeError(`${label} maps ${name}, which the interface record does not declare`);
    }
  }
  return mapped;
}

async function installImageMutationBinding({
  images,
  callableInterface,
  fields,
  imageId = null,
  bindingId = randomUUID(),
  blockId = randomUUID(),
  bindingMetadata = {},
  blockMetadata = {},
} = {}) {
  const imageService = assertImages(images);
  const interfaceRef = normalizeObjectRef(callableInterface, 'image mutation binding interface');
  const interfaceArtifact = await imageService.getCodeArtifact(interfaceRef.imageId, interfaceRef.objectId);
  if (!interfaceArtifact) {
    throw new TypeError(`callable interface not found: ${interfaceRef.imageId}/${interfaceRef.objectId}`);
  }
  const targetImageId = imageId ?? interfaceRef.imageId;
  const normalizedFields = normalizeMutationFields(fields, IMAGE_MUTATION_BINDING_V1);

  const {descriptor} = await resolveCallableInterface(
    imageService,
    {dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}]},
    IMAGE_MUTATION_BINDING_V1,
  );
  assertFieldMappingCovers(assertMutationInterface(descriptor, normalizedFields), normalizedFields, IMAGE_MUTATION_BINDING_V1);

  const bindingArtifact = await imageService.putCodeArtifact(targetImageId, {
    id: bindingId,
    representation: IMAGE_MUTATION_BINDING_V1,
    content: textValue(JSON.stringify({
      abi: IMAGE_MUTATION_BINDING_V1,
      fields: normalizedFields.map((f) => (f.indexed ? {name: f.name, indexed: true, edge: f.edge} : {name: f.name, slot: f.slot})),
    })),
    dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}],
    metadata: bindingMetadata,
  });
  const block = await imageService.putBlock(targetImageId, {
    id: blockId,
    code: objectRef(targetImageId, bindingArtifact.id),
    environment: null,
    metadata: blockMetadata,
  });
  return Object.freeze({bindingArtifact, block, interfaceRef});
}

// Parse an added ref element's string into a canonical ref/pinned-ref, refusing a transient target
// before any grant check or write (the write-seam guard is the backstop). Same seam as creation.
function parseEdgeTarget(imageId, text, label) {
  if (text.startsWith(PIN_PREFIX)) {
    const rest = text.slice(PIN_PREFIX.length);
    const at = rest.lastIndexOf('@');
    if (at <= 0 || at === rest.length - 1) {
      throw new TypeError(`${label} must be pin:<object-id>@<revision>, got ${text}`);
    }
    const objectId = rest.slice(0, at);
    const revision = rest.slice(at + 1);
    if (isTransientObjectId(objectId)) {
      throw new TypeError(`${label} target ${objectId} is transient; only durable objects can be edge targets`);
    }
    return pinnedRef(imageId, objectId, revision);
  }
  if (isTransientObjectId(text)) {
    throw new TypeError(`${label} target ${text} is transient; only durable objects can be edge targets`);
  }
  return objectRef(imageId, text);
}

// ADR 0065 §3 element identity: canonical-Value identity. Two refs are the same element iff they
// share (imageId, objectId); two pinned-refs iff they also share revision; a ref never equals a
// pinned-ref; two leaves iff canonically equal. This is what makes the no-removal and reorder rules
// sound (a ref->pin swap is a removal + addition, not a no-op re-pin).
function sameElement(left, right) {
  const a = canonicalizeValue(left);
  const b = canonicalizeValue(right);
  if (a.kind !== b.kind) return false;
  if (a.kind === 'ref') return a.imageId === b.imageId && a.objectId === b.objectId;
  if (a.kind === 'pinned-ref') {
    return a.imageId === b.imageId && a.objectId === b.objectId && a.revision === b.revision;
  }
  return JSON.stringify(a) === JSON.stringify(b);
}

// Count how many elements of `list` match `element` under sameElement (multiset membership). An
// explicit loop, because this counter is the no-removal invariant's enforcement: a miscount is not a
// list bug but an authority-semantics bug (a caller could drop an edge without the removal authority).
function countOf(list, element) {
  let count = 0;
  for (const candidate of list) {
    if (sameElement(candidate, element)) count += 1;
  }
  return count;
}

// ADR 0065 §2–3. Validate and build the replacement indexed part. The new list may append leaf
// elements (object/write alone), append ref elements (each authorized per-target), and reorder —
// but must contain every element of the old part (multiset), so it can never remove an edge. Added
// refs are canonicalized with the per-target grant firing at that point.
function buildNewIndexedPart(imageId, oldIndexed, listValue, field, edge, types, require) {
  if (!Array.isArray(listValue)) {
    throw new TypeError(`indexed field ${field.name} must be a list, got ${typeof listValue}`);
  }
  const elementType = resolveDeclaredType(field.type, types).element;
  // Canonicalize the new list: leaves host-side, added ref targets parsed (transient refused here).
  const newElements = listValue.map((element, index) => {
    const label = `indexed field ${field.name}[${index}]`;
    if (!edge) return hostLeafToCanonical(element, elementType, label);
    return {added: parseEdgeTarget(imageId, element, label)};
  });

  if (edge) {
    // For each old element, it must still be present in the new list (by identity); if so, the new
    // list reuses the OLD canonical element (preserving its exact form). Anything in the new list
    // not matched to an old element is an ADDED ref and needs the per-target grant.
    const oldList = oldIndexed ?? [];
    const result = [];
    const usedOld = new Array(oldList.length).fill(false);
    for (const {added} of newElements) {
      const matchIndex = oldList.findIndex((oldEl, i) => !usedOld[i] && sameElement(oldEl, added));
      if (matchIndex >= 0) {
        usedOld[matchIndex] = true;
        result.push(canonicalizeValue(oldList[matchIndex]));
      } else {
        // An added edge: authorize the parsed target before committing it.
        require({operation: OBJECT_EDGE_WRITE_OPERATION, resource: objectResource(imageId, added.objectId)});
        result.push(added);
      }
    }
    // No-removal: every old element must have been matched.
    if (usedOld.some((used) => !used)) {
      const missing = oldList.filter((_, i) => !usedOld[i]).map((el) => canonicalizeValue(el).objectId ?? '?');
      throw new TypeError(
        `${IMAGE_MUTATION_BINDING_V1} cannot remove indexed element(s) ${missing.join(', ')}: element removal is edge removal, deferred (ADR 0065 §3)`,
      );
    }
    return result;
  }

  // A leaf list: no edges anywhere, so any list is allowed — but no-removal still holds, so the new
  // list must contain every old element (by canonical identity).
  const oldList = oldIndexed ?? [];
  for (const oldEl of oldList) {
    if (countOf(newElements, oldEl) < countOf(oldList, oldEl)) {
      throw new TypeError(
        `${IMAGE_MUTATION_BINDING_V1} cannot remove an indexed element: element removal is edge removal, deferred (ADR 0065 §3)`,
      );
    }
  }
  return newElements;
}

function createImageMutationBindingV1Executor() {
  return Object.freeze({
    async execute({activation, code}, {images, require}) {
      if (!code || code.representation !== IMAGE_MUTATION_BINDING_V1) {
        throw new TypeError(`image mutation executor requires ${IMAGE_MUTATION_BINDING_V1}`);
      }
      assertBlockApplicationReceiver(activation, IMAGE_MUTATION_BINDING_V1);
      if (activation.environment !== null) {
        throw new TypeError(`${IMAGE_MUTATION_BINDING_V1} does not accept a lexical environment`);
      }
      const binding = parseImageMutationBindingArtifact(code);
      const {descriptor} = await resolveCallableInterface(images, code, IMAGE_MUTATION_BINDING_V1);
      const record = assertMutationInterface(descriptor, binding.fields);
      const mapped = assertFieldMappingCovers(record, binding.fields, IMAGE_MUTATION_BINDING_V1);

      const args = assertCallableInterfaceArguments(descriptor, activation.arguments, descriptor.function);
      const objectId = args[0].value;
      const token = args[1].value;
      // The image comes from the binding, never the caller.
      const imageId = code.imageId;

      // Authority first: a caller without object/write learns nothing, not even whether the
      // object exists. object/write alone suffices — the read below is read-for-write and is
      // not an exposure of state to the caller.
      require({operation: OBJECT_WRITE_OPERATION, resource: objectResource(imageId, objectId)});

      // Then the token, still before any fetch. A token issued for another object fails here
      // rather than silently matching a coincidentally equal version.
      const expectedVersion = parseObjectVersionToken(token, imageId, objectId);

      const value = unpackCompositeValue(
        args[2], descriptor.parameters[2], descriptor.types ?? {}, `${descriptor.function} value`,
      );

      const object = await images.getObject(imageId, objectId);
      if (!object) throw new TypeError(`object not found: ${imageId}/${objectId}`);

      // Unmapped slots are preserved rather than cleared.
      const slots = {...(object.slots ?? {})};
      // ADR 0065: when the binding has an indexed field, the indexed part is replaced by the field's
      // list (append/reorder, never shrink); otherwise it is preserved verbatim as before.
      let indexed = Object.hasOwn(object, 'indexed') ? object.indexed : undefined;
      for (const field of record.fields) {
        const mapping = mapped.get(field.name);
        if (mapping.indexed) {
          if (!Object.hasOwn(object, 'indexed')) {
            throw new TypeError(
              `${IMAGE_MUTATION_BINDING_V1} supplies indexed field ${field.name}, but ${imageId}/${objectId} has no indexed part`,
            );
          }
          indexed = buildNewIndexedPart(imageId, object.indexed, value[field.name], field, mapping.edge, descriptor.types ?? {}, require);
          continue;
        }
        const slot = mapping.slot;
        if (Object.hasOwn(slots, slot)) {
          const current = canonicalizeValue(slots[slot]);
          // Rejected, never followed or overwritten through: authority for this object must not
          // imply authority for whatever it points at.
          if (isReference(current)) {
            throw new TypeError(
              `slot ${slot} holds a reference; ${IMAGE_MUTATION_BINDING_V1} never writes through refs`,
            );
          }
        }
        slots[slot] = hostLeafToCanonical(value[field.name], field.type, `mutated field ${field.name}`);
      }

      const stored = await putObjectAtExpectedVersion(images, imageId, {
        id: objectId,
        shape: object.shape,
        behavior: object.behavior,
        slots,
        // The indexed part is part of the same object record: preserved verbatim when untouched,
        // or the new append/reorder value when the binding has an indexed field (ADR 0065).
        ...(indexed === undefined ? {} : {indexed}),
        metadata: object.metadata,
      }, expectedVersion);

      return textValue(objectVersionToken(imageId, objectId, stored._version));
    },
  });
}

