      }
      bindings[capture.id] = {name: capture.name, value: canonicalizeValue(capture.value)};
    }

    // ADR 0052 decision 5: a closure instance is execution-local. No environment record, no Block
    // record, no history event — the instance lives in the arena and becomes durable only if it
    // escapes, which is what makes evaluating a Block literal in a loop cost nothing.
    //
    // The instance's image is the prototype's, so dispatch-image behaviour is unchanged.
    const hasBindings = Object.keys(bindings).length > 0;
    let blockRef;
    if (arena) {
      const environment = hasBindings
        ? arena.mintClosureEnvironment(prototypeRef.imageId, {bindings})
        : null;
      blockRef = arena.mintClosureBlock(prototypeRef.imageId, {
        code: prototypeBlock.code,
        environment,
        metadata: {prototypeBlockId: prototypeRef.objectId},
      });
    } else {
      // No arena means no execution to be local to — a closure created outside one has nowhere
      // transient to live, so it is durable immediately.
      const environment = hasBindings
        ? await this.images.putLexicalEnvironment(prototypeRef.imageId, {bindings})
        : null;
      const block = await this.images.putBlock(prototypeRef.imageId, {
        code: prototypeBlock.code,
        environment: environment ? objectRef(environment.imageId, environment.id) : null,
        metadata: {prototypeBlockId: prototypeRef.objectId},
      });
      blockRef = objectRef(block.imageId, block.id);
    }
    // Execution-scoped, never durable: this is the only thing that lets a closure created in this
    // execution reach a live cell, and it dies with the arena.
    cells?.associate(blockRef, capturedCells);
    // Lexical frame state, alongside the lexical cells that already work this way. Execution-scoped
    // by construction: it dies with the arena, which is what makes an escaped closure fail closed
    // rather than carry a forgeable claim into a later execution (ADR 0050 decision 10a).
    if (frame) arena?.associateFrame?.(blockRef, frame);
    return blockRef;
  }

  // `authorityContext` is execution context in exactly the way `depth` already is: real,
  // load-bearing, and absent from the durable model. Nothing is added to the activation.
  // `invocationFrame` is ADR 0050 decision 5b's transient envelope, and `inheritedFrame` is the
  // caller's frame offered to a callee the language marked as its own host operation. Both are
  // execution context in exactly the way `depth` and `authority` are: they reach no activation
  // record, no Value and no durable state.
  async execute(activation, {
    depth = 0,
    authority = null,
    cellArena = null,
    dispatchImage = null,
    invocationFrame = null,
    inheritedFrame = null,
    conditionRuntime = null,
  } = {}) {
    if (!Number.isInteger(depth) || depth < 0) throw new TypeError('activation depth must be a non-negative integer');
    if (depth > MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
    assertActivationRequest(activation);

    // The root execution owns the arena; nested sends share it. That is a lifetime relationship and
    // nothing more: cells are still reached by frame, so sharing an arena never means sharing a
    // variable. It is what makes a returned closure keep working for the rest of this execution
    // while still expiring when the execution does.
    //
    // Created here, before the verification reads below, because ADR 0052 lets the activation's
    // Block be a closure instance that lives only in the arena — so the resolver has to exist
    // before anything tries to resolve.
    // ADR 0052 decision 6: returning from a *root* execution is an escape, because the answer
    // reaches a caller with no arena. A nested send is not — it hands its answer back inside the
    // same arena, where a transient closure stays perfectly usable. The existing call structure
    // already draws that line exactly: the root is the execution that was given no arena.
    const ownsArena = !cellArena;
    const arena = cellArena ?? new LexicalCellArena();
    // ADR 0054: one execution-wide condition runtime, owned beside the arena and living exactly as
    // long. Nested sends share it, so a handler established anywhere in the execution is found from
    // anywhere else in it — including across a WASM boundary, which contributes no machinery of its
    // own.
    const conditions = conditionRuntime ?? arena.conditionRuntime();
    // ADR 0052 decision 5a: one resolution rule for this execution, shared by the executors, the
    // dispatcher and this class's own reads. Identical to `this.images` when there is no arena.
    const view = arenaImagesView(this.images, arena);
    // ADR 0060: a write to an already-promoted object may introduce a *new* transient value (a
    // backing store allocated after its owner escaped). The view's write-through promotes such a
    // value through the same central operation the boundary uses, so the durable copy never holds
    // an unpromoted ref. The memo is the arena's, so a value promoted here and at the boundary is
    // one object.
    if (arena) arena.postPromotionPromoter = async (value) => await promoteClosure(this.images, arena, value);

    const block = await view.getBlock(activation.block.imageId, activation.block.objectId);
    if (!block) throw new TypeError(`activation block not found: ${activation.block.imageId}/${activation.block.objectId}`);
    if (!sameRef(block.code, activation.code)) throw new TypeError('activation code does not match Block code');
    if (!sameRef(block.environment, activation.environment)) {
      throw new TypeError('activation environment does not match Block environment');
    }

    const code = await view.getCodeArtifact(activation.code.imageId, activation.code.objectId);
    if (!code) throw new TypeError(`activation code artifact not found: ${activation.code.imageId}/${activation.code.objectId}`);

    const executor = this.executors.get(code.representation);

    const cells = arena.activationCells(activation.block);

    // ADR 0050 decision 5a, in priority order:
    //
    //   a dispatch that supplied a frame        REPLACES  — the callee runs as its own self
    //   a callee the language marked inheriting INHERITS  — its host operation acts for the caller
    //   a closure created inside a framed frame  RESTORES  — lexical self, per decision 10
    //   anything else                            NONE      — and the slot primitives are unusable
    //
    // The restore case is also what makes decision 10a fail closed for free: the association lives
    // in the arena, the arena dies with the execution, so a closure invoked in a *later* execution
    // finds nothing rather than believing a durable claim.
    const activeFrame = invocationFrame
      ?? this.invocations?.frameFor?.(activation)
      ?? inheritedFrame
      ?? arena.frameFor?.(activation.block)
      ?? null;

    // ADR 0055 decision 3a. Computed *alongside* the expression above rather than by refactoring it,
    // so ADR 0050's priority semantics are reused rather than re-derived.
    //
    // Only a dispatch-supplied frame is owned. A kernel primitive inherits one and a closure restores
    // one — both are borrowers holding the very same object — so ownership, not frame equality, is
    // what decides where a non-local return stops. Otherwise the return primitive, which is running
    // with the home frame at the moment it raises, would catch its own transfer.
    const ownsFrame = activeFrame !== null
      && (invocationFrame !== null || this.invocations?.frameFor?.(activation) != null);
    // Marked live inside the protected region below, not here: a failure between this point and the
    // `try` — temporary initialization, for instance — would otherwise leave a frame permanently
    // live, and a later `^` naming it would be told its home is still running.
    const homeSelector = ownsFrame ? (activation.dispatch?.message?.value ?? null) : null;

    // ADR 0044 decision 5a. A root activation dispatches in its own Block's image; a nested one
    // inherits what its sender computed. Context, never a field on the activation.
    const activeDispatchImage = dispatchImage ?? activation.block.imageId;

    // Resolved once per activation, before any executor runs, so both lanes see one answer.
    let initialTemporaryContents = UNBOUND;
    if (this.temporaryInitializer) {
      // The artifact's language identity travels with the request, because initialization policy
      // belongs to a language rather than to an image. The execution layer still knows nothing
      // about any particular language — only that an artifact has one.
      const initial = await this.temporaryInitializer({
        images: view,
        dispatchImage: activeDispatchImage,
        languageId: code.languageId ?? null,
      });
      if (initial !== null && initial !== undefined) initialTemporaryContents = canonicalizeValue(initial);
    }

    // A mutable record rather than mere stack scoping, so that "active" can later mean "the
    // logical activation is still alive" once async activations exist, instead of "a
    // JavaScript frame happens to be on the stack".
    const lifetime = {active: true};
    const whileActive = (operation, implementation) => (...args) => {
      if (!lifetime.active) throw new ExpiredExecutionContextError(operation);
      return implementation(...args);
    };

    try {
      if (ownsFrame) this.#markHomeActivation(activeFrame, 'live', homeSelector);
      const result = await executor.execute(
      {activation, code},
      {
        images: view,
        // ADR 0054. Primitives reach the condition runtime through this facade and never through
        // an authority context: `establish` hands back a scope id, and the *invoker* it stores
        // closes over the authority in force here. A handler therefore runs with its establisher's
        // rights without any capability crossing the primitive boundary (ADR 0037).
        conditions: Object.freeze({
          runtime: conditions,
          // Captures the authority in force *here*, and nothing else. An opaque handle rather than
          // the context itself, so a primitive can carry it to a handler entry without ever holding
          // a capability (ADR 0037).
          captureAuthority: whileActive('captureAuthority', () => {
            const token = Object.freeze({});
            CAPTURED_AUTHORITY.set(token, authority);
            return token;
          }),
          // Invoked from whichever frame is *running* the Block, not from the frame that captured
          // the token. Depth is therefore the depth at the signal point — a handler on a deep
          // signalling stack must not be measured from where `on:do:` was written — and the
          // dispatch image is the Block's own, which is the ordinary rule for any Block and is what
          // keeps a cross-image handler using its own kernel rather than the establisher's.
          //
          // Invoking a Block rather than dispatching a selector keeps this language-neutral, and
          // lets ADR 0050 restore the Block's creation frame, which is what gives a handler its
          // establisher's `self` for free.
          // ADR 0055. The primitive asks whether the frame it was handed still has a running
          // owner; it never sees the registry, and a frame is only ever a key in it.
          homeActivationState: whileActive('homeActivationState', (frame) => this.homeActivationState(frame)),
          homeActivationSelector: whileActive('homeActivationSelector', (frame) => this.homeActivationSelector(frame)),
          invoke: whileActive('invoke', async (token, blockRef, args = []) => {
            if (!CAPTURED_AUTHORITY.has(token)) throw new TypeError('unknown captured authority token');
            if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
            const activation = await this.invocations.prepareActivation({
              block: blockRef, arguments: args, images: view,
            });
            return await this.execute(activation, {
              depth: depth + 1,
              authority: CAPTURED_AUTHORITY.get(token),
              cellArena: arena,
              conditionRuntime: conditions,
              dispatchImage: normalizeObjectRef(blockRef, 'condition block').imageId,
            });
          }),
        }),
        // ADR 0052 decision 7a. The boundary that creates durable reachability calls this before
        // its write; the graph guard stays a tripwire proving a boundary was not forgotten, rather
        // than becoming the mechanism. A value with nothing transient in it comes straight back.
        promote: whileActive('promote', async (value) => await promoteClosure(this.images, arena, value)),
        // ADR 0060 decision 3. An object allocated inside this execution begins in the arena, not
        // the durable store — `basicNew` and condition allocation mint here, and the object becomes
        // durable only if a reference crosses a durability boundary via `promote`. The arena owns
        // the identity (a transient ref in the reserved namespace); the caller supplies only the
        // layout, so there is no identity collision to retry.
        mintObject: whileActive('mintObject', ({imageId, shape, behavior, slots = {}, indexed = null, metadata = {}}) => (
          arena.mintObject(imageId, {shape, behavior, slots, indexed, metadata})
        )),
        // Check-only, and the only authority operation that crosses this seam. There is no
        // grant to return, no context to read, and no principal to branch on. Absent
        // authority fails closed rather than permitting.
        require: whileActive('require', (demand) => {
          if (!this.authority) throw new TypeError('no authority service is configured; this execution has no capabilities');
          if (authority === null) throw new TypeError('no authority context was supplied; this execution has no capabilities');
          return this.authority.require(authority, demand);
        }),
        lookupBinding: whileActive('lookupBinding', async (bindingId) => {
          if (!activation.environment) throw new TypeError(`lexical binding not found: ${bindingId}`);
          return await this.lookupBinding(activation.environment, bindingId, view);
        }),
        // Declared, not initialized: a temporary has no value until it is assigned, and there is
        // no nil to give it. Reading one before assignment raises rather than defaulting.
        declareTemporaries: whileActive('declareTemporaries', (temporaries) => {
          if (!Array.isArray(temporaries)) throw new TypeError('temporaries must be an array');
          cells.declare(temporaries, initialTemporaryContents);
        }),
        // Cell-only and synchronous, which `readBinding` cannot be: it falls through to an awaited
        // durable-environment lookup. A WASM import must return a value, not a promise, so the
        // WASM lane uses these and never the general ones. Absence raises rather than falling
        // back, so there is no path by which a durable snapshot could answer a cell read.
        readCell: whileActive('readCell', (bindingId) => {
          const cell = cells.resolve(bindingId);
          if (!cell) throw new MissingLexicalCellError(bindingId);
          return cell.read();
        }),
        writeCell: whileActive('writeCell', (bindingId, value) => {
          const cell = cells.resolve(bindingId);
          if (!cell) throw new MissingLexicalCellError(bindingId);
          return cell.write(value);
        }),
        readBinding: whileActive('readBinding', async (bindingId) => {
          const cell = cells.resolve(bindingId);
          if (cell) return cell.read();
          if (!activation.environment) throw new TypeError(`lexical binding not found: ${bindingId}`);
          return await this.lookupBinding(activation.environment, bindingId, view);
        }),
        writeBinding: whileActive('writeBinding', async (bindingId, value) => {
          const cell = cells.resolve(bindingId);
          if (cell) return cell.write(value);
          // Assignment reaches cells only. A durable binding is layout plus a snapshot, and ADR
          // 0043 decision 2 keeps assignment out of the graph entirely.
          const record = activation.environment
            ? await this.lookupBindingRecord(activation.environment, bindingId, view)
            : null;
          if (record?.cell === true) throw new EscapingMutableClosureError(bindingId, record.name);
          if (record) throw new TypeError(`lexical binding ${bindingId} is not an assignable cell`);
          throw new TypeError(`lexical binding not found: ${bindingId}`);
        }),
        // Read-only, and only meaningful to a language-owned executor: it is the identity of the
        // method activation this operation is acting for, never a capability.
        invocationFrame: activeFrame,
        createClosure: whileActive('createClosure', async (request) => await this.createClosure(request, cells, arena, activeFrame)),
        // A nested send inherits the current authority. An executor may ask for a narrower
        // child, but never receives one: the attenuation happens here, so no executor ever
        // holds a context. Since attenuation only narrows, a nested send can lose rights and
        // can never gain them.
        sendMessage: whileActive('sendMessage', async (request, {attenuate = null} = {}) => {
          if (!this.invocations) throw new TypeError('activation executor has no message runtime');
          if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
          let nestedAuthority = authority;
          if (attenuate !== null) {
            if (!this.authority) throw new TypeError('cannot attenuate without an authority service');
            if (authority === null) throw new TypeError('cannot attenuate without an authority context');
            nestedAuthority = this.authority.attenuate(authority, {grants: attenuate});
          }
          // An object receiver dispatches in its own image; an immediate one has none, so the
          // sender's dispatch image carries through unchanged.
          const nextDispatchImage = isObjectRef(request.receiver)
            ? request.receiver.imageId
            : activeDispatchImage;
          const dispatched = await this.invocations.prepareDispatch(request, {
            dispatchImage: nextDispatchImage, images: view,
          });
          return await this.execute(dispatched.activation, {
            depth: depth + 1,
            authority: nestedAuthority,
            cellArena: arena,
            conditionRuntime: conditions,
            dispatchImage: nextDispatchImage,
            invocationFrame: dispatched.frame,
            // Offered only where the language said this callee is its own host operation. An
            // ordinary Block send inherits nothing, so a method cannot lend its identity to a Block
            // it merely invoked.
            inheritedFrame: dispatched.inheritsFrame ? activeFrame : null,
          });
        }),
      },
      );
      const answer = canonicalizeValue(result);
      // Before leaving, while the arena still exists. Deliberately the returned Value only: a
      // durable object cannot secretly hold a transient closure, because creating that edge would
      // already have been refused at the graph write seam. Walking a returned object graph would be
      // I/O spent re-proving what the write boundary guarantees.
      return ownsArena ? await promoteClosure(this.images, arena, answer) : answer;
    } catch (error) {
      // Only the owner stops a return naming its own frame; a borrower lets it travel on.
      if (ownsFrame && error instanceof NonLocalReturnTransfer && error.frame === activeFrame) {
        const answer = canonicalizeValue(error.value);
        // The same escape boundary an ordinary return crosses (ADR 0052 decision 6): a root
        // execution's answer is promoted before leaving, while the arena still exists. Returning
        // this value unpromoted would let `^ [ ... ]` hand a transient closure to a caller that has
        // no arena to resolve it in.
        return ownsArena ? await promoteClosure(this.images, arena, answer) : answer;
      }
      throw error;
    } finally {
      // Also on the exceptional path: a trapping guest must not leave a live context behind.
      lifetime.active = false;
      // Dead from here on. Retained rather than deleted: while the frame is still reachable, a
      // `^` naming it must be told the method returned rather than that it has no home.
      // Marked dead rather than deleted: while the frame is still reachable, a `^` naming it must
      // be told the method returned rather than that it has no home.
      if (ownsFrame) this.#markHomeActivation(activeFrame, 'dead', homeSelector);
    }
  }
}

export {
  ActivationExecutor,
  ExpiredExecutionContextError,
  MAX_ACTIVATION_DEPTH,
  assertActivationRequest,
};

import {canonicalizeValue, isObjectRef} from '../value/index.js';

function sameObjectRef(left, right) {
  return left.imageId === right.imageId && left.objectId === right.objectId;
}

function assertBlockApplicationReceiver(activation, label = 'callable Block') {
  if (!activation || typeof activation !== 'object' || Array.isArray(activation)) {
    throw new TypeError(`${label} activation must be an object`);
  }
  if (activation.receiver === null) return activation;

  const block = canonicalizeValue(activation.block);
  const receiver = canonicalizeValue(activation.receiver);
  if (!isObjectRef(block) || !isObjectRef(receiver) || !sameObjectRef(block, receiver)) {
    throw new TypeError(`${label} accepts only direct Block invocation or the Block itself as receiver`);
  }
  return activation;
}

export {assertBlockApplicationReceiver};

import {ensureBlock, ensureLexicalEnvironment, ensureObject} from '../graph/ensure-records.js';
import {objectRef} from '../value/index.js';
import {TRANSIENT_ID_PREFIX, isTransientRef} from '../value/transient-ref.js';
import {ExpiredClosureInstanceError} from './lexical-cells.js';

// ADR 0052 decision 7a: promotion is ONE operation, not a habit.
//
// Every escape boundary — root return, slot and indexed writes, Dictionary writes, the foreign
// boundary — calls this and nothing else. Four implementations of a rule this subtle would disagree,
// and the disagreement would surface as a closure that is sometimes shared and sometimes duplicated.
//
// The ordering below is the whole design, so it is worth reading as a sequence:
//
//   discover a transient instance
//     -> compute its durable id
//     -> memoize transient -> durable *immediately*, before recursing
//     -> recursively promote snapshot-captured transient refs
//     -> write the environment (exact-or-create)
//     -> write the Block (exact-or-create)
//
// The early memo is what makes sharing and cycles terminate: a closure reached twice is answered
// from the memo the second time, and a cycle meets its own entry rather than recursing forever. The
// preassigned durable ref is what lets another environment name this closure before its Block record
// exists — which is legal because `putLexicalEnvironment` validates the parent edge only and does
// not require binding refs to resolve, so no atomic write of a cycle is needed.
//
// But "identity reserved" and "records published" are different facts, and conflating them turns the
// very mechanism that breaks cycles into a way of reporting a failed promotion as a success: a retry
// would meet the leftover entry and answer a durable ref whose Block was never written. The memo
// therefore has three effective states:
//
//   absent        begin promotion
//   in-progress   answer the preassigned ref, so recursion and cycles terminate
//   complete      answer the promoted ref; the records exist
//
// A failure clears the in-progress entry, so a later call re-runs publication rather than trusting
// a reservation nobody honoured. Exact-or-create is what makes that safe after a commit-then-lost-
// ack: the retry rediscovers its own committed records and converges on them.

// Deterministic, and derived from the transient id — which already carries a per-arena nonce, so two
// executions cannot collide and a retry within one execution recomputes the same id. That is what
// makes a lost acknowledgement converge instead of promoting one closure under two identities.
//
// The transient id embeds the arena's mint kind as its first segment (`block`, `environment`,
// `object`). Closures keep the historical `closure/` prefix so a pre-ADR-0060 promoted closure's
// derived id is unchanged; objects derive under `object/`. The kind segment is consumed, not
// carried into the durable id.
function durableIdFor(transientObjectId) {
  const suffix = transientObjectId.slice(TRANSIENT_ID_PREFIX.length);
  if (suffix.startsWith('object/')) return `object/${suffix.slice('object/'.length)}`;
  return `closure/${suffix}`;
}

// Snapshot bindings only. A `{cell: true}` binding carries no value by construction, so there is
// nothing here to read — and that is deliberate rather than incidental: ADR 0043 keeps cell contents
// out of the durable record, and letting promotion see them would make transient state decide what
// persists. What is traversed is what is written.
function promotedBinding(binding) {
  if (binding?.cell === true) return {name: binding.name, cell: true};
  return {name: binding.name, unbound: true};
}

class ClosurePromoter {
  #images;
  #arena;
  #memo;

  constructor(images, arena) {
    this.#images = images;
    this.#arena = arena;
    // Per arena, so promotion is idempotent for the whole execution: a closure written into two
    // slots is one closure, in the second slot as much as the first.
    this.#memo = arena.promotionMemo();
  }

  // Rewrites a Value that may itself be, or contain, a transient reference. Returns a plain Value
  // when there is nothing transient about it, which is the overwhelmingly common case.
  async promoteValue(value) {
    if (!isTransientRef(value)) return value;
    return await this.promote(value);
  }

  async promote(ref) {
    const key = [ref.imageId, ref.objectId];
    // Both `in-progress` and `complete` answer the same ref: the first is what closes a cycle, the
    // second is what makes promotion idempotent. Only `absent` starts work.
    const existing = this.#memo.get(key);
    if (existing) return existing.ref;

    const record = this.#arena.transientRecord(ref.imageId, ref.objectId);
    if (!record) throw new ExpiredClosureInstanceError(ref.imageId, ref.objectId);

    const durable = objectRef(ref.imageId, durableIdFor(ref.objectId));
    // Reserved before any recursion. Everything below may reach this same instance again.
    this.#memo.set(key, {ref: durable, status: 'in-progress'});
    try {
      if (record.kind === 'block') {
        const environment = await this.#promoteEnvironment(ref.imageId, record.environment);
        await ensureBlock(this.#images, ref.imageId, {
          id: durable.objectId,
          code: record.code,
          environment,
          metadata: {...record.metadata},
        });
      } else if (record.kind === 'object') {
        await this.#promoteObjectRecord(ref, durable.objectId);
      } else {
        throw new TypeError(`only a closure instance or an object can be promoted: ${ref.imageId}/${ref.objectId}`);
      }
      this.#memo.set(key, {ref: durable, status: 'complete'});
      return durable;
    } catch (error) {
      // A reservation nobody honoured must not survive as an answer. Dropping it costs only the
      // work of re-running an exact-or-create publication, which converges whether the failed
      // attempt wrote nothing or wrote everything and lost the acknowledgement.
      this.#memo.delete(key);
      throw error;
    }
  }

  // ADR 0060 decision 5. The durable projection is the object's slots and indexed part, recursively
  // through transient refs only: what is traversed is what is written. A durable ref reachable from
  // the object is an edge to an existing durable record and is written as an edge, not re-published.
  // The preassigned durable ref (reserved in `promote` before this runs) is what lets a cycle name
  // this object before its record exists, so the traversal terminates on shared structure and on
  // cycles through the memo.
  //
  // The record is re-read from the arena *at write time*, not carried from the caller. Promotion of
  // a cyclic graph suspends inside a nested `promoteValue`, and Smalltalk code runs while a cycle is
  // still in-progress (`initialize`, slot writes) — so the object can be mutated between reservation
  // and publication. Writing the stale snapshot would silently drop the mutation that closed the
  // cycle (a link written *after* its target was reserved). The arena holds the live state; the
  // write publishes it as it stands when the holder's own promotion completes.
  async #promoteObjectRecord(ref, durableObjectId) {
    const record = this.#arena.transientRecord(ref.imageId, ref.objectId);
    if (!record) throw new ExpiredClosureInstanceError(ref.imageId, ref.objectId);
    const slots = {};
    for (const [slotId, value] of Object.entries(record.slots)) {
      slots[slotId] = await this.promoteValue(value);
    }
    const desired = {
      id: durableObjectId,
      shape: record.shape,
      behavior: record.behavior,
      slots,
      ...(Object.hasOwn(record, 'indexed')
        ? {indexed: await Promise.all(record.indexed.map((value) => this.promoteValue(value)))}
        : {}),
      metadata: {...record.metadata},
    };
    await ensureObject(this.#images, ref.imageId, desired);
  }

  async #promoteEnvironment(imageId, environmentRef) {
    if (!environmentRef) return null;
    // An instance may close over an environment that is already durable — a prototype's, say — in
    // which case there is nothing to promote and the edge stands as it is.
    if (!isTransientRef(environmentRef)) return environmentRef;

    const record = this.#arena.transientRecord(environmentRef.imageId, environmentRef.objectId);
    if (!record) throw new ExpiredClosureInstanceError(environmentRef.imageId, environmentRef.objectId);

    const bindings = {};
    for (const [bindingId, binding] of Object.entries(record.bindings)) {
      bindings[bindingId] = binding?.cell === true || binding?.unbound === true
        ? promotedBinding(binding)
        : {name: binding.name, value: await this.promoteValue(binding.value)};
    }

    const parent = await this.#promoteEnvironment(imageId, record.parent);
    const id = durableIdFor(environmentRef.objectId);
    await ensureLexicalEnvironment(this.#images, environmentRef.imageId, {
      id,
      ...(parent ? {parent} : {}),
      bindings,
    });
    return objectRef(environmentRef.imageId, id);
  }
}

// The single entry point every boundary uses.
async function promoteClosure(images, arena, value) {
  if (!arena || !isTransientRef(value)) return value;
  return await new ClosurePromoter(images, arena).promoteValue(value);
}

export {ClosurePromoter, durableIdFor, promoteClosure};

// ADR 0054: the condition runtime.
//
// One execution-wide stack of scopes, owned beside the arena and living exactly as long. The three
// classless-Block operations (`on:do:`, `ensure:`, `ifCurtailed:`) only enter and leave scopes on it,
// and signalling only searches it — so the neutral and WASM lanes share one handler search and one
// transfer mechanism, and WASM contributes nothing but the suspend/resume/retire behaviour it
// already had. There is deliberately no "WASM exception system".
//
// Nothing here is durable. A scope reaches no record, no Value and no activation field: it is
// execution context in the way `dispatchImage`, the authority context and ADR 0050's frame are.

// The unwind mechanism. Thrown to move control to a scope that is still on the stack, and carried by
// the host's own stack unwinding — which is what makes `ensure:` fire for host failures too, since
// they travel the same way.
class ConditionTransfer extends Error {
  constructor(kind, scopeId, value, occurrenceId = null) {
    super(`condition transfer (${kind})`);
    this.name = 'ConditionTransfer';
    this.kind = kind;
    this.scopeId = scopeId;
    this.value = value;
    this.occurrenceId = occurrenceId;
  }
}

// ADR 0055. A transfer that names a *home method activation* rather than a handler scope, which is
// why `on:do:` cannot intercept one: it is a different class and carries a frame, not a scope id.
class NonLocalReturnTransfer extends Error {
  constructor(frame, value) {
    super('non-local return');
    this.name = 'NonLocalReturnTransfer';
    this.frame = frame;
    this.value = value;
  }
}

class NonLocalReturnHomeError extends TypeError {
  constructor(detail) {
    super(`non-local return has no live home method activation: ${detail}`);
    this.name = 'NonLocalReturnHomeError';
  }
}

class SmalltalkUnhandledConditionError extends TypeError {
  constructor(description) {
    super(`unhandled Smalltalk condition: ${description}`);
    this.name = 'SmalltalkUnhandledConditionError';
  }
}

class SmalltalkNoActiveOccurrenceError extends TypeError {
  constructor(operation) {
    super(`${operation} requires a condition that is currently being handled`);
    this.name = 'SmalltalkNoActiveOccurrenceError';
  }
}

class ConditionRuntime {
  #scopes = [];
  #occurrences = [];
  #nextId = 0;

  // `authorityToken` is an opaque handle to the authority in force at establishment. The runtime
  // carries it and never reads it; only the executor can resolve it (ADR 0037). Deliberately *not*
  // a bound invoker: binding one would freeze the establishment frame's depth and dispatch image
  // too, and a handler must run at the signal point's depth and in its own Block's image.
  enterHandler({conditionClass, block, authorityToken}) {
    const scopeId = (this.#nextId += 1);
    this.#scopes.push({scopeId, kind: 'handler', conditionClass, block, authorityToken, active: true});
    return scopeId;
  }

  enterProtection({kind, block, authorityToken}) {
    const scopeId = (this.#nextId += 1);
    this.#scopes.push({scopeId, kind, block, authorityToken, active: true});
    return scopeId;
  }

  // Truncates rather than pops: an unwind may have skipped scopes established inside this one, and
  // leaving them on the stack would let a later signal find a handler whose `on:do:` has returned.
  leave(scopeId) {
    const index = this.#scopes.findIndex((scope) => scope.scopeId === scopeId);
    if (index >= 0) this.#scopes.length = index;
  }

  // Innermost first, and only scopes that are active — a handler is disabled while it runs, so a
  // re-signal from inside it delegates outward instead of recursing into itself.
  //
  // Asynchronous because matching walks the candidate's superclass chain through the image, which is
  // I/O. Sequential rather than parallel on purpose: innermost-first is the semantics, not an
  // optimisation, so the first match must be the innermost one.
  async findHandler(matches) {
    for (let index = this.#scopes.length - 1; index >= 0; index -= 1) {
      const scope = this.#scopes[index];
      if (scope.kind !== 'handler' || !scope.active) continue;
      if (await matches(scope.conditionClass)) return scope;
    }
    return null;
  }

  // The handling scope is recorded on the occurrence, so `return:` knows where to unwind to without
  // the condition object carrying any control-flow state.
  beginOccurrence(condition, handlerScopeId) {
    const occurrenceId = (this.#nextId += 1);
    this.#occurrences.push({occurrenceId, condition, handlerScopeId, active: true});
    return occurrenceId;
  }

  endOccurrence(occurrenceId) {
    const index = this.#occurrences.findIndex((entry) => entry.occurrenceId === occurrenceId);
    if (index >= 0) this.#occurrences.splice(index, 1);
  }

  // The receiver's *currently active* occurrence. One condition object signalled twice has two, and
  // neither may see the other's — so this is resolved per handling and never read off the object.
  activeOccurrenceFor(sameCondition) {
    for (let index = this.#occurrences.length - 1; index >= 0; index -= 1) {
      const entry = this.#occurrences[index];
      if (entry.active && sameCondition(entry.condition)) return entry;
    }
    return null;
  }

  withDisabled(scope, body) {
    scope.active = false;
    return Promise.resolve()
      .then(body)
      .finally(() => { scope.active = true; });
  }
}

export {
  ConditionRuntime,
  NonLocalReturnHomeError,
  NonLocalReturnTransfer,
  ConditionTransfer,
  SmalltalkNoActiveOccurrenceError,
  SmalltalkUnhandledConditionError,
};

class ExecutorRegistrationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ExecutorRegistrationError';
  }
}

class ExecutorNotFoundError extends Error {
  constructor(representation) {
    super(`no executor registered for representation: ${representation}`);
    this.name = 'ExecutorNotFoundError';
    this.representation = representation;
  }
}

function normalizeRepresentation(value) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError('code representation must be a non-empty string');
  }
  return value;
}

function assertExecutor(executor) {
  if (!executor || typeof executor !== 'object' || typeof executor.execute !== 'function') {
    throw new TypeError('code executor must implement execute(input, context)');
  }
  return executor;
}

class CodeExecutorRegistry {
  constructor() {
    this.executors = new Map();
  }

  register(representation, executor) {
    const key = normalizeRepresentation(representation);
    if (this.executors.has(key)) {
      throw new ExecutorRegistrationError(`executor already registered: ${key}`);
    }
    this.executors.set(key, assertExecutor(executor));
    return executor;
  }

  get(representation) {
    const key = normalizeRepresentation(representation);
    const executor = this.executors.get(key);
    if (!executor) throw new ExecutorNotFoundError(key);
    return executor;
  }

  has(representation) {
    return this.executors.has(normalizeRepresentation(representation));
  }

  list() {
    return [...this.executors.keys()].sort();
  }
}

export {
  CodeExecutorRegistry,
  ExecutorNotFoundError,
  ExecutorRegistrationError,
  normalizeRepresentation,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {TupleMap} from '../support/tuple-map.js';
import {canonicalizeValue, objectRef} from '../value/index.js';
import {isTransientObjectId, transientObjectId} from '../value/transient-ref.js';
import {ConditionRuntime} from './conditions.js';

// A closure instance whose arena is gone. Distinct from "block not found" on purpose: ADR 0052
// decision 5c makes this rigorous, because a reserved id can never name a durable record, so its
// absence from the arena means expiry rather than a missing or corrupt record.
class ExpiredClosureInstanceError extends TypeError {
  constructor(imageId, objectId) {
    super(`closure instance ${imageId}/${objectId} has expired; its execution has ended`);
    this.name = 'ExpiredClosureInstanceError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

// The lane-neutral lexical frame and cell substrate, per ADR 0043.
//
// This deliberately lives in the common execution layer rather than inside an executor. Two
// implementations of mutable lexical state — one for the neutral lane, one for WASM — is the
// architecture to avoid: the semantics would become lane-dependent, which ADR 0043 decision 10
// forbids. Both lanes consume these operations instead.
//
// A cell is identified by (lexical frame, static binding ID), never by binding ID alone. Binding
// IDs are static slot identity: the compiler derives them from a path defaulting to 'root', so
// `root:temporary:0` names a slot in the code, and two activations of that code — including two
// recursive activations — deliberately share it while needing distinct variables.
//
// Frame *identity* and frame *lifetime* are separate, and conflating them is the easy mistake:
//
//   different lexical invocation   ->  different frame
//   a frame stays reachable after its own call returns, if a closure still holds one of its cells
//   nothing captured it            ->  it goes away when its call returns
//   the root execution ends        ->  the arena dies with it
//
// So a factory that returns a counter closure keeps working for the rest of that execution:
//
//   make := [ | n | n := 0. [ n := n + 1 ] ].
//   counter := make value.  counter value.  counter value.   "2"
//
// The closure has escaped its declaring frame but not the execution that owns the arena. Only a
// later, independent execution meeting a durable {cell: true} capture raises.

// A host sentinel, never a canonical Value and never observable as one. When the object system
// arrives, a temporary's initial contents become the `nil` object ref and nothing here changes.
const UNBOUND = Symbol('lagrange.lexical.unbound');

class UnboundBindingError extends TypeError {
  constructor(name, id) {
    super(`lexical binding ${name ?? id} is unbound; it has no value until it is assigned`);
    this.name = 'UnboundBindingError';
    this.bindingId = id;
  }
}

// Raised when a closure that depends on a live cell is invoked without the execution that owns
// that cell. ADR 0043 decision 5: this case is unsupported, not silently reset to whatever the
// durable snapshot happened to hold.
class EscapingMutableClosureError extends TypeError {
  constructor(id, name) {
    super(
      `closure depends on the live lexical cell ${name ?? id}, which belonged to a finished execution; `
      + 'persistent mutable captured state needs an explicit survival contract',
    );
    this.name = 'EscapingMutableClosureError';
    this.bindingId = id;
  }
}

// Raised when a synchronous cell operation names a binding that is not a cell of this activation.
// The cell-only accessors deliberately do not fall back to the durable environment: that lookup is
// asynchronous, so a fallback would be unusable from a WASM import anyway, and offering one would
// reopen the snapshot channel that ADR 0043 decision 5 closes.
class MissingLexicalCellError extends TypeError {
  constructor(id) {
    super(`lexical binding ${id} is not a cell of this activation`);
    this.name = 'MissingLexicalCellError';
    this.bindingId = id;
  }
}

class LexicalCell {
  #id;
  #name;
  #contents = UNBOUND;

  // `initialContents` is how ADR 0044 decision 8 arrives: in a bootstrapped image a declared
  // temporary starts holding that image's `nil` ref, and elsewhere it starts UNBOUND exactly as
  // before. A cell holding nil is an ordinary bound cell — nothing downstream distinguishes it,
  // which is why this needs no new WASM ABI.
  constructor(id, name, initialContents = UNBOUND) {
    this.#id = id;
    this.#name = name ?? null;
    this.#contents = initialContents === UNBOUND ? UNBOUND : canonicalizeValue(initialContents);
  }

  get id() { return this.#id; }
  get name() { return this.#name; }
  get bound() { return this.#contents !== UNBOUND; }

  read() {
    if (this.#contents === UNBOUND) throw new UnboundBindingError(this.#name, this.#id);
    return this.#contents;
  }

  // Assignment is an expression, so the written value is returned.
  write(value) {
    this.#contents = canonicalizeValue(value);
    return this.#contents;
  }

  // Deliberately no snapshot() method. Persisting a mutable capture always writes
  // {name, cell: true} regardless of what the cell currently holds, so that no value is
  // reachable in the durable record for a later invocation to silently restart from. A snapshot
  // accessor would exist only to defeat that, so it does not exist.
}

// One lexical activation's cells. Opaque: nothing outside resolves a cell except through here.
class LexicalFrame {
  #cells = new Map();

  declare(id, name, initialContents = UNBOUND) {
    if (!this.#cells.has(id)) this.#cells.set(id, new LexicalCell(id, name, initialContents));
    return this.#cells.get(id);
  }

  own(id) {
    return this.#cells.get(id) ?? null;
  }
}

// Execution-scoped. What the arena actually owns is the closure-to-cell associations: those must
// outlive the activation that created the closure, and must not outlive the execution — which is
// what makes cells activation state under ADR 0041 rather than something that survives by accident.
//
// It deliberately does *not* keep a list of frames. A frame is reachable while its activation runs,
// and afterwards only through cells some closure captured, so an unwatched frame becomes collectable
// as soon as its call returns. Holding every frame for the execution's duration would retain one
// Map per send in a long loop while changing no semantics.
class LexicalCellArena {
  #closureCells = new Map();

  allocateFrame() {
    return new LexicalFrame();
  }

  // The transient association between a closure Block created in this execution and the cells it
  // captured. The durable environment cannot express cell identity, so this is what lets a
  // same-execution closure resolve the *declaring* frame's cell rather than a snapshot.
  //
  // Nested by imageId then objectId, because a Block ref is a two-part identity and flattening it
  // into one string is not injective: object ids are arbitrary non-empty text, so any separator can
  // itself appear inside a part. `a<sep>b` + `c` and `a` + `b<sep>c` would then collide and one
  // closure would resolve another closure's cells. A tuple lookup cannot be got wrong this way.
  associate(blockRef, cells) {
    if (cells.size === 0) return;
    let byObject = this.#closureCells.get(blockRef.imageId);
    if (!byObject) {
      byObject = new Map();
      this.#closureCells.set(blockRef.imageId, byObject);
    }
    byObject.set(blockRef.objectId, new Map(cells));
  }

  capturedCells(blockRef) {
    return this.#closureCells.get(blockRef.imageId)?.get(blockRef.objectId) ?? null;
  }

  // One lexical activation's view: its own fresh frame, plus the cells the Block being activated
  // captured when some earlier activation in this same execution created it.
  activationCells(blockRef) {
    return new ActivationCells(this, this.allocateFrame(), this.capturedCells(blockRef));
  }

  // ADR 0050 decision 10a. The frame in force where a closure was created, so activating it later in
  // the *same* execution restores lexical `self`. Deliberately here rather than in a durable record:
  // a persisted defining Behavior would be forgeable data, which is the vector self-only exists to
  // close. Dying with the arena is the feature.
  associateFrame(blockRef, frame) {
    this.frames ??= new TupleMap(2);
    this.frames.set([blockRef.imageId, blockRef.objectId], frame);
  }

  frameFor(blockRef) {
    return this.frames?.get([blockRef.imageId, blockRef.objectId]) ?? null;
  }

  // ADR 0052 decision 5a. Closure instances that have not escaped live here rather than in the
  // graph, keyed by the same instance ref the cells and frame above are keyed by — one keying
  // scheme, so an instance's cells, frame and definition are all reached the same way.
  //
  // The stored shapes deliberately mirror the durable Block and LexicalEnvironment records field for
  // field. Promotion is then a copy rather than a translation, which is what keeps a promoted
  // closure the same representation as one written eagerly.
  #instances = new TupleMap(2);

  #mint(imageId, kind, record) {
    const objectId = transientObjectId(`${kind}/${this.#nextInstance += 1}/${this.#nonce}`);
    this.#instances.set([imageId, objectId], record);
    return objectRef(imageId, objectId);
  }

  #nextInstance = 0;

  // Per-arena, so a transient id minted by one execution can never be mistaken for one minted by
  // another — including after an arena is gone, where the id must read as expired rather than as
  // some other execution's live instance.
  #nonce = randomUUID();

  // The instance's image is its prototype's, so dispatch-image behaviour needs no special case for
  // a transient receiver (ADR 0044 decision 5a, ADR 0051 decision 3).
  mintClosureBlock(imageId, {code, environment = null, metadata = {}}) {
    return this.#mint(imageId, 'block', Object.freeze({
      kind: 'block', code, environment, metadata: Object.freeze({...metadata}),
    }));
  }

  mintClosureEnvironment(imageId, {bindings, parent = null}) {
    return this.#mint(imageId, 'environment', Object.freeze({
      kind: 'lexical-environment', bindings: Object.freeze({...bindings}), parent,
    }));
  }

  // ADR 0060 decision 3. An object allocated inside this execution begins here rather than in the
  // durable store: `basicNew` and condition allocation mint into the arena, and the object becomes
  // durable only if a reference crosses a durability boundary. The record mirrors the durable
  // object record field for field — shape, behavior, slots, indexed, metadata — so promotion is a
  // copy rather than a translation, exactly as ADR 0052 made it for closures.
  mintObject(imageId, {shape, behavior, slots = {}, indexed = null, metadata = {}}) {
    return this.#mint(imageId, 'object', Object.freeze({
      kind: 'object',
      shape,
      behavior,
      slots: Object.freeze({...slots}),
      // A non-indexed Shape omits the property entirely, preserving the durable record form.
      ...(indexed === null ? {} : {indexed: Object.freeze([...indexed])}),
      metadata: Object.freeze({...metadata}),
    }));
  }

  transientRecord(imageId, objectId) {
    return this.#instances.get([imageId, objectId]) ?? null;
  }

  // ADR 0060: a slot or indexed write to an object that has not escaped stays in the arena. The
  // record is replaced whole (slots and indexed are immutable snapshots), mirroring the durable
  // whole-record rewrite, so a later read in the same execution sees the new state and a promotion
  // that follows publishes the latest. There is no version to CAS on — the record is
  // execution-local, so the only writer is this execution itself.
  mutateTransientObject(imageId, objectId, {slots = null, indexed = null} = {}) {
    const key = [imageId, objectId];
    const record = this.#instances.get(key);
    if (!record) throw new ExpiredClosureInstanceError(imageId, objectId);
    if (record.kind !== 'object') {
      throw new TypeError(`only a transient object can be mutated: ${imageId}/${objectId}`);
    }
    this.#instances.set(key, Object.freeze({
      ...record,
      slots: slots === null ? record.slots : Object.freeze({...slots}),
      ...(indexed === null
        ? (Object.hasOwn(record, 'indexed') ? {indexed: record.indexed} : {})
        : {indexed: Object.freeze([...indexed])}),
    }));
  }

  transientEntries() {
    return this.#instances.entries();
  }

  // ADR 0052 decision 7a. Lives on the arena so promotion is idempotent for the whole execution
  // rather than per boundary: a closure written into two slots must be one closure both times.
  #promotionMemo = new TupleMap(2);

  promotionMemo() {
    return this.#promotionMemo;
  }

  // ADR 0054. Kept on the arena because its lifetime is the arena's: a handler established in this
  // execution must not be findable from a later one, for the same reason a defining frame is not.
  #conditions = null;

  conditionRuntime() {
    this.#conditions ??= new ConditionRuntime();
    return this.#conditions;
  }
}

// What an executor is given. Deliberately narrow: declare a slot, resolve one, associate a new
// closure. No frame, no arena and no cell contents leak through it, so both execution lanes share
// one lexical-state model instead of each growing its own.
class ActivationCells {
  #arena;
  #frame;
  #captured;

  constructor(arena, frame, captured) {
    this.#arena = arena;
    this.#frame = frame;
    this.#captured = captured;
  }

  // One place, before the neutral and WASM lanes diverge. Four executors independently learning
  // about `nil` is the lane-dependent-semantics mistake ADR 0043 decision 10 forbids.
  declare(temporaries, initialContents = UNBOUND) {
    for (const {id, name} of temporaries) this.#frame.declare(id, name, initialContents);
  }

  // This activation's own slot first, then a captured cell — never the other way round, so a
  // recursive activation shadows the identically-named static slot it captured.
  resolve(id) {
    return this.#frame.own(id) ?? this.#captured?.get(id) ?? null;
  }

  associate(blockRef, cells) {
    this.#arena.associate(blockRef, cells);
  }
}



// ADR 0052 decision 5a: Block resolution is arena-first, then durable.
//
// Delivered as a view over the images service rather than as a new parameter on every reader,
// because the readers that must see a transient instance — `prepareActivation`, the language
// dispatcher's Block recognition, binding lookup — all already take an images service. A view keeps
// one resolution rule in one place instead of three call sites remembering to check the arena.
//
// The view is execution context in exactly the way `dispatchImage` is: it is built per execution,
// it reaches no durable record, and it dies with the arena.
function arenaImagesView(images, arena) {
  if (!arena) return images;
  const view = Object.create(images);
  const transient = (imageId, objectId, kind) => {
    const record = arena.transientRecord(imageId, objectId);
    if (!record) return null;
    return record.kind === kind ? record : null;
  };
  // Durable fallback is never reached for a reserved id, because decision 5b forbids a durable
  // record from taking one. A reserved id absent from this arena is therefore an *expired*
  // instance, which is a lifetime error rather than a missing record — and saying so is the
  // difference between "your closure outlived its execution" and "your image is corrupt".
  //
  // One nuance ADR 0060 forces: the dispatcher asks *every* object receiver "are you a Block?"
  // first (ADR 0044's Block-personality check), so a transient *object* is looked up as a Block on
  // every send to it. That is a negative answer, not an expiry — the id is live in the arena as a
  // different kind, and only a reserved id present *nowhere* in the arena has outlived its
  // execution. So "not this kind" answers null and lets the durable-negative fall through, while
  // "not in the arena at all" is the lifetime error.
  const resolve = async (imageId, objectId, kind, durable) => {
    const record = arena.transientRecord(imageId, objectId);
    if (record) return record.kind === kind ? record : null;
    if (isTransientObjectId(objectId)) {
      throw new ExpiredClosureInstanceError(imageId, objectId);
    }
    return await durable.call(images, imageId, objectId);
  };
  view.getBlock = (imageId, objectId) => resolve(imageId, objectId, 'block', images.getBlock);
  view.getLexicalEnvironment = (imageId, objectId) =>
    resolve(imageId, objectId, 'lexical-environment', images.getLexicalEnvironment);
  // ADR 0060: object reads resolve arena-first, exactly as Block reads already do — so a primitive
  // holding a transient receiver (a `basicNew` result, an unhandled condition still in its
  // execution) sees its state without the object ever becoming durable. The durable fallback is
  // never reached for a reserved id, for the same reason as above.
  // A transient record's id is its arena key rather than a stored field, but every reader and
  // writer below the view addresses a record by `record.id` — the whole-record rewrites in the
  // slot, indexed and Dictionary primitives all rebuild from it. Surface the id on the record the
  // view answers so those paths work unchanged against a transient object; the durable record
  // already carries its own id.
  view.getObject = async (imageId, objectId) => {
    const record = arena.transientRecord(imageId, objectId);
    if (record) {
      if (record.kind !== 'object') return null;
      return Object.freeze({...record, id: objectId});
    }
    if (isTransientObjectId(objectId)) throw new ExpiredClosureInstanceError(imageId, objectId);
    return await images.getObject(imageId, objectId);
  };
  // A write naming a reserved id is a write to an object in this arena. `basicNew`'s whole point is
  // that the id is minted transient and the record lives here — so the write updates the arena.
  // But ADR 0060 decision 4 makes the object *one object across promotion*: if this transient id is
  // already registered as promoted (the arena's memo, keyed exactly as the promoter keys it), the
  // mutation must also reach the durable record, or the durable copy goes stale the moment Smalltalk
  // code mutates an escaped object — which a cyclic structure does while its own promotion is still
  // resolving. The durable id is derived, so the write converges on the same identity; the arena is
  // updated too, so the rest of this execution keeps reading the new state. A durable id that is
  // not transient falls through to the durable store unchanged.
  view.putObject = async (imageId, record, options = {}) => {
    if (isTransientObjectId(record?.id)) {
      const existing = arena.transientRecord(imageId, record.id);
      if (!existing) throw new ExpiredClosureInstanceError(imageId, record.id);
      arena.mutateTransientObject(imageId, record.id, {
        slots: record.slots,
        indexed: Object.hasOwn(record, 'indexed') ? record.indexed : null,
      });
      const promoted = arena.promotionMemo().get([imageId, record.id]);
      if (promoted) {
        // The durable id is derived from the transient one by the promoter's rule. The durable
        // record already exists (promotion wrote it), so this is a mutation of it. A value written
        // now may itself be transient — a backing Array allocated *after* its OrderedCollection
        // escaped — and writing that ref unpromoted would dangle, so the new state is promoted
        // through the same central operation first. Within one execution the only writer is this
        // execution, so the read-then-write CAS cannot race here.
        const durableId = promoted.ref.objectId;
        const current = await images.getObject(imageId, durableId);
        if (current) {
          const promoteValue = arena.postPromotionPromoter
            ?? ((v) => v);
          const slots = {};
          for (const [slotId, value] of Object.entries(record.slots)) {
            slots[slotId] = await promoteValue(value);
          }
          await images.putObject(imageId, {
            id: durableId,
            shape: record.shape,
            behavior: record.behavior,
            slots,
            ...(Object.hasOwn(record, 'indexed')
              ? {indexed: await Promise.all(record.indexed.map(promoteValue))}
              : {}),
            metadata: record.metadata,
          }, {expectedVersion: current._version});
        }
      }
      return record;
    }
    return await images.putObject(imageId, record, options);
  };
  return view;
}

export {
  ActivationCells,
  EscapingMutableClosureError,
  ExpiredClosureInstanceError,
  MissingLexicalCellError,
  LexicalCell,
  LexicalCellArena,
  LexicalFrame,
  UNBOUND,
  UnboundBindingError,
  arenaImagesView,
