// ADR 0054: conditions and handlers.
//
// Two halves. The unwind operations are Block selectors, so they arrive through a discoverable
// protocol object exactly as ADR 0051's loop selectors do — but a *separate* one, because that
// protocol is an exact two-slot record existing images already hold, and widening it would turn its
// exactness check into a migration. An image holding one protocol and not the other is coherent.
//
// The transfer protocol is ordinary methods on an ordinary class: `signal`, `resume:`, `return:` are
// sends to a condition object, which is an ordinary persistent object (decision 1a). Only the signal
// *occurrence* is transient, and it lives in the execution's condition runtime.
const SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1 = 'smalltalk-block-unwind-protocol/v1';
const BLOCK_UNWIND_PROTOCOL_OBJECT_ID = 'smalltalk-block-unwind-protocol/v1';
const BLOCK_UNWIND_PROTOCOL_SHAPE_ID = 'smalltalk/block-unwind-protocol-shape/v1';

const UNWIND_SLOTS = Object.freeze([
  Object.freeze({
    id: 'block-unwind-on-do',
    name: 'onDo',
    primitive: SMALLTALK_PRIMITIVE.BLOCK_ON_DO,
    blockId: 'smalltalk/primitive/block-on-do',
  }),
  Object.freeze({
    id: 'block-unwind-ensure',
    name: 'ensure',
    primitive: SMALLTALK_PRIMITIVE.BLOCK_ENSURE,
    blockId: 'smalltalk/primitive/block-ensure',
  }),
  Object.freeze({
    id: 'block-unwind-if-curtailed',
    name: 'ifCurtailed',
    primitive: SMALLTALK_PRIMITIVE.BLOCK_IF_CURTAILED,
    blockId: 'smalltalk/primitive/block-if-curtailed',
  }),
]);

const CONDITION_PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.CONDITION_SIGNAL]: 'smalltalk/primitive/condition-signal',
  [SMALLTALK_PRIMITIVE.CONDITION_RESUME]: 'smalltalk/primitive/condition-resume',
  [SMALLTALK_PRIMITIVE.CONDITION_RETURN]: 'smalltalk/primitive/condition-return',
});

const CONDITION_CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.CONDITION_SIGNAL]: 'primitiveConditionSignal',
  [SMALLTALK_PRIMITIVE.CONDITION_RESUME]: 'primitiveConditionResume',
  [SMALLTALK_PRIMITIVE.CONDITION_RETURN]: 'primitiveConditionReturn',
});

// The condition hierarchy. Deliberately shallow: this ADR makes failures catchable, and a rich
// taxonomy is library work rather than a substrate decision.
const CONDITION_CLASSES = Object.freeze([
  {name: 'Exception', superclass: null},
  {name: 'Error', superclass: 'Exception'},
  {name: 'IndexOutOfRange', superclass: 'Error'},
  {name: 'EmptyCollection', superclass: 'Error'},
  // ADR 0054 decision 8's "now" set: the existing host errors that gain a Smalltalk-visible class.
  {name: 'ZeroDivide', superclass: 'Error'},
  {name: 'IndexBounds', superclass: 'Error'},
  {name: 'KeyNotFound', superclass: 'Error'},
]);




class SmalltalkConditionProtocolError extends TypeError {
  constructor(imageId, detail) {
    super(`Symmetric Smalltalk Block unwind protocol in ${imageId} is corrupt: ${detail}`);
    this.name = 'SmalltalkConditionProtocolError';
    this.imageId = imageId;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function installPrimitiveBlock({images, imageId, primitive, blockId}) {
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${blockId}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id: blockId,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

const RECEIVER = Object.freeze({op: 'receiver'});
const ARGUMENT = Object.freeze({op: 'argument', index: 0});

const applyPrimitive = (blockId, args) => ({
  op: 'send',
  languageId: SYMMETRIC_SMALLTALK_ID,
  receiver: {op: 'binding', id: blockId},
  message: textValue(args.length === 1 ? 'value:' : 'value:value:'),
  arguments: args,
});

async function installSmalltalkConditionProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Primitives before anything that points at them.
  const unwind = {};
  for (const slot of UNWIND_SLOTS) {
    unwind[slot.id] = await installPrimitiveBlock({
      images, imageId, primitive: slot.primitive, blockId: slot.blockId,
    });
  }
  const conditionPrimitives = {};
  for (const [primitive, blockId] of Object.entries(CONDITION_PRIMITIVE_BLOCK_ID)) {
    conditionPrimitives[primitive] = await installPrimitiveBlock({images, imageId, primitive, blockId});
  }

  const shapeRecord = await ensureShape(images, imageId, {
    id: BLOCK_UNWIND_PROTOCOL_SHAPE_ID,
    slots: UNWIND_SLOTS.map(({id, name}) => ({id, name})),
  });
  await ensureObject(images, imageId, {
    id: BLOCK_UNWIND_PROTOCOL_OBJECT_ID,
    shape: objectRef(imageId, shapeRecord.id),
    behavior: null,
    slots: unwind,
    metadata: {protocol: SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1},
  });

  // The condition classes, and `messageText` so a condition can carry a description.
  const instanceShapeRef = await (async () => {
    const record = await ensureShape(images, imageId, {
      id: EXCEPTION_SHAPE_ID,
      slots: [{id: 'exception-message-text', name: 'messageText'}],
    });
    return objectRef(imageId, record.id);
  })();

  // `ensureNamedClass` rather than `defineClass`: re-installation must converge, and `defineClass`
  // also ensures an empty method dictionary, so it conflicts once `Exception` has methods. The same
  // reason the library uses it.
  const classes = {};
  for (const {name, superclass} of CONDITION_CLASSES) {
    classes[name] = (await ensureNamedClass({
      images,
      imageId,
      name,
      instanceShapeRef,
      superclassRef: superclass ? classes[superclass] : kernel.objectClass,
    })).classRef;
  }

  const capture = (primitive) => Object.freeze({
    id: CONDITION_PRIMITIVE_BLOCK_ID[primitive],
    name: CONDITION_CAPTURE_NAME[primitive],
  });
  const signalCapture = capture(SMALLTALK_PRIMITIVE.CONDITION_SIGNAL);
  const resumeCapture = capture(SMALLTALK_PRIMITIVE.CONDITION_RESUME);
  const returnCapture = capture(SMALLTALK_PRIMITIVE.CONDITION_RETURN);

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: classes.Exception,
    methods: [
      {
        selector: 'signal',
        program: {
          parameters: [],
          captures: [{...signalCapture}],
          body: applyPrimitive(signalCapture.id, [RECEIVER]),
        },
        captures: [{...signalCapture, value: conditionPrimitives[SMALLTALK_PRIMITIVE.CONDITION_SIGNAL]}],
      },
      {
        selector: 'resume:',
        program: {
          parameters: [{id: 'resume:arg', name: 'value'}],
          captures: [{...resumeCapture}],
          body: applyPrimitive(resumeCapture.id, [RECEIVER, ARGUMENT]),
        },
        captures: [{...resumeCapture, value: conditionPrimitives[SMALLTALK_PRIMITIVE.CONDITION_RESUME]}],
      },
      {
        selector: 'return:',
        program: {
          parameters: [{id: 'return:arg', name: 'value'}],
          captures: [{...returnCapture}],
          body: applyPrimitive(returnCapture.id, [RECEIVER, ARGUMENT]),
        },
        captures: [{...returnCapture, value: conditionPrimitives[SMALLTALK_PRIMITIVE.CONDITION_RETURN]}],
      },
      // No `messageText` accessor yet. It was a literal `''` — which is worse than absent, since it
      // silently answered the wrong thing for a condition that *does* carry text. Reading the slot
      // needs ADR 0050's instance-slot primitive, so this protocol would have to depend on the
      // instance-variable protocol; that dependency is a decision rather than a detail. The text is
      // still stored on every host-generated condition, so the accessor can arrive without a
      // migration.
    ],
  });

  return Object.freeze({
    protocol: SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1,
    ref: objectRef(imageId, BLOCK_UNWIND_PROTOCOL_OBJECT_ID),
    ...classes,
  });
}

// Discovery mirrors `findSmalltalkBlockProtocol` exactly: absent stays distinct from corrupt, and
// each slot's target is proven to be the primitive that slot claims rather than merely being a
// local ref.
async function findSmalltalkBlockUnwindProtocol({images, imageId} = {}) {
  requiredText(imageId, 'block unwind protocol image id');
  const record = await images.getObject(imageId, BLOCK_UNWIND_PROTOCOL_OBJECT_ID);
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1) {
    throw new SmalltalkConditionProtocolError(imageId, `object does not declare ${SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1}`);
  }
  if (!isLocalRef(record.shape, imageId, BLOCK_UNWIND_PROTOCOL_SHAPE_ID)) {
    throw new SmalltalkConditionProtocolError(imageId, `object does not have shape ${BLOCK_UNWIND_PROTOCOL_SHAPE_ID}`);
  }
  const refs = {};
  for (const slot of UNWIND_SLOTS) {
    const value = record.slots?.[slot.id];
    if (!isLocalRef(value, imageId)) {
      throw new SmalltalkConditionProtocolError(imageId, `slot ${slot.name} must be an unpinned local ref`);
    }
    const block = await images.getBlock(value.imageId, value.objectId);
    if (!block) throw new SmalltalkConditionProtocolError(imageId, `slot ${slot.name} does not reference a Block`);
    const code = block.code && await images.getCodeArtifact(block.code.imageId, block.code.objectId);
    if (!code) {
      throw new SmalltalkConditionProtocolError(imageId, `slot ${slot.name} references a Block with no code artifact`);
    }
    if (code.representation !== SMALLTALK_KERNEL_PRIMITIVE_V1) {
      throw new SmalltalkConditionProtocolError(imageId, `slot ${slot.name} does not reference a kernel primitive`);
    }
    // The same strict contract ADR 0051 uses, not a private JSON read: this object routes dispatch,
    // so a malformed declaration must be refused by the parser that owns that format rather than
    // by whatever a local `JSON.parse` happens to tolerate.
    let declared;
    try {
      declared = parsePrimitiveCode(code);
    } catch (error) {
      throw new SmalltalkConditionProtocolError(imageId, `slot ${slot.name} references an unreadable primitive`, {cause: error});
    }
    if (declared !== slot.primitive) {
      throw new SmalltalkConditionProtocolError(
        imageId, `slot ${slot.name} references the ${declared} primitive, not ${slot.primitive}`,
      );
    }
    refs[slot.name] = value;
  }
  return Object.freeze({protocol: SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1, ref: objectRef(imageId, record.id), ...refs});
}

// Workstream 3 (MessagePack pressure). `Exception>>messageText`, installed as a *separate* pass
// rather than inside `installSmalltalkConditionProtocol`. The condition installer deliberately does
// not take the ADR 0050 instance-variable dependency (see the note at its method list); this
// installer runs after `installSmalltalkInstanceVariableProtocol`, so the class-scoped compiler can
// lower the slot read to the ordinary slot primitive. The slot itself predates this accessor and is
// populated with non-empty text on every host-generated condition, so nothing migrates — a host
// `ZeroDivide` from `1 // 0` already carries its message.
async function installSmalltalkExceptionAccessors({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const exceptionClass = objectRef(imageId, 'smalltalk/class/Exception');
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: exceptionClass,
    methods: [
      {selector: 'messageText', source: '[ ^messageText ]'},
    ],
  });
  return Object.freeze({exceptionClass});
}

export {
  BLOCK_UNWIND_PROTOCOL_OBJECT_ID,
  BLOCK_UNWIND_PROTOCOL_SHAPE_ID,
  CONDITION_CLASSES,
  SMALLTALK_BLOCK_UNWIND_PROTOCOL_V1,
  SmalltalkConditionProtocolError,
  UNWIND_SLOTS,
  findSmalltalkBlockUnwindProtocol,
  installSmalltalkConditionProtocol,
  installSmalltalkExceptionAccessors,
};

import {booleanValue, isObjectRef, textValue} from '../value/index.js';
import {defineMethods} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0045: Symmetric Smalltalk's conditionals, as ordinary methods on True and False.
//
// Nothing here is a primitive. Each method either evaluates one of its block arguments through an
// ordinary `value` send — which ADR 0044 decision 11 answers without a class — or answers `nil`,
// which it names through an ordinary captured binding rather than through an operation in the
// common IR. The compiler recognizes none of these selectors; a source conditional is a keyword
// send like any other, and the branch is taken by dispatch choosing True's method or False's.
//
// This is an installer, deliberately separate from `installSmalltalkKernel`. The kernel bootstrap
// creates identity; protocol arrives afterwards, per lane, exactly as `+` does. An image with a
// kernel and no control-flow protocol fails as message-not-understood, which is a coherent state.
const NIL_CAPTURE = Object.freeze({id: 'smalltalk/control-flow/nil', name: 'nil'});

// What each class does for each selector. Written as one table rather than hand-built programs so
// the symmetry is checkable by reading it: every selector appears once per class, and no two entries
// can drift apart in shape.
//
//   a number   evaluate that argument, by sending it `value`
//   null       answer nil
//   a boolean  answer that canonical boolean Value (ADR 0056)
//
// The Boolean protocol needed no second publication surface: `and:`/`or:` are the same shape as the
// conditionals — evaluate an argument, or answer without mentioning it — and their laziness falls
// out of that rather than being arranged. An arm that answers a literal never names the argument, so
// the Block simply is not evaluated.
const CONDITIONAL_PROTOCOL = Object.freeze([
  {selector: 'ifTrue:', parameters: ['aBlock'], True: 0, False: null},
  {selector: 'ifFalse:', parameters: ['aBlock'], True: null, False: 0},
  {selector: 'ifTrue:ifFalse:', parameters: ['trueBlock', 'falseBlock'], True: 0, False: 1},
  {selector: 'ifFalse:ifTrue:', parameters: ['falseBlock', 'trueBlock'], True: 1, False: 0},
  // ADR 0056 decision 4. Ordinary methods through ADR 0045's bridge; the compiler learns nothing.
  {selector: 'not', parameters: [], True: false, False: true},
  {selector: 'and:', parameters: ['aBlock'], True: 0, False: false},
  {selector: 'or:', parameters: ['aBlock'], True: true, False: 0},
]);

// ADR 0056 added three rows to the table above, so these are derived by *role* rather than by
// "everything in the table". `SMALLTALK_CONDITIONAL_SELECTORS` is public and has always meant the
// four conditionals; silently widening it would change what an existing name means, which is exactly
// the drift the reserved-word rule guards against one level down.
const BOOLEAN_SELECTORS = Object.freeze(['not', 'and:', 'or:']);

const SMALLTALK_CONDITIONAL_SELECTORS = Object.freeze(
  CONDITIONAL_PROTOCOL.map(({selector}) => selector).filter((selector) => !BOOLEAN_SELECTORS.includes(selector)),
);
const SMALLTALK_BOOLEAN_SELECTORS = Object.freeze([...BOOLEAN_SELECTORS]);
// Everything this installer publishes, for callers that mean exactly that.
const SMALLTALK_CONTROL_FLOW_SELECTORS = Object.freeze(CONDITIONAL_PROTOCOL.map(({selector}) => selector));

// The kernel slot naming each singleton, and the class it is an instance of. `True` and `False` have
// no kernel slot of their own, so the class is read from the singleton rather than named here.
const SINGLETONS = Object.freeze([
  {kernelSlot: 'true', className: 'True'},
  {kernelSlot: 'false', className: 'False'},
]);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// One method, as a semantic program plus the capture values its bindings need. `lagrange-code/v0`
// carries capture *descriptors*; the values live in the Block's lexical environment, which is what
// keeps `nil` an object in the graph rather than a meaning taught to the IR.
function conditionalMethod({selector, parameters, evaluate, nilRef}) {
  const parameterDescriptors = parameters.map((name, index) => ({
    id: `${selector}:parameter:${index}`,
    name,
  }));
  // ADR 0056: an arm that answers a boolean answers the canonical *Value*, not the singleton — the
  // singleton is a dispatch personality (ADR 0045), and a boolean-answering method must not quietly
  // convert one into the other.
  if (typeof evaluate === 'boolean') {
    return {
      selector,
      program: {
        parameters: parameterDescriptors,
        captures: [],
        body: {op: 'literal', value: booleanValue(evaluate)},
      },
      captures: [],
    };
  }
  if (evaluate === null) {
    return {
      selector,
      program: {
        parameters: parameterDescriptors,
        captures: [{...NIL_CAPTURE}],
        body: {op: 'binding', id: NIL_CAPTURE.id},
      },
      captures: [{...NIL_CAPTURE, value: nilRef}],
    };
  }
  return {
    selector,
    program: {
      parameters: parameterDescriptors,
      captures: [],
      // The block is invoked through the existing ordinary value path, so the whole conditional is
      // two sends: one that chose this method, and this one.
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'argument', index: evaluate},
        message: textValue('value'),
        arguments: [],
      },
    },
    captures: [],
  };
}

// The class of a singleton, read from the singleton itself rather than from a kernel slot. `True`
// and `False` have no kernel slot of their own, and going through the object is also the exact path
// the dispatcher's boolean bridge takes — so installing onto anything else would install onto a
// class the bridge does not reach.
async function classOfSingleton(images, singletonRef, label) {
  const record = await images.getObject(singletonRef.imageId, singletonRef.objectId);
  if (!record) throw new TypeError(`Smalltalk kernel ${label} not found: ${singletonRef.imageId}/${singletonRef.objectId}`);
  if (!isObjectRef(record.behavior)) {
    throw new TypeError(`Smalltalk kernel ${label} has no behavior: ${singletonRef.imageId}/${singletonRef.objectId}`);
  }
  return record.behavior;
}

async function installSmalltalkControlFlow({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const installed = {};
  for (const {kernelSlot, className} of SINGLETONS) {
    const classRef = await classOfSingleton(images, kernel[kernelSlot], kernelSlot);
    await defineMethods({
      images,
      compilation,
      imageId,
      classRef,
      lane,
      methods: CONDITIONAL_PROTOCOL.map((entry) => conditionalMethod({
        selector: entry.selector,
        parameters: entry.parameters,
        evaluate: entry[className],
        nilRef: kernel.nil,
      })),
    });
    installed[className] = classRef;
  }
  // ifNil:/ifNotNil: — the nil-checking protocol, installed on UndefinedObject (nil) and
  // Object (everything else). Ordinary Smalltalk methods over the existing conditional
  // and identity protocol: no new primitive, no compiler knowledge.
  //
  // UndefinedObject (nil): ifNil: evaluates the block; ifNotNil: answers nil.
  // Object (everything else): ifNil: answers self; ifNotNil: evaluates the block.
  const undefinedObjectClass = await classOfSingleton(images, kernel.nil, 'nil');
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: undefinedObjectClass,
    methods: [
      {selector: 'ifNil:', source: '[ :aBlock | ^ aBlock value ]'},
      {selector: 'ifNotNil:', source: '[ :aBlock | ^ nil ]'},
    ],
  });
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      {selector: 'ifNil:', source: '[ :aBlock | ^ self ]'},
      {selector: 'ifNotNil:', source: '[ :aBlock | ^ aBlock value ]'},
    ],
  });

  return Object.freeze({
    trueClass: installed.True,
    falseClass: installed.False,
    undefinedObjectClass,
    selectors: SMALLTALK_CONTROL_FLOW_SELECTORS,
  });
}

export {
  NIL_CAPTURE as SMALLTALK_CONTROL_FLOW_NIL_CAPTURE,
  SMALLTALK_BOOLEAN_SELECTORS,
  SMALLTALK_CONDITIONAL_SELECTORS,
  SMALLTALK_CONTROL_FLOW_SELECTORS,
  installSmalltalkControlFlow,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, canonicalizeValue, integerValue} from '../value/index.js';

// ADR 0048 decisions 5 and 6: the durable Dictionary representation, as pure functions.
//
// Kept free of installers, executors and image services on purpose. A test can then prove the
// representation directly rather than only through surface sends, and a later MethodDictionary fast
// path can read the same layout without dragging in the Dictionary protocol.
const DICTIONARY_SHAPE_ID = 'smalltalk/dictionary-shape/v1';
const DICTIONARY_TABLE_SHAPE_ID = 'smalltalk/dictionary-table-shape/v1';
const DICTIONARY_TABLE_SLOT = 'dictionary-table';
const DICTIONARY_TALLY_SLOT = 'dictionary-table-tally';

const DICTIONARY_SHAPE_SLOTS = Object.freeze([{id: DICTIONARY_TABLE_SLOT, name: 'table'}]);
const DICTIONARY_TABLE_SHAPE_SLOTS = Object.freeze([{id: DICTIONARY_TALLY_SLOT, name: 'tally'}]);

// Power of two so the probe start is a mask-equivalent modulo, and at least 8 so a small dictionary
// still has slack before its first growth.
const DICTIONARY_MINIMUM_CAPACITY = 8;
const DICTIONARY_LOAD_NUMERATOR = 3;
const DICTIONARY_LOAD_DENOMINATOR = 4;

// Three Values per bucket. Occupancy is the *hash* cell rather than the key cell, which is what
// leaves `nil` usable as an ordinary key instead of being stolen as an empty sentinel.
const BUCKET_WIDTH = 3;

class SmalltalkDictionaryTableError extends TypeError {
  constructor(message) {
    super(`malformed Dictionary table: ${message}`);
    this.name = 'SmalltalkDictionaryTableError';
  }
}

function isIntegerValue(value) {
  return Boolean(value) && value.kind === VALUE_KIND.INTEGER;
}

function capacityOf(indexedLength) {
  if (indexedLength % BUCKET_WIDTH !== 0) {
    throw new SmalltalkDictionaryTableError(`indexed length ${indexedLength} is not a multiple of ${BUCKET_WIDTH}`);
  }
  const capacity = indexedLength / BUCKET_WIDTH;
  if (capacity < DICTIONARY_MINIMUM_CAPACITY || (capacity & (capacity - 1)) !== 0) {
    throw new SmalltalkDictionaryTableError(`capacity ${capacity} is not a power of two of at least ${DICTIONARY_MINIMUM_CAPACITY}`);
  }
  return capacity;
}

function emptyBuckets(capacity) {
  return Array.from({length: capacity}, () => ({hash: null, key: null, value: null}));
}

// Buckets -> the flat indexed part. `nil` fills all three cells of an empty bucket, so an empty
// bucket is indistinguishable from one that never held anything — there are no tombstones in v1
// because there is no removal.
function indexedFromBuckets(buckets, nilRef) {
  const indexed = [];
  for (const bucket of buckets) {
    if (bucket.hash === null) {
      indexed.push(nilRef, nilRef, nilRef);
      continue;
    }
    indexed.push(bucket.hash, bucket.key, bucket.value);
  }
  return indexed;
}

function bucketsFromIndexed(indexed) {
  const capacity = capacityOf(indexed.length);
  const buckets = [];
  for (let index = 0; index < capacity; index += 1) {
    const base = index * BUCKET_WIDTH;
    const hash = indexed[base];
    if (!isIntegerValue(hash)) {
      buckets.push({hash: null, key: null, value: null});
      continue;
    }
    buckets.push({hash, key: indexed[base + 1], value: indexed[base + 2]});
  }
  return buckets;
}

// Linear probing from the floor-modulo of the hash. Floor rather than truncating remainder because
// a user-defined `hash` may answer a negative Integer, and a negative start index would otherwise
// probe outside the table.
function probeStart(hashValue, capacity) {
  if (!isIntegerValue(hashValue)) {
    throw new SmalltalkDictionaryTableError('a stored or query hash must be an Integer Value');
  }
  const capacityBig = BigInt(capacity);
  const raw = BigInt(hashValue.value) % capacityBig;
  return Number(((raw % capacityBig) + capacityBig) % capacityBig);
}

function* probeSequence(hashValue, capacity) {
  const start = probeStart(hashValue, capacity);
  for (let step = 0; step < capacity; step += 1) {
    yield (start + step) % capacity;
  }
}

function sameStoredHash(left, right) {
  return isIntegerValue(left) && isIntegerValue(right) && BigInt(left.value) === BigInt(right.value);
}

// Growth is decided from the count the table would have *after* the insert, so a table never
// publishes at a load above the limit and then grows on the following write.
function needsGrowth(tallyAfterInsert, capacity) {
  return tallyAfterInsert * DICTIONARY_LOAD_DENOMINATOR > capacity * DICTIONARY_LOAD_NUMERATOR;
}

function grownCapacity(capacity) {
  return capacity * 2;
}

// Reinsertion after growth places entries by their **stored** hashes. A key is never sent `hash`
// again merely because the table grew: that would re-run user code during an internal resize, and
// a key whose hash had since changed would silently relocate.
function reinsert(buckets, capacity) {
  const grown = emptyBuckets(capacity);
  for (const bucket of buckets) {
    if (bucket.hash === null) continue;
    let placed = false;
    for (const index of probeSequence(bucket.hash, capacity)) {
      if (grown[index].hash === null) {
        grown[index] = {...bucket};
        placed = true;
        break;
      }
    }
    if (!placed) throw new SmalltalkDictionaryTableError('grown table has no free bucket, which cannot happen below the load factor');
  }
  return grown;
}

function tallyOf(buckets) {
  return buckets.reduce((count, bucket) => count + (bucket.hash === null ? 0 : 1), 0);
}

// The durable form of a table snapshot, ready for `putObject`. `behavior` is deliberately absent:
// DictionaryTable is a language-owned internal graph object, not a public Smalltalk class.
function tableRecordFields({buckets, shapeRef, nilRef}) {
  return {
    shape: shapeRef,
    slots: {[DICTIONARY_TALLY_SLOT]: integerValue(tallyOf(buckets))},
    indexed: indexedFromBuckets(buckets, nilRef),
    metadata: {smalltalk: 'dictionary-table'},
  };
}

// Read a stored table, validating what the representation promises rather than trusting it. A
// dictionary whose tally disagrees with its buckets would make `size` lie, and a mis-sized indexed
// part would make probing read the wrong cells.
function readTableRecord(record) {
  if (!record || record.kind !== 'object') throw new SmalltalkDictionaryTableError('table record is not an object');
  if (!Object.hasOwn(record, 'indexed')) throw new SmalltalkDictionaryTableError('table record has no indexed part');
  const buckets = bucketsFromIndexed(record.indexed);
  const tally = record.slots?.[DICTIONARY_TALLY_SLOT];
  if (!isIntegerValue(tally)) throw new SmalltalkDictionaryTableError('table tally must be an Integer Value');
  const counted = tallyOf(buckets);
  if (BigInt(tally.value) !== BigInt(counted)) {
    throw new SmalltalkDictionaryTableError(`table tally ${tally.value} disagrees with ${counted} occupied buckets`);
  }
  return {buckets, capacity: buckets.length, tally: counted};
}

function sameCanonicalValue(left, right) {
  return JSON.stringify(canonicalizeValue(left)) === JSON.stringify(canonicalizeValue(right));
}

export {
  BUCKET_WIDTH,
  DICTIONARY_LOAD_DENOMINATOR,
  DICTIONARY_LOAD_NUMERATOR,
  DICTIONARY_MINIMUM_CAPACITY,
  DICTIONARY_SHAPE_ID,
  DICTIONARY_SHAPE_SLOTS,
  DICTIONARY_TABLE_SHAPE_ID,
  DICTIONARY_TABLE_SHAPE_SLOTS,
  DICTIONARY_TABLE_SLOT,
  DICTIONARY_TALLY_SLOT,
  SHAPE_INDEXED,
  SmalltalkDictionaryTableError,
  bucketsFromIndexed,
  capacityOf,
  emptyBuckets,
  grownCapacity,
  indexedFromBuckets,
  needsGrowth,
  probeSequence,
  probeStart,
  readTableRecord,
  reinsert,
  sameCanonicalValue,
  sameStoredHash,
  tableRecordFields,
  tallyOf,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {objectRef, textValue} from '../value/index.js';
import {
  defineMethods,
  ensureBlock,
  ensureCodeArtifact,
  ensureNamedClass,
  ensureSmalltalkShape,
} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  DICTIONARY_SHAPE_ID,
  DICTIONARY_SHAPE_SLOTS,
  DICTIONARY_TABLE_SHAPE_ID,
  DICTIONARY_TABLE_SHAPE_SLOTS,
} from './smalltalk-dictionary-table.js';
import {
  SmalltalkKernelConflictError,
  canonicalJson,
  findSmalltalkKernel,
  readBehavior,
} from './smalltalk-kernel.js';
import {sameRef} from './smalltalk-lookup.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0048 decisions 1 and 9: the `Object >> =` / `Object >> hash` protocol and the first public
// `Dictionary` protocol, installed after kernel identity exists exactly as ADRs 0045-0047 install
// theirs. The compiler and dispatcher learn none of these selectors.
//
// Two installers rather than one, because they are separately useful: equality and hashing are
// ordinary Object protocol that a program may want without any collection at all, and a later
// MethodDictionary fast path needs the built-in helpers rather than the Dictionary class.
const DICTIONARY_CLASS_ID = 'smalltalk/class/Dictionary';
const DICTIONARY_METACLASS_ID = 'smalltalk/metaclass/Dictionary';

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS]: 'smalltalk/primitive/built-in-equals',
  [SMALLTALK_PRIMITIVE.BUILT_IN_HASH]: 'smalltalk/primitive/built-in-hash',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE]: 'smalltalk/primitive/dictionary-initialize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_SIZE]: 'smalltalk/primitive/dictionary-size',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY]: 'smalltalk/primitive/dictionary-includes-key',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT]: 'smalltalk/primitive/dictionary-at',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT]: 'smalltalk/primitive/dictionary-at-put',
  [SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO]: 'smalltalk/primitive/dictionary-keys-and-values-do',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS]: 'primitiveEquals',
  [SMALLTALK_PRIMITIVE.BUILT_IN_HASH]: 'primitiveHash',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE]: 'primitiveDictionaryInitialize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_SIZE]: 'primitiveDictionarySize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY]: 'primitiveDictionaryIncludesKey',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT]: 'primitiveDictionaryAt',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT]: 'primitiveDictionaryAtPut',
  [SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO]: 'primitiveDictionaryKeysAndValuesDo',
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

const captureFor = (primitive) => ({id: PRIMITIVE_BLOCK_ID[primitive], name: CAPTURE_NAME[primitive]});
const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

function primitiveSend(capture, args) {
  return {
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: {op: 'binding', id: capture.id},
    message: textValue('value:'.repeat(args.length)),
    arguments: args,
  };
}

// One method reaching one primitive, with the primitive Block bound as an ordinary captured ref in
// the method's own lexical environment.
function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = captureFor(primitive);
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{...capture}],
      body: primitiveSend(capture, args),
    },
    captures: [{...capture, value: objectRef(imageId, capture.id)}],
  };
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}


// `Object >> =` and `Object >> hash`. Every receiver in the image inherits them, which is what makes
// the default relation of decision 2 the language's default rather than a Dictionary-private helper.
async function installSmalltalkEqualityProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  for (const primitive of [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS, SMALLTALK_PRIMITIVE.BUILT_IN_HASH]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      capturedMethod({
        selector: '=',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS,
        parameters: ['anObject'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      // Workstream 3 (MessagePack pressure: the type-mapper dispatch sends `self class == Dictionary`,
      // and the slice also compares symbols, integers, booleans-across-the-bridge and ordinary refs
      // with `==`). `==` is *identity*, and it must NOT route through `=` — `=` is overridable
      // (Association overrides it for value equality), so `^self = anObject` would be wrong.
      //
      // It reuses the SAME built-in primitive as `=` rather than a new one, because ADR 0048 decision
      // 2's relation is already exactly what identity means here: an ObjectRef has genuine
      // (imageId, objectId) identity, while an immediate Value (Integer/Float/Text/Bytes/Boolean)
      // carries no object identity apart from its value, so its identity collapses to value by
      // construction. Two equal-but-distinct Associations are distinct refs -> `==` is false;
      // `1000 == 1000` is value-true because that is the only identity 1000 has. The primitive also
      // applies the ADR 0045 boolean-singleton normalization, which `aBoolean == true` across the
      // bridge requires — a hand-rolled identity primitive would risk dropping it.
      //
      // Like `=`, `==` is an ordinary (overridable) method; Smalltalk convention is not to override
      // it, and the language deliberately does not seal it.
      capturedMethod({
        selector: '==',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS,
        parameters: ['anObject'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'hash',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_HASH,
        args: [receiver()],
        imageId,
      }),
    ],
  });
  return Object.freeze({objectClass: kernel.objectClass});
}


async function installSmalltalkDictionaryProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // The table Shape carries the indexed declaration ADR 0047 introduced; the Dictionary Shape is an
  // ordinary one-slot layout, so a Dictionary's own identity never moves when its contents change.
  await ensureSmalltalkShape(images, imageId, {id: DICTIONARY_SHAPE_ID, slots: [...DICTIONARY_SHAPE_SLOTS]});
  await ensureSmalltalkShape(images, imageId, {
    id: DICTIONARY_TABLE_SHAPE_ID,
    slots: [...DICTIONARY_TABLE_SHAPE_SLOTS],
    indexed: SHAPE_INDEXED.VALUES,
  });

  for (const primitive of [
    SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE,
    SMALLTALK_PRIMITIVE.DICTIONARY_SIZE,
    SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY,
    SMALLTALK_PRIMITIVE.DICTIONARY_AT,
    SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT,
    SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO,
  ]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  const {classRef, metaclassRef} = await ensureNamedClass({
    images,
    imageId,
    name: 'Dictionary',
    superclassRef: kernel.objectClass,
    instanceShapeRef: objectRef(imageId, DICTIONARY_SHAPE_ID),
  });

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: [
      // Overrides `Object >> initialize`, which ADR 0046 installs as `^self`. `new` therefore stays
      // ordinary composition: basicNew leaves `table` nil, and this fills it in.
      capturedMethod({
        selector: 'initialize',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE,
        args: [receiver()],
        imageId,
      }),
      capturedMethod({
        selector: 'size',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_SIZE,
        args: [receiver()],
        imageId,
      }),
      capturedMethod({
        selector: 'includesKey:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY,
        parameters: ['aKey'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'at:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_AT,
        parameters: ['aKey'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'at:put:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT,
        parameters: ['aKey', 'aValue'],
        args: [receiver(), argument(0), argument(1)],
        imageId,
      }),
      // Workstream 3 (MessagePack pressure: `writeMap:` walks every pair). The one enumeration
      // primitive — the pairs live in the hidden table representation, so no composition of the
      // protocol above can reach them. Snapshot semantics, no hash/= re-sends and no order promise
      // are documented at the primitive itself.
      capturedMethod({
        selector: 'keysAndValuesDo:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO,
        parameters: ['aBlock'],
        args: [receiver(), argument(0)],
        imageId,
      }),
    ],
  });

  // Workstream 3 (MessagePack pressure). Ordinary-source lookup conveniences composed from the
  // primitives above — `MpSettings` and the type mappers read with `at:ifAbsent:`/`at:ifAbsentPut:`.
  // No new primitive and no table access: a miss is one `at:put:` through the existing protocol.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: [
      {
        selector: 'at:ifAbsent:',
        source: '[ :key :aBlock | (self includesKey: key) ifTrue: [ ^ self at: key ] ifFalse: [ ^ aBlock value ] ]',
      },
      {
        selector: 'at:ifAbsentPut:',
        source: '[ :key :aBlock | (self includesKey: key) ifTrue: [ ^ self at: key ] ifFalse: [ ^ self at: key put: (aBlock value) ] ]',
      },
    ],
  });

  // Class-side. Upstream `createDictionary:` sends `Dictionary new: size`, where `size` is only a
  // capacity *hint*. This Dictionary grows on demand from a fixed floor and has no capacity-taking
  // allocation primitive, so the honest minimal class method accepts and ignores the hint. It lives
  // on the metaclass — sending `new:` to the class object dispatches through the metaclass chain,
  // exactly like `Array new:`. `self new` resolves to the inherited zero-argument `Class>>new`
  // (basicNew + initialize), so it terminates rather than recursing into `new:`.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: metaclassRef,
    methods: [
      {selector: 'new:', source: '[ :size | ^ self new ]'},
    ],
  });

  return Object.freeze({classRef, dictionaryShape: objectRef(imageId, DICTIONARY_SHAPE_ID)});
}

export {
  DICTIONARY_CLASS_ID,
  PRIMITIVE_BLOCK_ID as SMALLTALK_DICTIONARY_PRIMITIVE_BLOCK_ID,
  installSmalltalkDictionaryProtocol,
  installSmalltalkEqualityProtocol,
};

import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {utf8Encode} from '../support/portable-bytes.js';
import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  float64ToNumber,
  integerValue,
  isObjectRef,
} from '../value/index.js';

// ADR 0048 decisions 2 and 3: the built-in `=` relation and the stable `hash` that must agree with
// it. Everything here is a pure function of canonical Values, which is what lets a later
// MethodDictionary fast path use the same helpers on Text selectors without executing any Smalltalk.
//
// This is deliberately *not* the `lagrange-code` `equals` op. That op is a frozen language-neutral
// structural comparison; this is one language's equality protocol, and the two must be able to
// disagree without either changing.
const SMALLTALK_EQUALITY_DOMAIN = 'smalltalk/equality/v1';

// The hash is a durable contract, not an implementation detail. Existing persistent tables were laid
// out with it, so replacing the algorithm is a migration decision rather than an optimization.
const SMALLTALK_HASH_BITS = 63n;
const SMALLTALK_HASH_MASK = (1n << SMALLTALK_HASH_BITS) - 1n;

class SmalltalkUnhashableValueError extends TypeError {
  constructor(kind) {
    super(
      `Symmetric Smalltalk has no equality or hash contract for a ${kind} Value; `
      + 'it is graph/history state rather than a Smalltalk receiver',
    );
    this.name = 'SmalltalkUnhashableValueError';
    this.kind = kind;
  }
}

function sameRefIdentity(left, right) {
  return left.imageId === right.imageId && left.objectId === right.objectId;
}

// An integral Float64 and an Integer denote the same number, so they share one normal form. The
// conversion goes through the Float's own value rather than through JavaScript's safe-integer range:
// 2^60 is exactly representable and must hash like the Integer 2^60, while 2^60+1 must not.
function integralFloat(value) {
  const number = float64ToNumber(value);
  if (!Number.isFinite(number) || !Number.isInteger(number)) return null;
  // -0 and +0 both become 0n, which is what makes them one key.
  return BigInt(number);
}

// The equality normal form, and therefore the hash pre-image. Two Values are built-in equal exactly
// when their normal forms are identical, which is what makes `a = b => a hash = b hash` true by
// construction rather than by parallel maintenance of two functions.
//
// NaN is the one deliberate exception: it has a stable normal form, but `=` says it is unequal to
// everything including itself. Dictionary does not repair a key whose own equality relation rejects
// it.
function equalityNormalForm(input) {
  const value = canonicalizeValue(input);
  switch (value.kind) {
    case VALUE_KIND.BOOLEAN:
      return ['boolean', value.value];
    case VALUE_KIND.TEXT:
      return ['text', value.value];
    case VALUE_KIND.BYTES:
      return ['bytes', value.base64];
    case VALUE_KIND.INTEGER:
      return ['number/integer', BigInt(value.value).toString(10)];
    case VALUE_KIND.FLOAT64: {
      const number = float64ToNumber(value);
      if (Number.isNaN(number)) return ['number/nan', value.bits];
      if (!Number.isFinite(number)) return ['number/infinity', number > 0 ? '+' : '-'];
      const integral = integralFloat(value);
      if (integral !== null) return ['number/integer', integral.toString(10)];
      // IEEE64 has exactly one bit pattern per finite non-integral value, so the bits are already a
      // canonical form; only NaN payloads and signed zero needed special handling, and both are
      // handled above.
      return ['number/float64', value.bits];
    }
    case VALUE_KIND.REF:
      return ['ref', value.imageId, value.objectId];
    default:
      throw new SmalltalkUnhashableValueError(value.kind);
  }
}

function builtInEquals(leftInput, rightInput) {
  const left = canonicalizeValue(leftInput);
  const right = canonicalizeValue(rightInput);

  // Identity, and nothing else: no record is read, so `_version`, Shape, behavior and slot contents
  // never participate. Two refs to the same object are equal however much the object has changed.
  if (isObjectRef(left) || isObjectRef(right)) {
    return isObjectRef(left) && isObjectRef(right) && sameRefIdentity(left, right);
  }
  // A pinned ref has no Smalltalk behavior, so it is not equal to anything rather than being an
  // error here; `hash` is where using one as a key actually fails.
  if (left.kind === VALUE_KIND.PINNED_REF || right.kind === VALUE_KIND.PINNED_REF) return false;

  const numericKinds = new Set([VALUE_KIND.INTEGER, VALUE_KIND.FLOAT64]);
  if (numericKinds.has(left.kind) && numericKinds.has(right.kind)) {
    // NaN must be unequal to itself, and no normal form can express that, so numbers are compared
    // directly rather than by comparing normal forms.
    if (left.kind === VALUE_KIND.FLOAT64 && Number.isNaN(float64ToNumber(left))) return false;
    if (right.kind === VALUE_KIND.FLOAT64 && Number.isNaN(float64ToNumber(right))) return false;
    const asBigInt = (value) => (value.kind === VALUE_KIND.INTEGER ? BigInt(value.value) : integralFloat(value));
    const leftInteger = asBigInt(left);
    const rightInteger = asBigInt(right);
    if (leftInteger !== null && rightInteger !== null) return leftInteger === rightInteger;
    // At least one is a non-integral or infinite Float; an Integer can equal neither.
    if (left.kind !== VALUE_KIND.FLOAT64 || right.kind !== VALUE_KIND.FLOAT64) return false;
    return float64ToNumber(left) === float64ToNumber(right);
  }

  if (left.kind !== right.kind) return false;
  switch (left.kind) {
    case VALUE_KIND.BOOLEAN:
      return left.value === right.value;
    case VALUE_KIND.TEXT:
      return left.value === right.value;
    case VALUE_KIND.BYTES:
      // Canonical base64, so string equality is byte equality.
      return left.base64 === right.base64;
    default:
      throw new SmalltalkUnhashableValueError(left.kind);
  }
}

// Deterministic across processes and restarts, because bucket placement in a durable table depends
// on it. A host-randomized or address-derived hash would relocate every key on restart.
function builtInHash(value) {
  const form = equalityNormalForm(value);
  const digest = getDefaultCryptoProvider().sha256(
    utf8Encode(JSON.stringify([SMALLTALK_EQUALITY_DOMAIN, ...form])),
  );
  return integerValue(new DataView(digest.buffer, digest.byteOffset, digest.byteLength).getBigUint64(0, false) & SMALLTALK_HASH_MASK);
}

// ADR 0045 makes the `true`/`false` singleton the effective receiver of a boolean send, so a
// built-in comparison would otherwise see a ref on one side and a boolean Value on the other and
// answer false. Normalizing the two well-known local singletons back to their boolean values keeps
// `true = true` from depending on which side of the bridge each operand arrived through.
function normalizeBooleanSingleton(value, kernel) {
  if (!kernel || !isObjectRef(value)) return value;
  if (sameRefIdentity(value, kernel.true)) return booleanValue(true);
  if (sameRefIdentity(value, kernel.false)) return booleanValue(false);
  return value;
}

export {
  sameRefIdentity,
  SMALLTALK_EQUALITY_DOMAIN,
  SMALLTALK_HASH_BITS,
  SmalltalkUnhashableValueError,
  builtInEquals,
  builtInHash,
  equalityNormalForm,
  normalizeBooleanSingleton,
};

import {canonicalRecordJson} from '../graph/ensure-records.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, isObjectRef, objectRef, textValue} from '../value/index.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {ensureNamedClass} from './smalltalk-class-builder.js';
import {KERNEL_CLASSES, ensureObject, ensureShape, findSmalltalkKernel, isLocalRef} from './smalltalk-kernel.js';

// ADR 0057: the durable namespace, and the first-class bindings it maps to.
//
// Three things are kept apart throughout, and most of this module exists to keep them apart:
//
//   name              a Text key in the mapping below
//   binding identity  a GlobalBinding object, stable across rename and rebinding
//   current value     what that binding holds right now
//
// The binding deliberately does not carry its own name — that is what lets renaming preserve
// identity — and it answers `value` and nothing else. A compiled method necessarily holds the
// binding ref in order to *read* the global, so an ordinary setter would make every reader a
// writer: reference is not authority (ADR 0057 decision 2). Rebinding happens through the trusted
// operations here.
const SMALLTALK_GLOBAL_NAMESPACE_V1 = 'smalltalk-global-namespace/v1';
const NAMESPACE_OBJECT_ID = 'smalltalk-global-namespace/v1';
// ADR 0002: Shapes are immutable, and a structural change creates a new shape identity. ADR 0061
// adds the parent slot, so the namespace Shape is v2 — never a mutation of v1. v1 is kept as a
// constant so a namespace record written before 0061 still validates (dual-read) and is migrated
// to v2 the first time its mapping is rewritten.
const NAMESPACE_SHAPE_ID_V1 = 'smalltalk/global-namespace-shape/v1';
const NAMESPACE_SHAPE_ID = 'smalltalk/global-namespace-shape/v2';
const NAMESPACE_PARENT_SLOT = 'namespace-parent';
const GLOBAL_BINDING_SHAPE_ID = 'smalltalk/global-binding-shape/v1';
const GLOBAL_BINDING_VALUE_SLOT = 'global-binding-value';
const GLOBAL_BINDING_CLASS_ID = 'smalltalk/class/GlobalBinding';

// Core installers choose stable, readable ids. The *generic* service never derives one — see
// `publish`, which requires the caller to supply it.
const globalBindingId = (name) => `smalltalk/global-binding/${name}`;

class SmalltalkNamespaceError extends TypeError {
  constructor(imageId, detail) {
    super(`Symmetric Smalltalk global namespace in ${imageId} is corrupt: ${detail}`);
    this.name = 'SmalltalkNamespaceError';
    this.imageId = imageId;
  }
}

class SmalltalkGlobalConflictError extends TypeError {
  constructor(name, detail) {
    super(`global ${name} ${detail}`);
    this.name = 'SmalltalkGlobalConflictError';
    this.globalName = name;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// The mapping is an indexed part rather than named Shape slots. A Shape's identity is its layout, so
// slots would turn every publication, rename and removal into a structural migration of the
// namespace object; an indexed part lets the mapping mutate while the Shape stays fixed.
//
// Canonical order — sorted by name — so two images that published the same globals in different
// orders hold the same record, and so a rewrite is a diff rather than a reshuffle.
function encodePairs(entries) {
  const indexed = [];
  for (const [name, binding] of [...entries].sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))) {
    indexed.push(textValue(name), binding);
  }
  return indexed;
}

function decodePairs(imageId, indexed) {
  if (!Array.isArray(indexed)) throw new SmalltalkNamespaceError(imageId, 'the mapping is not an indexed part');
  if (indexed.length % 2 !== 0) {
    throw new SmalltalkNamespaceError(imageId, `the mapping has an odd number of entries (${indexed.length})`);
  }
  const entries = new Map();
  let previousName = null;
  for (let index = 0; index < indexed.length; index += 2) {
    const name = indexed[index];
    const binding = indexed[index + 1];
    if (name?.kind !== VALUE_KIND.TEXT || name.value.length === 0) {
      throw new SmalltalkNamespaceError(imageId, `entry ${index / 2} has a non-Text name`);
    }
    if (!isLocalRef(binding, imageId)) {
      throw new SmalltalkNamespaceError(imageId, `entry ${name.value} must map to an unpinned local ref`);
    }
    if (entries.has(name.value)) throw new SmalltalkNamespaceError(imageId, `duplicate name ${name.value}`);
    // The representation is *promised* canonical, so an out-of-order mapping is corrupt rather than
    // something to quietly normalise on the next write. Accepting it would mean two images holding
    // the same globals could hold different records, which is the property canonical order exists
    // to rule out.
    if (previousName !== null && previousName >= name.value) {
      throw new SmalltalkNamespaceError(imageId, `entries are not in canonical order: ${previousName} before ${name.value}`);
    }
    previousName = name.value;
    entries.set(name.value, binding);
  }
  return entries;
}

async function assertIsBinding({images, imageId, name, binding}) {
  const record = await images.getObject(binding.imageId, binding.objectId);
  if (!record) throw new SmalltalkNamespaceError(imageId, `${name} maps to a missing object`);
  if (!isLocalRef(record.shape, imageId, GLOBAL_BINDING_SHAPE_ID)) {
    throw new SmalltalkNamespaceError(imageId, `${name} maps to an object that is not a GlobalBinding`);
  }
  if (!isLocalRef(record.behavior, imageId, GLOBAL_BINDING_CLASS_ID)) {
    throw new SmalltalkNamespaceError(imageId, `${name} maps to an object whose behavior is not GlobalBinding`);
  }
  return record;
}

// Installs the binding class, its read protocol, and an empty namespace. Needs only the kernel and
// the instance-variable protocol — deliberately not `Association`, allocation or equality, so a
// binding can exist before the classes it will name.
async function installSmalltalkGlobalNamespace({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const bindingShape = await ensureShape(images, imageId, {
    id: GLOBAL_BINDING_SHAPE_ID,
    slots: [{id: GLOBAL_BINDING_VALUE_SLOT, name: 'value'}],
  });
  const {classRef} = await ensureNamedClass({
    images, imageId, name: 'GlobalBinding', instanceShapeRef: objectRef(imageId, bindingShape.id),
  });
  // `value` and nothing else. There is no `value:`, by decision: see the header.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef, methods: [{selector: 'value', source: '[ value ]'}],
  });

  // ADR 0061: one slot, the optional parent edge. This is the v2 Shape — v1 had no slots. The slot
  // is always present in a v2 namespace object — `putObject` enforces exact slot-set match — so
  // "no parent" is a nil Value here, never an omitted slot. The root is the parentless namespace.
  const namespaceShape = await ensureShape(images, imageId, {
    id: NAMESPACE_SHAPE_ID,
    slots: [{id: NAMESPACE_PARENT_SLOT, name: 'parent'}],
    indexed: SHAPE_INDEXED.VALUES,
  });
  // Created empty, but *not* ensured against an empty mapping: the mapping has its own lifecycle
  // once anything is published, exactly as a binding's value does. Ensuring exactness here would
  // make re-running the installer conflict with every global published since — the same mistake as
  // resetting a rebound value on republication.
  const existingNamespace = await images.getObject(imageId, NAMESPACE_OBJECT_ID);
  if (!existingNamespace) {
    await images.putObject(imageId, {
      id: NAMESPACE_OBJECT_ID,
      shape: objectRef(imageId, namespaceShape.id),
      behavior: null,
      slots: {[NAMESPACE_PARENT_SLOT]: kernel.nil},
      indexed: [],
      metadata: {protocol: SMALLTALK_GLOBAL_NAMESPACE_V1},
    }, {expectedVersion: 0});
  } else {
    // Present already: it must still be a real namespace, so a squatter is refused rather than
    // adopted.
    await findSmalltalkGlobalNamespace({images, imageId});
  }

  // The kernel classes are published here because they already exist and this installer is the
  // first thing that can name anything. Everything else is published deliberately by whoever
  // installs it — publication is an operation, never a side effect of creating a class.
  for (const {name} of KERNEL_CLASSES) {
    await publishGlobal({
      images, imageId, name, bindingId: globalBindingId(name),
      value: objectRef(imageId, `smalltalk/class/${name}`),
    });
  }

  return Object.freeze({
    protocol: SMALLTALK_GLOBAL_NAMESPACE_V1,
    ref: objectRef(imageId, NAMESPACE_OBJECT_ID),
    bindingClass: classRef,
  });
}

// An explicit publication step for classes a protocol installer created. Deliberately a separate
// call rather than something `ensureNamedClass` does: a class may exist and remain unnameable, which
// is what keeps a future private or project namespace possible (ADR 0057 decision 1).
async function publishSmalltalkClassGlobals({images, imageId, names} = {}) {
  requiredText(imageId, 'image id');
  if (!Array.isArray(names) || names.length === 0) throw new TypeError('names must be a non-empty array');
  const published = {};
  for (const name of names) {
    const classId = `smalltalk/class/${name}`;
    if (!await images.getObject(imageId, classId)) {
      throw new TypeError(`image ${imageId} has no class ${name} to publish`);
    }
    published[name] = await publishGlobal({
      images, imageId, name, bindingId: globalBindingId(name), value: objectRef(imageId, classId),
    });
  }
  return Object.freeze(published);
}

// ADR 0061: the parent edge. A namespace object stores it in the `namespace-parent` slot: the
// kernel nil for the root, a ref to another namespace otherwise. Reading it is tolerant of the
// pre-0061 root, which was written with `slots: {}` before the Shape grew the slot — absence reads
// as no parent, and the first rewrite carries the slot forward. `nilRef` is the kernel nil, the
// only value besides a namespace ref the slot may hold.
function namespaceParentRef(imageId, record, nilRef) {
  const parent = record.slots?.[NAMESPACE_PARENT_SLOT];
  if (parent === undefined || parent === null) return null;
  if (!isLocalRef(parent, imageId)) {
    throw new SmalltalkNamespaceError(imageId, `the parent slot holds a non-local value, not a namespace ref or nil`);
  }
  // The kernel nil means "no parent"; any other local ref names the parent namespace.
  if (nilRef && parent.objectId === nilRef.objectId) return null;
  return parent;
}

// Generalized finder (ADR 0061). `findSmalltalkGlobalNamespace` is the root special case; this one
// reads any namespace by id. Absent stays distinct from corrupt, as with every other discoverable
// protocol here: an image without the object simply has no such namespace, while a damaged one is
// an explicit failure.
async function findNamespace({images, imageId, namespaceId = NAMESPACE_OBJECT_ID} = {}) {
  requiredText(imageId, 'namespace image id');
  requiredText(namespaceId, 'namespace id');
  const record = await images.getObject(imageId, namespaceId);
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_GLOBAL_NAMESPACE_V1) {
    throw new SmalltalkNamespaceError(imageId, `${namespaceId} does not declare ${SMALLTALK_GLOBAL_NAMESPACE_V1}`);
  }
  // Dual-read: a namespace written before ADR 0061 has the v1 (slotless) Shape; a nested one or a
  // migrated root has v2. Both are namespaces; only v2 can carry a parent edge.
  const isNamespaceShape = isLocalRef(record.shape, imageId, NAMESPACE_SHAPE_ID)
    || isLocalRef(record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  if (!isNamespaceShape) {
    throw new SmalltalkNamespaceError(imageId, `${namespaceId} does not have a namespace Shape`);
  }
  const entries = decodePairs(imageId, record.indexed);
  for (const [name, binding] of entries) {
    await assertIsBinding({images, imageId, name, binding});
  }
  // The kernel nil is the only non-namespace value the parent slot may hold; look it up to read the
  // edge. An image with a namespace always has a kernel (the installer needs one), so this is safe.
  const kernel = await findSmalltalkKernel({images, imageId});
  return Object.freeze({
    protocol: SMALLTALK_GLOBAL_NAMESPACE_V1,
    record,
    entries,
    parent: namespaceParentRef(imageId, record, kernel?.nil ?? null),
  });
}

// Absent stays distinct from corrupt, as with every other discoverable protocol here: an image
// without a namespace simply has no globals, while a damaged one is an explicit failure.
async function findSmalltalkGlobalNamespace({images, imageId} = {}) {
  return await findNamespace({images, imageId, namespaceId: NAMESPACE_OBJECT_ID});
}

async function requireNamespace({images, imageId, namespaceId = NAMESPACE_OBJECT_ID}) {
  const namespace = await findNamespace({images, imageId, namespaceId});
  if (!namespace) {
    throw new TypeError(`image ${imageId} has no global namespace ${namespaceId}; install it first`);
  }
  return namespace;
}

async function writeMapping({images, imageId, namespace, entries}) {
  // Writes this namespace's own id and preserves its slots — critically the parent edge. Writing
  // `slots: {}` would erase the parent on every publish/rename/remove in a nested namespace. A
  // record still on the v1 (slotless) Shape is MIGRATED to v2 here: it gains the parent slot (nil,
  // since a v1 record is the root and the root is parentless) and the v2 Shape ref, so ADR 0002's
  // immutability is honored — v1 is never mutated, the object just moves to the new Shape.
  const kernel = await findSmalltalkKernel({images, imageId});
  const onV1 = isLocalRef(namespace.record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  const slots = onV1
    ? {[NAMESPACE_PARENT_SLOT]: kernel.nil}
    : (namespace.record.slots && Object.hasOwn(namespace.record.slots, NAMESPACE_PARENT_SLOT)
      ? namespace.record.slots
      : {[NAMESPACE_PARENT_SLOT]: kernel.nil});
  await images.putObject(imageId, {
    id: namespace.record.id,
    shape: onV1 ? objectRef(imageId, NAMESPACE_SHAPE_ID) : namespace.record.shape,
    behavior: namespace.record.behavior,
    slots,
    indexed: encodePairs(entries),
    metadata: namespace.record.metadata,
  }, {expectedVersion: namespace.record._version});
}

// The trusted management seam. None of this is Smalltalk protocol.
//
// `publish` is retry-safe in the way an installer needs: a binding that already exists keeps the
// value it has. Re-running an installer must not undo a legitimate rebind — the current value has
// its own lifecycle now, and only `rebind` is allowed to change it.
async function publishGlobal({images, imageId, name, bindingId, value, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(name, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});

  // Preflight, before anything is created. Checking the mapping only after minting the candidate
  // would leave an orphan GlobalBinding behind on every rejected publication.
  const mapped = namespace.entries.get(name);
  if (mapped) {
    if (mapped.objectId !== bindingId) {
      throw new SmalltalkGlobalConflictError(name, `is already bound to ${mapped.objectId}, not ${bindingId}`);
    }
    await assertIsBinding({images, imageId, name, binding: mapped});
    return objectRef(imageId, bindingId);
  }

  const existingBinding = await images.getObject(imageId, bindingId);
  if (!existingBinding) {
    await images.putObject(imageId, {
      id: bindingId,
      shape: objectRef(imageId, GLOBAL_BINDING_SHAPE_ID),
      behavior: objectRef(imageId, GLOBAL_BINDING_CLASS_ID),
      slots: {[GLOBAL_BINDING_VALUE_SLOT]: value},
      metadata: {},
    }, {expectedVersion: 0});
  } else {
    // Already there — keep the value it has. Re-running an installer must not undo a rebind.
    await assertIsBinding({images, imageId, name, binding: objectRef(imageId, bindingId)});
  }

  const entries = new Map(namespace.entries);
  entries.set(name, objectRef(imageId, bindingId));
  await writeMapping({images, imageId, namespace, entries});
  return objectRef(imageId, bindingId);
}

async function resolveGlobal({images, imageId, name, namespaceId = NAMESPACE_OBJECT_ID}) {
  const namespace = await findNamespace({images, imageId, namespaceId});
  return namespace?.entries.get(name) ?? null;
}

// Changes the value on a stable identity. Already-compiled code observes it because it holds the
// binding, not the value.
async function rebindGlobal({images, imageId, bindingId, value}) {
  requiredText(bindingId, 'global binding id');
  const record = await images.getObject(imageId, bindingId);
  if (!record) throw new TypeError(`no global binding ${imageId}/${bindingId}`);
  await assertIsBinding({images, imageId, name: bindingId, binding: objectRef(imageId, bindingId)});
  const current = record.slots?.[GLOBAL_BINDING_VALUE_SLOT];
  if (canonicalRecordJson(current) === canonicalRecordJson(value)) return objectRef(imageId, bindingId);
  await images.putObject(imageId, {
    id: bindingId,
    shape: record.shape,
    behavior: record.behavior,
    slots: {[GLOBAL_BINDING_VALUE_SLOT]: value},
    metadata: record.metadata,
  }, {expectedVersion: record._version});
  return objectRef(imageId, bindingId);
}

// The same binding under a new name: identity survives, so compiled code is unaffected. The caller
// must name the identity it believes it is moving. That makes retry convergence part of the one API
// contract rather than an optional stronger mode: after a lost acknowledgement, the retry succeeds
// only when that same identity is already at the destination.
async function renameGlobal({images, imageId, from, to, bindingId, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(from, 'global name');
  requiredText(to, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});
  const binding = namespace.entries.get(from);
  const target = namespace.entries.get(to);

  if (!binding) {
    if (target && target.objectId === bindingId) return target;
    if (target) {
      throw new SmalltalkGlobalConflictError(to, `is bound to ${target.objectId}, not ${bindingId}`);
    }
    throw new SmalltalkGlobalConflictError(from, 'is not published');
  }
  if (binding.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(from, `is bound to ${binding.objectId}, not ${bindingId}`);
  }
  if (target && target.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(to, `is already bound to ${target.objectId}`);
  }
  // The desired mapping already exists to the expected binding: an ensure-style no-op.
  if (target && from === to) return binding;
  const entries = new Map(namespace.entries);
  entries.delete(from);
  entries.set(to, binding);
  await writeMapping({images, imageId, namespace, entries});
  return binding;
}

// Withdraws a *name*, but only for the identity the caller names. The binding object stays, so code
// already holding it keeps working. Identity is required for the same ABA reason as rename: if a
// removal commits, its acknowledgement is lost, and another actor republishes the same spelling to a
// different binding, the original retry must conflict rather than delete the new binding.
async function removeGlobal({images, imageId, name, bindingId, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(name, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});
  const mapped = namespace.entries.get(name);
  if (!mapped) return false;
  if (mapped.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(name, `is bound to ${mapped.objectId}, not ${bindingId}`);
  }
  const entries = new Map(namespace.entries);
  entries.delete(name);
  await writeMapping({images, imageId, namespace, entries});
  return true;
}

// ADR 0061: create a nested namespace. Same Shape and protocol as the root, at a caller-chosen id,
// with a parent edge (defaulting to the root). Exact-or-create: re-creating the same namespace with
// the same parent is a no-op; a conflict on id or parent is loud. The parent must exist and be a
// namespace. A fresh node cannot already be on a cycle, so the only self-cycle to refuse is
// parent === self.
async function createNamespace({images, imageId, namespaceId, parent = NAMESPACE_OBJECT_ID}) {
  requiredText(imageId, 'image id');
  requiredText(namespaceId, 'namespace id');
  requiredText(parent, 'parent namespace id');
  if (namespaceId === parent) {
    throw new SmalltalkNamespaceError(imageId, `a namespace cannot be its own parent: ${namespaceId}`);
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const existing = await images.getObject(imageId, namespaceId);
  if (existing) {
    // Converge on a retry: it must be the same namespace with the same parent.
    const found = await findNamespace({images, imageId, namespaceId});
    const foundParent = found.parent?.objectId ?? null;
    if (foundParent !== parent) {
      throw new SmalltalkGlobalConflictError(
        namespaceId,
        `already exists with parent ${foundParent ?? 'none'}, not ${parent}`,
      );
    }
    return objectRef(imageId, namespaceId);
  }
  // The parent must be a real namespace; this also validates the root exists for a default parent.
  await requireNamespace({images, imageId, namespaceId: parent});
  await images.putObject(imageId, {
    id: namespaceId,
    shape: objectRef(imageId, NAMESPACE_SHAPE_ID),
    behavior: null,
    slots: {[NAMESPACE_PARENT_SLOT]: objectRef(imageId, parent)},
    indexed: [],
    metadata: {protocol: SMALLTALK_GLOBAL_NAMESPACE_V1},
  }, {expectedVersion: 0});
  return objectRef(imageId, namespaceId);
}

// ADR 0061: (re)set a namespace's parent. Refuses to close a cycle: walking the proposed parent's
// chain to the root must not pass through this namespace. Identity-scoped by CAS on the record
// version, like the mapping writes.
async function setNamespaceParent({images, imageId, namespaceId, parent}) {
  requiredText(imageId, 'image id');
  requiredText(namespaceId, 'namespace id');
  requiredText(parent, 'parent namespace id');
  if (namespaceId === parent) {
    throw new SmalltalkNamespaceError(imageId, `a namespace cannot be its own parent: ${namespaceId}`);
  }
  const namespace = await requireNamespace({images, imageId, namespaceId});
  // The proposed parent must be a namespace, and reaching the root from it must not pass through
  // this namespace — that is the cycle.
  const visited = new Set();
  let cursor = parent;
  for (;;) {
    if (cursor === namespaceId) {
      throw new SmalltalkNamespaceError(
        imageId,
        `setting the parent of ${namespaceId} to ${parent} would close a cycle`,
      );
    }
    if (visited.has(cursor)) {
      throw new SmalltalkNamespaceError(imageId, `the proposed parent chain already has a cycle at ${cursor}`);
    }
    visited.add(cursor);
    const ancestor = await findNamespace({images, imageId, namespaceId: cursor});
    if (!ancestor) throw new SmalltalkNamespaceError(imageId, `the proposed parent ${cursor} is not a namespace`);
    if (!ancestor.parent) break;
    cursor = ancestor.parent.objectId;
  }
  // Gaining or changing a parent edge requires the v2 Shape (v1 has no parent slot): migrate a v1
  // record as part of the same write, honoring ADR 0002 immutability.
  const onV1 = isLocalRef(namespace.record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  const slots = {
    ...(onV1 ? {} : (namespace.record.slots ?? {})),
    [NAMESPACE_PARENT_SLOT]: objectRef(imageId, parent),
  };
  await images.putObject(imageId, {
    id: namespace.record.id,
    shape: onV1 ? objectRef(imageId, NAMESPACE_SHAPE_ID) : namespace.record.shape,
    behavior: namespace.record.behavior,
    slots,
    indexed: namespace.record.indexed,
    metadata: namespace.record.metadata,
  }, {expectedVersion: namespace.record._version});
  return objectRef(imageId, namespaceId);
}

// Name -> binding id, for the compiler. Transient: it is read per compilation and never stored.
//
// ADR 0061: resolution walks the parent chain from `namespaceId` outward to the root, and a nearer
// namespace's name shadows a farther one's (inner-wins). The walk is the compile-time lookup the
// ADR describes; the artifact the compiler produces still carries only binding ids, never a path.
// The chain is acyclic by construction (the management seam refuses a cycle-closing parent), but
// the walk defends itself anyway: a corrupted cycle is a namespace error, never a silent loop.
async function globalDeclarations({images, imageId, namespaceId = NAMESPACE_OBJECT_ID}) {
  const merged = new Map();
  const visited = new Set();
  let currentId = namespaceId;
  // Walk outward, recording which names are already claimed by a nearer namespace. First writer
  // wins, so a child name is never overwritten by its parent's.
  for (;;) {
    if (visited.has(currentId)) {
      throw new SmalltalkNamespaceError(imageId, `the namespace parent chain has a cycle at ${currentId}`);
    }
    visited.add(currentId);
    const namespace = await findNamespace({images, imageId, namespaceId: currentId});
    if (!namespace) {
      // A missing namespace is only legal as the caller's own starting point being absent — an
      // image with no globals at all. A parent that points nowhere is a dangling edge = corrupt.
      if (currentId === namespaceId && currentId === NAMESPACE_OBJECT_ID) return {};
      throw new SmalltalkNamespaceError(imageId, `the namespace ${currentId} named in a parent chain does not exist`);
    }
    for (const [name, binding] of namespace.entries) {
      if (!merged.has(name)) merged.set(name, binding.objectId);
    }
    if (!namespace.parent) return Object.fromEntries(merged);
    currentId = namespace.parent.objectId;
  }
}

