  NAMESPACE_SHAPE_ID,
  NAMESPACE_SHAPE_ID_V1,
  SMALLTALK_GLOBAL_NAMESPACE_V1,
  SmalltalkGlobalConflictError,
  SmalltalkNamespaceError,
