};

import {SHAPE_INDEXED} from '../object/model.js';
import {integerValue, objectRef, textValue} from '../value/index.js';
import {
  defineClass,
  defineMethods,
  ensureBlock,
  ensureCodeArtifact,
} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  SmalltalkKernelConflictError,
  canonicalJson,
  findSmalltalkKernel,
  readBehavior,
} from './smalltalk-kernel.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {sameRef} from './smalltalk-lookup.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0047 is intentionally post-bootstrap, like allocation and control flow. The kernel remains
// identity-only; Array is the first ordinary class whose instance Shape has an indexed part.
const ARRAY_INSTANCE_SHAPE_ID = 'smalltalk/array-instance-shape/v1';
const ARRAY_CLASS_ID = 'smalltalk/class/Array';
const ARRAY_METACLASS_ID = 'smalltalk/metaclass/Array';

const INDEXED_PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED]: 'smalltalk/primitive/basic-new-sized',
  [SMALLTALK_PRIMITIVE.INDEXED_SIZE]: 'smalltalk/primitive/indexed-size',
  [SMALLTALK_PRIMITIVE.INDEXED_AT]: 'smalltalk/primitive/indexed-at',
  [SMALLTALK_PRIMITIVE.INDEXED_AT_PUT]: 'smalltalk/primitive/indexed-at-put',
});

const CAPTURE = Object.freeze({
  [SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED],
    name: 'primitiveBasicNewSized',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_SIZE]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_SIZE],
    name: 'primitiveIndexedSize',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_AT]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_AT],
    name: 'primitiveIndexedAt',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_AT_PUT]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT],
    name: 'primitiveIndexedAtPut',
  }),
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

const parameter = (id, name = id) => ({id, name});
const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

const oneBasedToZeroBased = (expression) => ({
  op: 'integer-add',
  left: expression,
  right: {op: 'literal', value: integerValue(-1)},
});

function primitiveSend(capture, args) {
  return {
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: {op: 'binding', id: capture.id},
    message: textValue('value:'.repeat(args.length)),
    arguments: args,
  };
}

function methodProgram(parameters, capture, body) {
  return {
    parameters,
    captures: capture ? [{...capture}] : [],
    body,
  };
}

function capturedMethod(selector, parameters, capture, args) {
  return {
    selector,
    program: methodProgram(parameters, capture, primitiveSend(capture, args)),
    captures: [{...capture, value: null}],
  };
}

async function ensureArrayShape(images, imageId) {
  const desired = {id: ARRAY_INSTANCE_SHAPE_ID, slots: [], indexed: SHAPE_INDEXED.VALUES};
  const existing = await images.getShape(imageId, desired.id);
  if (!existing) return await images.putShape(imageId, desired);
  const layout = (shape) => canonicalJson({
    slots: shape.slots,
    indexed: Object.hasOwn(shape, 'indexed') ? shape.indexed : SHAPE_INDEXED.NONE,
  });
  if (layout(existing) !== layout(desired)) {
    throw new SmalltalkKernelConflictError('shape', imageId, desired.id);
  }
  return existing;
}

function requireSameRef(actual, expected, imageId) {
  if (!sameRef(actual, expected)) throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID);
}

async function ensureArrayClass({images, imageId, kernel, shapeRef}) {
  const classRef = objectRef(imageId, ARRAY_CLASS_ID);
  const metaclassRef = objectRef(imageId, ARRAY_METACLASS_ID);
  const existing = await images.getObject(imageId, ARRAY_CLASS_ID);
  if (!existing) {
    return await defineClass({
      images,
      imageId,
      name: 'Array',
      superclassRef: kernel.objectClass,
      instanceShapeRef: shapeRef,
    });
  }

  // Once the class record exists, defineClass completed all four class-graph writes. Calling it
  // again after methods have begun to publish would wrongly demand that the method dictionaries be
  // empty again. Rediscovery therefore validates only the immutable class definition and leaves
  // method dictionaries to defineMethods, which has its own retry-safe exactness contract.
  let behavior;
  let metaclass;
  try {
    behavior = await readBehavior(images, classRef);
    metaclass = await readBehavior(images, metaclassRef);
  } catch (error) {
    throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID, {cause: error});
  }
  if (behavior.name.value !== 'Array' || metaclass.name.value !== 'Array class') {
    throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID);
  }
  requireSameRef(behavior.record.behavior, metaclassRef, imageId);
  requireSameRef(behavior.superclass, kernel.objectClass, imageId);
  requireSameRef(behavior.instanceShape, shapeRef, imageId);

  const objectBehavior = await readBehavior(images, kernel.objectClass);
  requireSameRef(metaclass.record.behavior, kernel.metaclassClass, imageId);
  requireSameRef(metaclass.superclass, objectBehavior.record.behavior, imageId);
  requireSameRef(metaclass.instanceShape, kernel.nil, imageId);
  return Object.freeze({classRef, metaclassRef});
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = INDEXED_PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

function bindCapture(method, imageId) {
  if (!method.captures) return method;
  return {
    ...method,
    captures: method.captures.map((entry) => ({
      ...entry,
      value: objectRef(imageId, entry.id),
    })),
  };
}

function protocolFor({kernel, arrayClass, imageId}) {
  const basicNewSized = CAPTURE[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED];
  const indexedSize = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_SIZE];
  const indexedAt = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_AT];
  const indexedAtPut = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT];
  const index = oneBasedToZeroBased(argument(0));

  return [
    {
      classRef: kernel.classClass,
      methods: [bindCapture(capturedMethod(
        'basicNew:',
        [parameter('size')],
        basicNewSized,
        [receiver(), argument(0)],
      ), imageId)],
    },
    {
      classRef: arrayClass.metaclassRef,
      methods: [{
        selector: 'new:',
        program: methodProgram(
          [parameter('size')],
          null,
          {
            op: 'send',
            languageId: SYMMETRIC_SMALLTALK_ID,
            receiver: receiver(),
            message: textValue('basicNew:'),
            arguments: [argument(0)],
          },
        ),
      }],
    },
    {
      classRef: arrayClass.classRef,
      methods: [
        bindCapture(capturedMethod('size', [], indexedSize, [receiver()]), imageId),
        bindCapture(capturedMethod('at:', [parameter('index')], indexedAt, [receiver(), index]), imageId),
        bindCapture(capturedMethod(
          'at:put:',
          [parameter('index'), parameter('value')],
          indexedAtPut,
          [receiver(), index, argument(1)],
        ), imageId),
      ],
    },
  ];
}

async function installSmalltalkIndexedProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Deterministic publication order makes a partial run recoverable by replaying the installer:
  // layout -> class graph -> primitive Blocks -> ordinary methods.
  const shape = await ensureArrayShape(images, imageId);
  const arrayClass = await ensureArrayClass({
    images,
    imageId,
    kernel,
    shapeRef: objectRef(imageId, shape.id),
  });

  const primitives = {};
  for (const primitive of [
    SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED,
    SMALLTALK_PRIMITIVE.INDEXED_SIZE,
    SMALLTALK_PRIMITIVE.INDEXED_AT,
    SMALLTALK_PRIMITIVE.INDEXED_AT_PUT,
  ]) {
    primitives[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }

  for (const {classRef, methods} of protocolFor({kernel, arrayClass, imageId})) {
    await defineMethods({images, compilation, imageId, classRef, methods, lane});
  }

  return Object.freeze({
    arrayClass: arrayClass.classRef,
    arrayMetaclass: arrayClass.metaclassRef,
    arrayInstanceShape: objectRef(imageId, shape.id),
    basicNewSizedPrimitive: primitives[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED],
    indexedSizePrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_SIZE],
    indexedAtPrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_AT],
    indexedAtPutPrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT],
  });
}

// `do:` for Array, installed as a separate post-Block/Integer step because it
// composes the indexed primitives with the Block enumeration loop (which is not
// yet installed when `installSmalltalkIndexedProtocol` runs). A general
// collection protocol the upstream MessagePack encoder needs (`writeArray:`
// sends `array do:`); Array is a kernel class outside the `Collection`
// hierarchy, so it does not inherit the library's `Collection do:`.
const ARRAY_ENUMERATION_METHODS = Object.freeze([
  {
    selector: 'do:',
    source: `[ :aBlock | | index |
      index := 1.
      [ index <= self size ] whileTrue: [
        aBlock value: (self at: index).
        index := index + 1 ] ]`,
  },
]);

async function installSmalltalkArrayEnumerationProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  await defineMethodsFromSource({
    images, compilation, imageId, lane,
    classRef: objectRef(imageId, ARRAY_CLASS_ID),
    methods: ARRAY_ENUMERATION_METHODS,
  });
  return Object.freeze({protocol: 'smalltalk-array-enumeration/v1'});
}

export {
  ARRAY_INSTANCE_SHAPE_ID,
  CAPTURE as SMALLTALK_INDEXED_CAPTURE,
  INDEXED_PRIMITIVE_BLOCK_ID as SMALLTALK_INDEXED_PRIMITIVE_BLOCK_ID,
  installSmalltalkArrayEnumerationProtocol,
  installSmalltalkIndexedProtocol,
};

import {objectRef, textValue} from '../value/index.js';
import {
  defineMethods,
  ensureBlock,
  ensureCodeArtifact,
} from './smalltalk-class-builder.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {globalDeclarations} from './smalltalk-globals.js';
import {classVariableDeclarations} from './smalltalk-class-variables.js';
import {visibleInstanceShape} from './smalltalk-lookup.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {
  INSTANCE_SLOT_READ_CAPTURE,
  ARRAY_BINDING_ID,
  NIL_BINDING_ID,
  NIL_CAPTURE,
  NON_LOCAL_RETURN_CAPTURE,
  INSTANCE_SLOT_WRITE_CAPTURE,
  SYMBOL_BINDING_ID,
  compileSymmetricSmalltalkSemanticBlock,
} from './symmetric-smalltalk-semantic.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0050: the class-scoped compilation entry point, and the primitive Blocks it binds against.
//
// This is a *sibling* of `compileSymmetricSmalltalkSemanticBlock`, not a stage above it. That
// compiler already resolves names and already rejects an unbound root name at that moment, so there
// is no later point where an unresolved name survives for someone else to bind. The class arrives as
// an argument, exactly as `captures` already does, and the Block compiler is untouched.
const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ]: 'smalltalk/primitive/instance-slot-read',
  [SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE]: 'smalltalk/primitive/instance-slot-write',
  // ADR 0055. `^` lowers to a send to this, bound through the same seam and reserved the same way.
  [SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN]: 'smalltalk/primitive/non-local-return',
});

// Owned by the class-scoped binder, which injects them for instance-variable access and for `^`.
const RESERVED_CAPTURE_NAMES = new Set([
  INSTANCE_SLOT_READ_CAPTURE, INSTANCE_SLOT_WRITE_CAPTURE, NON_LOCAL_RETURN_CAPTURE, NIL_CAPTURE,
]);
// The nil binding id joins the primitive ids: reserving a name without its id would let a caller
// bind the same id under a different name and shadow the intrinsic from outside the compiler.
const RESERVED_CAPTURE_IDS = new Set([...Object.values(PRIMITIVE_BLOCK_ID), NIL_BINDING_ID]);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkInstanceVariableProtocol({images, imageId} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const installed = {};
  for (const primitive of Object.keys(PRIMITIVE_BLOCK_ID)) {
    installed[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }
  return Object.freeze({
    readPrimitive: installed[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ],
    writePrimitive: installed[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE],
    nonLocalReturnPrimitive: installed[SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN],
  });
}

// name -> stable slot id, for the names a method of this class may see. The *name* lives here and in
// the Shape; the compiled method carries only the id (ADR 0050 decision 2), which is why a rename
// that preserves the id leaves existing methods working.
async function instanceVariableBindings({images, imageId, classRef} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  // The same strict walk the runtime permission check uses, so the binder cannot offer a name
  // the primitive would then refuse, and neither can report corruption as an unbound name.
  const shape = await visibleInstanceShape({images, behaviorRef: classRef, nilRef: kernel.nil});
  if (!shape) return Object.freeze({});
  const bindings = {};
  for (const {id, name} of shape.slots) {
    if (Object.hasOwn(bindings, name)) {
      throw new TypeError(`instance shape ${shape.id} declares duplicate slot name: ${name}`);
    }
    bindings[name] = id;
  }
  return Object.freeze(bindings);
}

// A method may capture named values, exactly as a Block may. This is how a method names anything
// that is not a parameter, temporary or instance variable — a class, for instance, since source has
// no global namespace: `Array` is a captured ref, not a resolvable global.
//
// Compilation and installation are kept apart. What the *compiler* needs is a declaration — a name
// bound to a stable capture id — and it answers the program's capture list. Every declaration is in
// that list, referenced or not. Binding values is installation's job, because a value is per image
// while a declaration is not.
//
// Two forms are accepted and both mean the same thing to the compiler:
//
//   {name: captureId}                  a declaration map
//   [{name, id, value?}]               declarations, optionally carrying installation values
//
// Duplicates are refused in either form rather than resolved by position. A repeated name would make
// the meaning of that name in source depend on declaration order, and a repeated id would collapse
// two declarations into one binding — the same first-wins defect this substrate rejects everywhere.
function normalizeCaptureDeclarations(captures) {
  const entries = Array.isArray(captures)
    ? captures.map((entry) => {
      if (!entry || typeof entry !== 'object') throw new TypeError('a capture declaration must be an object');
      return {name: entry.name, id: entry.id, value: entry.value};
    })
    : Object.entries(captures ?? {}).map(([name, id]) => ({name, id, value: undefined}));

  const names = new Set();
  const ids = new Set();
  for (const entry of entries) {
    requiredText(entry.name, 'capture name');
    requiredText(entry.id, 'capture id');
    // The binder adds its own captures for the slot primitives, and they are spread *after* the
    // caller's — so a colliding declaration would be silently replaced, value and all, which is
    // exactly what the uniform capture contract is supposed to prevent. Refuse instead.
    if (RESERVED_CAPTURE_NAMES.has(entry.name)) {
      throw new TypeError(`capture name ${entry.name} is reserved for instance-variable access`);
    }
    if (RESERVED_CAPTURE_IDS.has(entry.id)) {
      throw new TypeError(`capture id ${entry.id} is reserved for instance-variable access`);
    }
    if (names.has(entry.name)) throw new TypeError(`method declares capture name ${entry.name} twice`);
    if (ids.has(entry.id)) throw new TypeError(`method declares capture id ${entry.id} twice`);
    names.add(entry.name);
    ids.add(entry.id);
  }
  return entries;
}

// The class-scoped entry point: parse -> compile *with the defining class* -> semantic program.
async function compileSymmetricSmalltalkMethod({
  images,
  imageId,
  classRef,
  selector,
  source,
  captures = {},
  // ADR 0057: the caller's namespace snapshot, where it has one. Reading it again here would let a
  // rename or removal between the two reads change what a batch of methods meant.
  globals: suppliedGlobals = null,
  // ADR 0061: which namespace this method compiles in, when no snapshot is supplied. Defaults to
  // the root, preserving ADR 0057 for existing callers.
  namespaceId,
} = {}) {
  requiredText(selector, 'selector');
  const declared = normalizeCaptureDeclarations(captures);
  const instanceVariables = await instanceVariableBindings({images, imageId, classRef});
  // The primitives arrive as ordinary root captures, so an instance-variable reference lowers to an
  // ordinary send and nothing downstream of the compiler learns a new concept. They are added only
  // when the source actually names an instance variable, so a method that uses none carries none.
  // One namespace snapshot per batch, supplied by the caller where there is one: reading it twice
  // would let a rename or removal between the reads change what compilation meant.
  const globals = suppliedGlobals ?? await globalDeclarations({images, imageId, namespaceId});
  const compiled = compileSymmetricSmalltalkSemanticBlock(source, {
    globals,
    captures: {
      ...Object.fromEntries(declared.map(({name, id}) => [name, id])),
      [INSTANCE_SLOT_READ_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ],
      [INSTANCE_SLOT_WRITE_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE],
    },
    // ADR 0055: made *available* rather than declared. A declaration becomes a program capture
    // whether or not the source references it, so declaring this eagerly would give every method a
    // dependency it may never use. The lowering requests it on first `^`, which needs no second
    // inspection of the source.
    intrinsics: {
      [NON_LOCAL_RETURN_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN],
      // `nil` is deliberately absent: the semantic compiler owns that intrinsic and offers it to
      // every compilation, so declaring it here would be a second definition to keep in step.
    },
    instanceVariables,
    // This entry point is the class-scoped one, so its compilations have a method to return from.
    methodHome: true,
    classVariables: await classVariableDeclarations({images, imageId, classRef}),
  });

  // Every declaration becomes a program capture, referenced or not — that is the block compiler's
  // existing behaviour for root captures and this path does not change it. What is returned is the
  // program's own capture list, in its own order, with no values: this is compilation, and a value
  // is an installation concern.
  return Object.freeze({
    selector,
    program: compiled.program,
    representation: compiled.representation,
    instanceVariables,
    captures: compiled.program.captures.map(({id, name}) => Object.freeze({id, name})),
    // Transient provenance: which of those captures are globals this compilation resolved.
    globalBindingIdsUsed: compiled.globalBindingIdsUsed,
    // Transient provenance: which of those captures are class variables this compilation resolved.
    classVariableBindingIdsUsed: compiled.classVariableBindingIdsUsed,
  });
}

// Compile methods from source against their defining class and install them. This is where a
// capture declaration acquires its value: the slot primitives resolve to their well-known Blocks in
// this image, and anything else must have been supplied by the caller.
async function defineMethodsFromSource({images, compilation, imageId, classRef, methods, lane = 'neutral', namespaceId} = {}) {
  if (!Array.isArray(methods) || methods.length === 0) throw new TypeError('methods must be a non-empty array');
  const primitiveIds = new Set(Object.values(PRIMITIVE_BLOCK_ID));
  // Resolved once: `nil` means this image's kernel nil, and a method that never writes it carries
  // no binding to resolve.
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const kernelNil = kernel.nil;
  // One snapshot for the whole batch, used for compilation and nothing else. Global captures are
  // identified by *provenance* below, never by testing an id against this map. ADR 0061: the
  // namespace the batch compiles in, defaulting to the root.
  const globals = await globalDeclarations({images, imageId, namespaceId});
  const compiled = [];
  for (const {selector, source, captures} of methods) {
    const declared = normalizeCaptureDeclarations(captures ?? {});
    const supplied = new Map(declared.map(({id, value}) => [id, value]));
    const method = await compileSymmetricSmalltalkMethod({
      images, imageId, classRef, selector, source, captures, globals,
    });
    // Exactly what this method resolved as a global or class variable — so an explicit capture
    // keeps its caller's value even when its id happens to equal a published binding id.
    const resolvedGlobals = new Set(method.globalBindingIdsUsed ?? []);
    const resolvedClassVars = new Set(method.classVariableBindingIdsUsed ?? []);
    const bound = method.captures.map(({id, name}) => {
      if (primitiveIds.has(id)) return {id, name, value: objectRef(imageId, id)};
      // ADR 0056: the nil intrinsic resolves to this image's kernel nil, exactly as the slot
      // primitives resolve to this image's Blocks.
      if (id === NIL_BINDING_ID) return {id, name, value: kernelNil};
      // The symbol intrinsic binds to the image-local interner primitive Block.
      if (id === SYMBOL_BINDING_ID) return {id, name, value: objectRef(imageId, 'smalltalk/primitive/symbol-intern')};
      // The array intrinsic binds to this image's Array class (for the `#()` empty literal).
      if (id === ARRAY_BINDING_ID) return {id, name, value: objectRef(imageId, 'smalltalk/class/Array')};
      // ADR 0057: a resolved global binds to that binding object in *this* image. The artifact
      // carried only the id; the ref appears here, at installation.
      if (resolvedGlobals.has(id)) return {id, name, value: objectRef(imageId, id)};
      // A resolved class variable binds to the ClassVariableBinding object in this image.
      if (resolvedClassVars.has(id)) return {id, name, value: objectRef(imageId, id)};
      const value = supplied.get(id);
      if (value === undefined) {
        throw new TypeError(
          `method ${selector} declares capture ${name} without a value; every declared capture `
          + 'becomes a binding in the installed method, so installation needs a value for each',
        );
      }
      return {id, name, value};
    });
    compiled.push({selector: method.selector, program: method.program, captures: bound});
  }
  return await defineMethods({images, compilation, imageId, classRef, lane, methods: compiled});
}

export {
  PRIMITIVE_BLOCK_ID as SMALLTALK_INSTANCE_SLOT_PRIMITIVE_BLOCK_ID,
  compileSymmetricSmalltalkMethod,
  defineMethodsFromSource,
  installSmalltalkInstanceVariableProtocol,
  instanceVariableBindings,
};

import {booleanValue, objectRef, textValue} from '../value/index.js';
import {defineMethods, ensureBlock, ensureCodeArtifact} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0053: Integer ordering and arithmetic, installed as ordinary methods over language-owned
// primitives. `lagrange-code/v0` stays frozen — no comparison op is added — and the compiler learns
// no selector: `<` is found by the same Behavior walk as `+` and `ifTrue:`.
//
// One comparison primitive, three derived methods. Four primitives would be four chances for the set
// to disagree, and a `>=` that parts company with `<` at exactly one boundary is the classic form of
// that bug.
const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN]: 'smalltalk/primitive/integer-less-than',
  [SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT]: 'smalltalk/primitive/integer-subtract',
  [SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY]: 'smalltalk/primitive/integer-multiply',
  [SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE]: 'smalltalk/primitive/integer-floor-divide',
  [SMALLTALK_PRIMITIVE.INTEGER_MODULO]: 'smalltalk/primitive/integer-modulo',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_AND]: 'smalltalk/primitive/integer-bit-and',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_OR]: 'smalltalk/primitive/integer-bit-or',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR]: 'smalltalk/primitive/integer-bit-xor',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT]: 'smalltalk/primitive/integer-bit-shift',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN]: 'primitiveIntegerLessThan',
  [SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT]: 'primitiveIntegerSubtract',
  [SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY]: 'primitiveIntegerMultiply',
  [SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE]: 'primitiveIntegerFloorDivide',
  [SMALLTALK_PRIMITIVE.INTEGER_MODULO]: 'primitiveIntegerModulo',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_AND]: 'primitiveIntegerBitAnd',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_OR]: 'primitiveIntegerBitOr',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR]: 'primitiveIntegerBitXor',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT]: 'primitiveIntegerBitShift',
});

const captureFor = (primitive) => Object.freeze({
  id: PRIMITIVE_BLOCK_ID[primitive],
  name: CAPTURE_NAME[primitive],
});

const RECEIVER = Object.freeze({op: 'receiver'});
const ARGUMENT = Object.freeze({op: 'argument', index: 0});

// `aPrimitive value: x value: y` — an ordinary Block send, which ADR 0044 decision 11 answers
// without a class. A method never *is* a primitive; it captures one and sends to it.
const applyPrimitive = (primitive, left, right) => ({
  op: 'send',
  languageId: SYMMETRIC_SMALLTALK_ID,
  receiver: {op: 'binding', id: PRIMITIVE_BLOCK_ID[primitive]},
  message: textValue('value:value:'),
  arguments: [left, right],
});

// ADR 0053 decision 2. `not` does not exist — ADR 0045 deferred it — and inventing it to spell two
// methods would be scope creep, so the negation lives inside these two installed programs using the
// neutral `if`. That is a lower-level semantic producer using the IR directly, which ADR 0045
// permits; what it forbids is Smalltalk *source* conditionals becoming compiler special cases.
const negated = (condition) => ({
  op: 'if',
  condition,
  then: {op: 'literal', value: booleanValue(false)},
  else: {op: 'literal', value: booleanValue(true)},
});

const LESS_THAN = SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN;

// The installed protocol, as it reads in Smalltalk:
//
//   Integer >> <   primitiveIntegerLessThan value: self value: other
//   Integer >> >   primitiveIntegerLessThan value: other value: self
//   Integer >> <=  (primitiveIntegerLessThan value: other value: self) not
//   Integer >> >=  (primitiveIntegerLessThan value: self  value: other) not
const INTEGER_METHODS = [
  {selector: '<', primitive: LESS_THAN, body: applyPrimitive(LESS_THAN, RECEIVER, ARGUMENT)},
  {selector: '>', primitive: LESS_THAN, body: applyPrimitive(LESS_THAN, ARGUMENT, RECEIVER)},
  {selector: '<=', primitive: LESS_THAN, body: negated(applyPrimitive(LESS_THAN, ARGUMENT, RECEIVER))},
  {selector: '>=', primitive: LESS_THAN, body: negated(applyPrimitive(LESS_THAN, RECEIVER, ARGUMENT))},
  {
    selector: '-',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT, RECEIVER, ARGUMENT),
  },
  {
    selector: '*',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY, RECEIVER, ARGUMENT),
  },
  {
    selector: '//',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE, RECEIVER, ARGUMENT),
  },
  {
    selector: '\\\\',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_MODULO,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_MODULO, RECEIVER, ARGUMENT),
  },
  // Workstream 3. Bitwise protocol, one method per primitive. These are the general Integer
  // operations upstream MessagePack reaches for (`bitOr:` in size headers, `bitAnd:`/`bitShift:` in
  // dialect byte extraction); nothing about them names MessagePack.
  {
    selector: 'bitAnd:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_AND,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_AND, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitOr:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_OR,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_OR, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitXor:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitShift:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT, RECEIVER, ARGUMENT),
  },
];

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Ensure-exact-or-create at both deterministic ids, like every other derived record here.
async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkIntegerProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Primitives first: a method's environment may not point at a Block that does not yet exist.
  const primitives = {};
  for (const primitive of Object.keys(PRIMITIVE_BLOCK_ID)) {
    primitives[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.integerClass,
    methods: INTEGER_METHODS.map(({selector, primitive, body}) => {
      const capture = captureFor(primitive);
      return {
        selector,
        program: {parameters: [{id: `${selector}:arg`, name: 'other'}], captures: [{...capture}], body},
        captures: [{...capture, value: primitives[primitive]}],
      };
    }),
  });

  // Workstream 3 (MessagePack pressure). Ordinary-source Integer protocol over the comparisons and
  // arithmetic above — no new primitive, no compiler knowledge. Reached for by real upstream source:
  // `writeInteger:` guards with `anInteger between: 0 and: 127`; `readArraySized:` loops `1 to: size
  // do:`; `readMapSized:` loops `timesRepeat:`; `readInt8` negates. `negated`, `between:and:` and the
  // loops are written against `<`, `<=`, `-`, `+`, `and:` and `whileTrue:`, all of which resolve at
  // dispatch like any other send.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.integerClass,
    methods: [
      {selector: 'negated', source: '[ ^ 0 - self ]'},
      {selector: 'between:and:', source: '[ :min :max | ^ (min <= self) and: [ self <= max ] ]'},
      {
        selector: 'to:do:',
        source: `[ :stop :aBlock | | i |
          i := self.
          [ i <= stop ] whileTrue: [ aBlock value: i. i := i + 1 ].
          ^ self ]`,
      },
      {selector: 'timesRepeat:', source: '[ :aBlock | 1 to: self do: [ :i | aBlock value ]. ^ self ]'},
      // Binary selector convenience for bitShift:. `a >> b` shifts right by b (negative bitShift);
      // `a << b` shifts left by b (positive bitShift). Written against the installed primitive,
      // not a new one.
      {selector: '>>', source: '[ :shift | ^ self bitShift: 0 - shift ]'},
      {selector: '<<', source: '[ :shift | ^ self bitShift: shift ]'},
    ],
  });

  return Object.freeze({integerClass: kernel.integerClass, ...primitives});
}

export {
  INTEGER_METHODS,
  PRIMITIVE_BLOCK_ID as SMALLTALK_INTEGER_PRIMITIVE_BLOCK_ID,
  installSmalltalkIntegerProtocol,
};

import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, isObjectRef, objectRef, textValue} from '../value/index.js';
import {
  METHOD_DICTIONARY_SHAPE_ID,
  buildMethodBuckets,
  isMethodDictionary,
  methodDictionaryRecordFields,
} from './smalltalk-method-dictionary.js';
import {ensureMethodDictionaryShape} from './smalltalk-method-dictionary-migration.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// The Symmetric Smalltalk kernel: the durable object graph ADR 0044 dispatches against.
//
// This module installs and rediscovers it. It deliberately performs no dispatch: execution starts
// depending on the kernel in a later change, once dispatch-image context exists. What lands here is
// identity — the shapes, the singleton and class graph, and a way to find all of it again from
// nothing but an image id.
//
// Discoverability is the point. Returning refs from an installer is not enough: the refs die with
// the process while the image survives, so the kernel is reachable at one well-known object id and
// everything else is found through it. The dispatcher will know this protocol, never an `Integer`
// object id.
const SMALLTALK_KERNEL_PROTOCOL_V1 = 'smalltalk-kernel/v1';
const SMALLTALK_KERNEL_OBJECT_ID = 'smalltalk-kernel/v1';

// Fixed shapes, per ADR 0044 decision 1. A Behavior's shape never changes, which is what keeps
// adding a method from restructuring the class.
const BEHAVIOR_SHAPE_ID = 'smalltalk/behavior-shape/v1';
const KERNEL_SHAPE_ID = 'smalltalk/kernel-shape/v1';
const EMPTY_SHAPE_ID = 'smalltalk/empty-shape/v1';

const BEHAVIOR_SLOTS = Object.freeze([
  {id: 'behavior-name', name: 'name'},
  {id: 'behavior-superclass', name: 'superclass'},
  {id: 'behavior-methods', name: 'methods'},
  {id: 'behavior-instance-shape', name: 'instanceShape'},
]);

// The kernel carries the immediate-value classes decision 5 dispatches through, the singletons of
// decision 7, and the three classes the metaclass knot is tied from.
const KERNEL_SLOTS = Object.freeze([
  {id: 'kernel-nil', name: 'nil'},
  {id: 'kernel-true', name: 'true'},
  {id: 'kernel-false', name: 'false'},
  {id: 'kernel-object-class', name: 'objectClass'},
  {id: 'kernel-class-class', name: 'classClass'},
  {id: 'kernel-metaclass-class', name: 'metaclassClass'},
  {id: 'kernel-boolean-class', name: 'booleanClass'},
  {id: 'kernel-integer-class', name: 'integerClass'},
  {id: 'kernel-float-class', name: 'floatClass'},
  {id: 'kernel-text-class', name: 'textClass'},
  {id: 'kernel-byte-array-class', name: 'byteArrayClass'},
]);

const KERNEL_SLOT_BY_NAME = Object.freeze(Object.fromEntries(
  KERNEL_SLOTS.map(({id, name}) => [name, id]),
));

// ADR 0044 decision 2. Generic Shapes reject a duplicate slot *id* and say nothing about names, so
// two slots may both be named `+` and a find-based lookup would resolve by position. That is a
// MethodDictionary invariant, checked here, and deliberately not imposed on generic Shape — which
// has other legitimate users whose slot names are not selectors.
function methodDictionarySlots(selectors) {
  if (!Array.isArray(selectors)) throw new TypeError('method dictionary selectors must be an array');
  const seen = new Set();
  return selectors.map((selector, index) => {
    if (typeof selector !== 'string' || selector.length === 0) {
      throw new TypeError(`method dictionary selector ${index} must be non-empty text`);
    }
    if (seen.has(selector)) {
      throw new TypeError(`method dictionary declares duplicate selector: ${selector}`);
    }
    seen.add(selector);
    return {id: `selector:${base64urlEncode(utf8Encode(selector))}`, name: selector};
  });
}

// Bootstrap must be safe on a populated image and restartable after a partial failure. The two
// record kinds fail differently on their own: `putObject` is an upsert, so a plain write would
// silently replace an existing `smalltalk/nil` or `Integer`; `putShape` is create-once, so a retry
// after a half-finished install would be rejected by the shapes it had already written.
//
// One rule covers both. Every bootstrap write is ensure-exact-or-create:
//
//   absent                  -> create
//   present and identical   -> reuse, write nothing
//   present and different   -> fail, overwrite nothing
class SmalltalkKernelConflictError extends TypeError {
  constructor(kind, imageId, objectId) {
    super(`${kind} ${imageId}/${objectId} already exists and differs from the kernel definition; refusing to overwrite it`);
    this.name = 'SmalltalkKernelConflictError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

// Key order is not part of a record's meaning, so compare a canonical projection rather than
// whatever order the caller or the backend happened to produce.
function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value ?? null);
}

function shapeLayoutProjection(record) {
  return canonicalJson({
    slots: record.slots ?? [],
    indexed: Object.hasOwn(record, 'indexed') ? record.indexed : SHAPE_INDEXED.NONE,
  });
}

async function ensureShape(service, imageId, desired) {
  const existing = await service.getShape(imageId, desired.id);
  if (!existing) return await service.putShape(imageId, desired);
  // ADR 0047: indexed is declared layout just like named slots. Absence remains the old `none`
  // meaning, but a values Shape must never compare equal to a pre-0047/no-indexed Shape by accident.
  if (shapeLayoutProjection(desired) !== shapeLayoutProjection(existing)) {
    throw new SmalltalkKernelConflictError('shape', imageId, desired.id);
  }
  return existing;
}

// `putObject` does take expectedVersion, and 0 means "must not already exist" — belt and braces
// alongside the existence check above, against a concurrent writer.
async function ensureObject(service, imageId, desired) {
  const existing = await service.getObject(imageId, desired.id);
  const projection = (record) => canonicalJson({
    shape: record.shape ?? null,
    behavior: record.behavior ?? null,
    slots: record.slots ?? {},
    // Unlike Shape, object absence is not equivalent to an empty indexed part: a values Shape
    // requires the property even when its length is zero. Exactness therefore preserves absence.
    indexed: Object.hasOwn(record, 'indexed') ? record.indexed : null,
    metadata: record.metadata ?? {},
  });
  if (!existing) return await service.putObject(imageId, desired, {expectedVersion: 0});
  if (projection(desired) !== projection(existing)) {
    throw new SmalltalkKernelConflictError('object', imageId, desired.id);
  }
  return existing;
}

// The global invariant, checked against stored data rather than assumed from how it was built.
// Generic graph writes can produce a dictionary shape with duplicate selector names, and any
// name-based lookup over that resolves by position — the first-wins defect ADR 0044 decision 2
// exists to remove. Validating the *whole* shape rather than only the selector being sent is what
// makes the invariant global rather than incidental to the send.
function assertUniqueSelectorShape(shape, label) {
  const seen = new Set();
  for (const {name} of shape.slots) {
    if (seen.has(name)) throw new TypeError(`${label} declares duplicate selector: ${name}`);
    seen.add(name);
  }
  return shape;
}

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['putShape', 'getShape', 'putObject', 'getObject']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

// Cross-image shape and slot references are legal, so an object id alone is not identity. Another
// image may hold its own `smalltalk/behavior-shape/v1`, and treating a ref to it as this image's
// kernel shape would misclassify a foreign record.
function isLocalRef(value, imageId, objectId) {
  return isObjectRef(value) && value.imageId === imageId && (objectId === undefined || value.objectId === objectId);
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// The kernel classes. `super` is the instance-side superclass name; the metaclass chain is derived
// from it by decision 4 rather than written out, so the two cannot drift apart.
const KERNEL_CLASSES = Object.freeze([
  {name: 'Object', super: null},
  {name: 'Class', super: 'Object'},
  {name: 'Metaclass', super: 'Object'},
  {name: 'UndefinedObject', super: 'Object'},
  {name: 'Boolean', super: 'Object'},
  {name: 'True', super: 'Boolean'},
  {name: 'False', super: 'Boolean'},
  {name: 'Integer', super: 'Object'},
  {name: 'Float', super: 'Object'},
  {name: 'Text', super: 'Object'},
  {name: 'ByteArray', super: 'Object'},
]);

const classId = (name) => `smalltalk/class/${name}`;
const metaclassId = (name) => `smalltalk/metaclass/${name}`;
const methodsId = (ownerId) => `${ownerId}/methods`;


// ADR 0049 decision 7: a class defined after this ADR gets the hashed representation immediately.
//
// Tolerant of a legacy record at the same id on purpose. Installing this machinery migrates nothing
// (decision 7), so re-running an installer against an image bootstrapped before it must reuse the
// legacy dictionary rather than demand it be replaced — that is a job for explicit migration, not a
// side effect of running the installer again.
// A record at this deterministic id is reused only when it is *provably* a valid legacy method
// dictionary. Accepting any non-hashed object would contradict both the ensure-exact-or-create rule
// and ADR 0049's promise that a class defined now gets the hashed representation: an unrelated
// squatter would be adopted as the class's method dictionary.
async function isLegacyMethodDictionary(service, imageId, record) {
  if (!record || record.kind !== 'object') return false;
  if (isMethodDictionary(record)) return false;
  // An empty legacy dictionary is structurally an ordinary empty object, so structure alone cannot
  // tell one from an unrelated record squatting on this deterministic id. Every legacy dictionary
  // this substrate ever wrote declares itself one, so the tag is the discriminator — a metadata
  // *label*, which hides no ref and is exactly what metadata is for.
  if (record.metadata?.smalltalk !== 'method-dictionary') return false;
  if (!isObjectRef(record.shape)) return false;
  const shape = await service.getShape(record.shape.imageId, record.shape.objectId);
  if (!shape) return false;
  try {
    assertUniqueSelectorShape(shape, `method dictionary ${imageId}/${record.id}`);
  } catch {
    return false;
  }
  // Every declared selector slot must hold a local unpinned Block ref, and the record must hold
  // nothing else — the same contract the legacy dispatcher reads.
  const declared = new Set(shape.slots.map(({id}) => id));
  if (Object.keys(record.slots ?? {}).some((slotId) => !declared.has(slotId))) return false;
  for (const {id: slotId} of shape.slots) {
    const method = record.slots?.[slotId];
    if (!isObjectRef(method) || method.imageId !== imageId) return false;
  }
  return true;
}

async function ensureEmptyMethodDictionary(service, imageId, id, metadata, nilRef) {
  const existing = await service.getObject(imageId, id);
  if (await isLegacyMethodDictionary(service, imageId, existing)) return existing;
  const {buckets} = buildMethodBuckets([]);
  return await ensureObject(service, imageId, {
    id,
    ...methodDictionaryRecordFields({
      buckets,
      shapeRef: objectRef(imageId, METHOD_DICTIONARY_SHAPE_ID),
      nilRef,
      metadata,
    }),
  });
}

async function installSmalltalkKernel({images, imageId} = {}) {
  const service = assertImages(images);
  requiredText(imageId, 'kernel image id');
  const ref = (objectId) => objectRef(imageId, objectId);

  await ensureMethodDictionaryShape(service, imageId);
  const shapes = {
    behavior: await ensureShape(service, imageId, {id: BEHAVIOR_SHAPE_ID, slots: [...BEHAVIOR_SLOTS]}),
    kernel: await ensureShape(service, imageId, {id: KERNEL_SHAPE_ID, slots: [...KERNEL_SLOTS]}),
    empty: await ensureShape(service, imageId, {id: EMPTY_SHAPE_ID, slots: []}),
  };
  // Every kernel method dictionary starts empty; methods arrive with the classes that need them.
  const emptyMethodsShapeId = `${EMPTY_SHAPE_ID}`;

  // A Behavior object. `behavior` and `superclass` are passed as refs rather than derived, because
  // the metaclass knot needs edges pointing at objects that do not exist yet — which `putObject`
  // permits, since it validates the shape but neither `behavior` nor ref-valued slots.
  const putBehavior = async ({id, name, superclassRef, behaviorRef, instanceShapeRef}) => {
    await ensureEmptyMethodDictionary(
      service, imageId, methodsId(id), {owner: id}, ref('smalltalk/nil'),
    );
    void emptyMethodsShapeId;
    return await ensureObject(service, imageId, {
      id,
      shape: ref(BEHAVIOR_SHAPE_ID),
      behavior: behaviorRef,
      slots: {
        'behavior-name': textValue(name),
        'behavior-superclass': superclassRef,
        'behavior-methods': ref(methodsId(id)),
        'behavior-instance-shape': instanceShapeRef,
      },
      metadata: {smalltalk: 'behavior', name},
    });
  };

  // The singletons first, so `nil` exists to stand in every absent slot. They are ordinary objects
  // with no slots; what makes them singular is that the kernel names them.
  const singletons = {};
  for (const [slotName, className, objectId] of [
    ['nil', 'UndefinedObject', 'smalltalk/nil'],
    ['true', 'True', 'smalltalk/true'],
    ['false', 'False', 'smalltalk/false'],
  ]) {
    singletons[slotName] = await ensureObject(service, imageId, {
      id: objectId,
      shape: ref(EMPTY_SHAPE_ID),
      behavior: ref(classId(className)),
      slots: {},
      metadata: {smalltalk: 'singleton', name: slotName},
    });
  }
  const nilRef = ref('smalltalk/nil');

  // Metaclasses. `behavior(aMetaclass) == Metaclass` for every one of them, including Metaclass's
  // own metaclass — which is the knot: `behavior(Metaclass class) == Metaclass`.
  //
  // Decision 4's chain rule is applied here rather than written out per class, so the class and
  // metaclass hierarchies cannot drift apart: `C class superclass == S class`, with `Object class
  // superclass == Class` as the root case.
  for (const {name, super: superName} of KERNEL_CLASSES) {
    await putBehavior({
      id: metaclassId(name),
      name: `${name} class`,
      superclassRef: superName === null ? ref(classId('Class')) : ref(metaclassId(superName)),
      behaviorRef: ref(classId('Metaclass')),
      instanceShapeRef: nilRef,
    });
  }

  // Classes. `behavior(aClass) == that class's metaclass`, and `nil` stands for "no superclass".
  for (const {name, super: superName} of KERNEL_CLASSES) {
    await putBehavior({
      id: classId(name),
      name,
      superclassRef: superName === null ? nilRef : ref(classId(superName)),
      behaviorRef: ref(metaclassId(name)),
      instanceShapeRef: nilRef,
    });
  }

  const kernel = await ensureObject(service, imageId, {
    id: SMALLTALK_KERNEL_OBJECT_ID,
    shape: ref(KERNEL_SHAPE_ID),
    behavior: ref(classId('Object')),
    slots: {
      'kernel-nil': ref('smalltalk/nil'),
      'kernel-true': ref('smalltalk/true'),
      'kernel-false': ref('smalltalk/false'),
      'kernel-object-class': ref(classId('Object')),
      'kernel-class-class': ref(classId('Class')),
      'kernel-metaclass-class': ref(classId('Metaclass')),
      'kernel-boolean-class': ref(classId('Boolean')),
      'kernel-integer-class': ref(classId('Integer')),
      'kernel-float-class': ref(classId('Float')),
      'kernel-text-class': ref(classId('Text')),
      'kernel-byte-array-class': ref(classId('ByteArray')),
    },
    metadata: {protocol: SMALLTALK_KERNEL_PROTOCOL_V1},
  });

  return Object.freeze({
    protocol: SMALLTALK_KERNEL_PROTOCOL_V1,
    ref: ref(SMALLTALK_KERNEL_OBJECT_ID),
    kernel,
    shapes: Object.freeze(shapes),
    singletons: Object.freeze(singletons),
  });
}

// Rediscovery: one image id in, the whole kernel out. Nothing here depends on having run the
// installer in this process.
async function findSmalltalkKernel({images, imageId} = {}) {
  const service = assertImages(images);
  requiredText(imageId, 'kernel image id');
  const record = await service.getObject(imageId, SMALLTALK_KERNEL_OBJECT_ID);
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_KERNEL_PROTOCOL_V1) {
    throw new TypeError(
      `object ${imageId}/${SMALLTALK_KERNEL_OBJECT_ID} does not declare ${SMALLTALK_KERNEL_PROTOCOL_V1}`,
    );
  }
  // Declaring the protocol is not enough: the record must actually have the kernel shape, in this
  // image, and every slot must be an unpinned local ref. Otherwise a partially-written or
  // deliberately-shaped impostor would be handed to the dispatcher.
  if (!isLocalRef(record.shape, imageId, KERNEL_SHAPE_ID)) {
    throw new TypeError(`Smalltalk kernel ${imageId}/${record.id} does not have shape ${KERNEL_SHAPE_ID}`);
  }
  const slots = {};
  for (const {id, name} of KERNEL_SLOTS) {
    const value = record.slots[id];
    if (!isLocalRef(value, imageId)) {
      throw new TypeError(`Smalltalk kernel slot ${name} must be an unpinned ref in ${imageId}`);
    }
    slots[name] = value;
  }
  return Object.freeze({protocol: SMALLTALK_KERNEL_PROTOCOL_V1, ref: objectRef(imageId, record.id), record, ...slots});
}

// ADR 0044 decision 10: a behavior record means what its own shape says it means. A fixed-shape
// Behavior gets ADR 0044 lookup; anything else is a legacy behavior and keeps legacy lookup.
// Installing the kernel therefore reinterprets nothing that already exists.
function isBehaviorObject(record) {
  return Boolean(record)
    && record.kind === 'object'
    && isLocalRef(record.shape, record.imageId, BEHAVIOR_SHAPE_ID);
}

async function readBehavior(images, ref) {
  const record = await assertImages(images).getObject(ref.imageId, ref.objectId);
  if (!record) throw new TypeError(`behavior not found: ${ref.imageId}/${ref.objectId}`);
  if (!isBehaviorObject(record)) throw new TypeError(`not a ${BEHAVIOR_SHAPE_ID} behavior: ${ref.objectId}`);
  // The next change makes this part of dispatch, so the slot types are checked here rather than
  // trusted there.
  const name = record.slots['behavior-name'];
  if (name?.kind !== VALUE_KIND.TEXT) throw new TypeError(`behavior ${ref.objectId} name must be a text Value`);
  const refSlots = {};
  for (const [slotId, label] of [
    ['behavior-superclass', 'superclass'],
    ['behavior-methods', 'methods'],
    ['behavior-instance-shape', 'instanceShape'],
  ]) {
    const value = record.slots[slotId];
    if (!isLocalRef(value, record.imageId)) {
      throw new TypeError(`behavior ${ref.objectId} ${label} must be an unpinned ref in ${record.imageId}`);
    }
    refSlots[label] = value;
  }
  return Object.freeze({record, name, ...refSlots});
}

// ADR 0044 decision 8's policy half, scoped exactly as the ADR scopes it: ADR 0043 decision 9 is
// superseded for bootstrapped *Symmetric Smalltalk* execution, so an artifact of any other language
// gets nothing back and its temporaries start UNBOUND — even in an image that carries a kernel.
//
// Deliberately unmemoized. Bootstrap is an installer for an existing image, so a runtime that
// observed an image before its kernel existed must see the kernel afterwards; caching would make
// execution depend on what the process happened to observe earlier rather than on current graph
// state. A cache without an invalidation contract hides later graph changes too, and there is no
// such contract to write against yet.
function createSmalltalkTemporaryInitializer() {
  return async ({images, dispatchImage, languageId}) => {
    if (!dispatchImage || languageId !== SYMMETRIC_SMALLTALK_ID) return null;
    const kernel = await findSmalltalkKernel({images, imageId: dispatchImage});
    return kernel ? kernel.nil : null;
  };
}

export {
  BEHAVIOR_SHAPE_ID,
  KERNEL_CLASSES,
  ensureEmptyMethodDictionary,
  isLegacyMethodDictionary,
  createSmalltalkTemporaryInitializer,
  SmalltalkKernelConflictError,
  assertUniqueSelectorShape,
  canonicalJson,
  ensureObject,
  ensureShape,
  isLocalRef,
  BEHAVIOR_SLOTS,
  EMPTY_SHAPE_ID,
  KERNEL_SHAPE_ID,
  KERNEL_SLOTS,
  KERNEL_SLOT_BY_NAME,
  SMALLTALK_KERNEL_OBJECT_ID,
  SMALLTALK_KERNEL_PROTOCOL_V1,
  findSmalltalkKernel,
  installSmalltalkKernel,
  isBehaviorObject,
  methodDictionarySlots,
  readBehavior,
};

import {findSmalltalkBlockProtocol} from './smalltalk-block-protocol.js';
import {findSmalltalkBlockUnwindProtocol} from './smalltalk-conditions.js';
import {resolveGlobal} from './smalltalk-globals.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {ensureNamedClass, ensureSmalltalkShape, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

// The first image-resident library: ordinary Smalltalk classes written with the facilities ADRs
// 0043-0050 built, and nothing else. No collection-specific primitive is added here, and none is
// used — every method below is source that the class-scoped compiler binds like any other.
//
// It is a substrate exercise as much as a library. Where an idiom is unavailable the code uses what
// exists rather than reaching for a host operation, and the awkwardness is left visible on purpose:
//
//   no conditions            a refusal is signalled by sending a selector nothing implements, so
//                            an out-of-range access fails as a message-not-understood naming the
//                            collection's own concept rather than raising anything
//
// Three of those gaps are now closed, and the awkwardness went with each. ADR 0051 gave Blocks
// `whileTrue:`/`whileFalse:`, so iteration is a loop rather than recursion under the 256-activation
// limit. ADR 0053 gave Integer `<=`, so a traversal states its bound instead of counting up to
// `tally + 1` and comparing with `=` — and `at:`, `first`, `last` and `removeLast` become possible,
// because each is a bounds check and a bounds check is an ordering question. ADR 0055 gave `^` a
// home, so `includes:` answers from inside its loop instead of carrying a `found` flag out.
//
// Each of those is a general language gap rather than a collection concern, and each is recorded in
// `docs/roadmap.md` rather than papered over here.

const ASSOCIATION_SHAPE_ID = 'smalltalk/association-instance-shape/v1';
const ORDERED_COLLECTION_SHAPE_ID = 'smalltalk/ordered-collection-instance-shape/v1';

// The hierarchy's root. `Collection` holds no state of its own — the enumeration protocol is
// written against `do:`, which a subclass supplies — so it carries no instance Shape and nothing
// here binds an instance variable. That is what lets the shared protocol live above every concrete
// collection without either duplicating it or pushing the subclass's layout up into the parent.
//
// `species` answers the class a derived collection should be made of. The default is the receiver's
// own class, which is what Smalltalk specifies and what `collect:`/`select:` need; a class whose
// derived collections should be something else (a SortedCollection answering an OrderedCollection,
// a Set answering a list for `collect:`) overrides `species`, not the enumeration methods.
const COLLECTION_METHODS = [
  {selector: 'species', source: '[ self class ]'},
  // Enumeration composes `do:` rather than touching any subclass state. `detect:ifNone:` returns
  // from inside its loop (ADR 0055), and `inject:into:` threads an accumulator — both ordinary
  // Smalltalk over `do:`, with no primitive and no compiler involvement.
  {
    selector: 'collect:',
    source: `[ :aBlock | | result |
      result := self species new.
      self do: [ :each | result add: (aBlock value: each) ].
      ^ result ]`,
  },
  {
    selector: 'select:',
    source: `[ :aBlock | | result |
      result := self species new.
      self do: [ :each | (aBlock value: each) ifTrue: [ result add: each ] ].
      ^ result ]`,
  },
  {
    selector: 'detect:ifNone:',
    source: `[ :aBlock :noneBlock |
      self do: [ :each | (aBlock value: each) ifTrue: [ ^ each ] ].
      ^ noneBlock value ]`,
  },
  {
    selector: 'inject:into:',
    source: `[ :initial :binaryBlock | | accumulator |
      accumulator := initial.
      self do: [ :each | accumulator := binaryBlock value: accumulator value: each ].
      ^ accumulator ]`,
  },
];

const ASSOCIATION_METHODS = [
  {selector: 'key', source: '[ key ]'},
  {selector: 'value', source: '[ value ]'},
  {selector: 'key:value:', source: '[ :aKey :aValue | key := aKey. value := aValue. self ]'},
  {selector: 'value:', source: '[ :aValue | value := aValue. self ]'},
  // A same-class guard first, because sending `key` to an arbitrary object would be
  // message-not-understood rather than an answer of false.
  {
    selector: '=',
    source: `[ :other |
      (other class = self class)
        ifTrue: [ (key = other key) and: [ value = other value ] ]
        ifFalse: [ false ] ]`,
  },
  // Equal Associations must hash alike (ADR 0048 decision 4). Hashing the key alone satisfies that
  // and is what a Dictionary of Associations wants.
  {selector: 'hash', source: '[ key hash ]'},
];



const ORDERED_COLLECTION_METHODS = [
  {
    selector: 'initialize',
    source: '[ contents := Array new: 4. tally := 0. self ]',
  },
  {selector: 'size', source: '[ tally ]'},
  {selector: 'isEmpty', source: '[ tally = 0 ]'},

  // Growth is a policy of this class, not of storage — exactly as ADR 0047 decision 6 said it would
  // be: an OrderedCollection is an ordinary object holding an Array plus a size and a growth policy.
  {selector: 'add:', source: '[ :item | self ensureRoom. tally := tally + 1. contents at: tally put: item. item ]'},
  {selector: 'ensureRoom', source: '[ (tally = contents size) ifTrue: [ self grow ] ]'},
  {
    selector: 'grow',
    source: `[ | bigger |
      bigger := Array new: (contents size + contents size).
      self copyInto: bigger.
      contents := bigger.
      self ]`,
  },

  // Iteration is a loop (ADR 0051) that states its bound with `<=` (ADR 0053), rather than
  // recursion counting up to `tally + 1` to avoid an ordering comparison that did not exist.
  {
    selector: 'copyInto:',
    source: `[ :target | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        target at: index put: (contents at: index).
        index := index + 1 ] ]`,
  },
  {
    selector: 'do:',
    source: `[ :aBlock | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        aBlock value: (contents at: index).
        index := index + 1 ] ]`,
  },
  // Answers from inside the loop (ADR 0055). The `found` temporary this used to carry existed only
  // because a Block could not return from its enclosing method; it went with the gap rather than
  // surviving as decoration.
  {
    selector: 'includes:',
    source: `[ :item | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        (item = (contents at: index)) ifTrue: [ ^ true ] ifFalse: [ false ].
        index := index + 1 ].
      false ]`,
  },
  // ADR 0053's point. Each of these is a bounds check, which is why none existed before an ordering
  // comparison did.
  //
  // The bound is the collection's own `tally`, never the backing Array's capacity: `contents at:`
  // succeeds for any index up to capacity, so a collection that deferred to it would cheerfully
  // answer whatever slack the growth policy left behind.
  //
  // A refusal is an ordinary signal (ADR 0054), so a caller can handle it — which is what makes
  // `at:ifAbsent:` writable in Smalltalk rather than needing a second primitive. Before that ADR
  // this sent `errorIndexOutOfBounds:`, which nothing implemented, so the failure arrived as a
  // message-not-understood that no one could catch.
  {
    selector: 'at:',
    source: `[ :index |
      (index < 1)
        ifTrue: [ (IndexOutOfRange new) signal ]
        ifFalse: [ (index <= tally)
          ifTrue: [ contents at: index ]
          ifFalse: [ (IndexOutOfRange new) signal ] ] ]`,
  },
  // Expressible only because the refusal is catchable: the alternative Block is evaluated by
  // handling the collection's own signal, with no new protocol underneath it.
  {
    selector: 'at:ifAbsent:',
    source: '[ :index :aBlock | [ self at: index ] on: IndexOutOfRange do: [ :e | aBlock value ] ]',
  },
  {selector: 'first', source: '[ self at: 1 ]'},
  {selector: 'last', source: '[ self at: tally ]'},
  // The vacated slot is cleared, not merely hidden. `at:` would refuse to answer it either way, but
  // the backing Array is a durable object: leaving the ref there keeps the removed element
  // graph-reachable, so a large collection drained to empty would retain every element it ever held.
  {
    selector: 'removeLast',
    source: `[ | item |
      (tally < 1)
        ifTrue: [ (EmptyCollection new) signal ]
        ifFalse: [
          item := contents at: tally.
          contents at: tally put: nil.
          tally := tally - 1.
          item ] ]`,
  },
  // Higher-order enumeration no longer lives here: it moved to Collection with the rest of the
  // shared protocol, written against `do:` and `species` rather than `contents`/`tally`. What
  // remains is OrderedCollection's own layout and growth — the parts Collection cannot know.
  {
    selector: 'asArray',
    source: `[ | result |
      result := Array new: tally.
      self copyInto: result.
      result ]`,
  },
];

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Both go through the shared ensure-exact-or-create helpers. Accepting *any* record at a
// deterministic id would adopt an unrelated object as this class or its layout — the rule the
// repository applies to every derived id, and the reason `defineClass` alone is not enough for
// rediscovery once methods exist.
async function ensureLibraryClass({images, imageId, name, shapeId, slots, superclassRef = null}) {
  // A stateless class carries no instance Shape. `ensureNamedClass` answers nil for it, and
  // `defineClass`'s complete-layout rule is satisfied because a nil-shape ancestor declares nothing
  // a subclass could drop.
  const instanceShapeRef = shapeId
    ? await ensureSmalltalkShape(images, imageId, {id: shapeId, slots})
    : null;
  return (await ensureNamedClass({images, imageId, name, superclassRef, instanceShapeRef})).classRef;
}

// Installed after the kernel protocols this library is written against: allocation (ADR 0046),
// conditionals (0045), Array (0047), equality (0048) and instance variables (0050).
async function installSmalltalkLibrary({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const associationRef = await ensureLibraryClass({
    images,
    imageId,
    name: 'Association',
    shapeId: ASSOCIATION_SHAPE_ID,
    slots: [{id: 'association-key', name: 'key'}, {id: 'association-value', name: 'value'}],
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: associationRef, methods: ASSOCIATION_METHODS,
  });

  // Collection before its subclass: OrderedCollection names it as superclass, and Collection's
  // shared enumeration is defined once here rather than repeated per concrete collection.
  const collectionRef = await ensureLibraryClass({images, imageId, name: 'Collection'});
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: collectionRef, methods: COLLECTION_METHODS,
  });

  const orderedCollectionRef = await ensureLibraryClass({
    images,
    imageId,
    name: 'OrderedCollection',
    superclassRef: collectionRef,
    shapeId: ORDERED_COLLECTION_SHAPE_ID,
    slots: [
      {id: 'ordered-collection-contents', name: 'contents'},
      {id: 'ordered-collection-tally', name: 'tally'},
    ],
  });
  // Restored prerequisites. Every traversal loops, so an image without ADR 0051's Block protocol
  // would install methods that compile cleanly and fail with "Block does not understand:
  // whileFalse:" on first use. Refused here instead, where the cause is still visible.
  if (!await findSmalltalkBlockProtocol({images, imageId})) {
    throw new TypeError(`image ${imageId} has no Smalltalk Block protocol; install it first`);
  }
  // Checked as installed *methods*, not as the presence of the primitive Blocks: the Integer
  // installer publishes its primitives before its methods, so a Block-existence check would pass on
  // a half-installed protocol with `<`, `<=` and `-` still absent.
  for (const selector of ['<', '<=', '-']) {
    if (!await methodBlockRef({images, imageId, classRef: kernel.integerClass, selector})) {
      throw new TypeError(`image ${imageId} has no Integer ${selector} method; install the Integer protocol first`);
    }
  }
  // The unwind protocol object is published *before* the condition classes and their methods, so
  // checking only for it would pass on a half-installed protocol with `Exception >> signal` still
  // missing — the same partial-install hazard the Integer check already closes. Checked as an
  // installed method on a class this library actually signals.
  if (!await findSmalltalkBlockUnwindProtocol({images, imageId})) {
    throw new TypeError(`image ${imageId} has no Smalltalk condition protocol; install it first`);
  }
  const exceptionClass = objectRef(imageId, 'smalltalk/class/Exception');
  if (!await images.getObject(imageId, exceptionClass.objectId)
    || !await methodBlockRef({images, imageId, classRef: exceptionClass, selector: 'signal'})) {
    throw new TypeError(`image ${imageId} has no Exception signal method; install the condition protocol first`);
  }
  for (const name of ['IndexOutOfRange', 'EmptyCollection']) {
    if (!await images.getObject(imageId, `smalltalk/class/${name}`)) {
      throw new TypeError(`image ${imageId} has no ${name} class; install the condition protocol first`);
    }
  }
  // ADR 0057: this library's source names `Array`, `IndexOutOfRange` and `EmptyCollection`, so
  // those globals must have been published. Checked here, where the cause is visible, rather than
  // failing later as an unbound name inside a method body.
  for (const name of ['Array', 'IndexOutOfRange', 'EmptyCollection']) {
    if (!await resolveGlobal({images, imageId, name})) {
      throw new TypeError(`image ${imageId} has not published the global ${name}; publish it first`);
    }
  }

  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: orderedCollectionRef,
    // No captures at all: every class these methods name is resolved through the image's namespace
    // (ADR 0057), so the installer no longer has to know which classes each method mentions.
    methods: ORDERED_COLLECTION_METHODS,
  });

  return Object.freeze({
    association: associationRef,
    collection: collectionRef,
    orderedCollection: orderedCollectionRef,
  });
}

