  ASSOCIATION_METHODS,
  ASSOCIATION_SHAPE_ID,
  COLLECTION_METHODS,
  ORDERED_COLLECTION_METHODS,
  ORDERED_COLLECTION_SHAPE_ID,
  installSmalltalkLibrary,
