// One locality rule for every primitive. A foreign primitive Block must fail rather than answer a
// foreign kernel's class, allocate into somebody else's image, or mutate a foreign indexed object.
class SmalltalkPrimitiveLocalityError extends TypeError {
  constructor(primitive, primitiveImage, ref) {
    super(
      `Symmetric Smalltalk ${primitive} primitive in ${primitiveImage} cannot act on `
      + `${ref.imageId}/${ref.objectId}; a primitive is local to its own image`,
    );
    this.name = 'SmalltalkPrimitiveLocalityError';
    this.primitive = primitive;
    this.primitiveImage = primitiveImage;
  }
}

class SmalltalkPrimitiveReceiverError extends TypeError {
  constructor(primitive, description) {
    super(`Symmetric Smalltalk ${primitive} primitive cannot act on ${description}`);
    this.name = 'SmalltalkPrimitiveReceiverError';
    this.primitive = primitive;
  }
}

function parsePrimitiveCode(code) {
  if (code.content?.kind !== VALUE_KIND.TEXT) {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must be a text Value`);
  }
  let declaration;
  try {
    declaration = JSON.parse(code.content.value);
  } catch (error) {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must contain valid JSON`, {cause: error});
  }
  const keys = Object.keys(declaration ?? {});
  if (keys.length !== 1 || keys[0] !== 'primitive') {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must contain exactly primitive`);
  }
  if (!SMALLTALK_PRIMITIVE_NAMES.includes(declaration.primitive)) {
    throw new TypeError(`unknown ${SMALLTALK_KERNEL_PRIMITIVE_V1} primitive: ${declaration.primitive}`);
  }
  return declaration.primitive;
}

function primitiveCodeContent(primitive) {
  if (!SMALLTALK_PRIMITIVE_NAMES.includes(primitive)) {
    throw new TypeError(`unknown ${SMALLTALK_KERNEL_PRIMITIVE_V1} primitive: ${primitive}`);
  }
  return JSON.stringify({primitive});
}

function assertLocalRef(value, primitiveImage, primitive, description) {
  if (!isObjectRef(value)) {
    throw new SmalltalkPrimitiveReceiverError(
      primitive,
      value?.kind ? `a ${value.kind} Value; ${description}` : `a non-ref; ${description}`,
    );
  }
  if (value.imageId !== primitiveImage) {
    throw new SmalltalkPrimitiveLocalityError(primitive, primitiveImage, value);
  }
  return value;
}

// ADR 0052 decision 6: writing into a slot, an indexed part or a Dictionary makes a value durably
// reachable, so it is an escape. Each of these boundaries rewrites the value through the one central
// promoter and then performs its existing write unchanged — the promotion is the boundary's job, not
// the graph guard's.
//
// A context without `promote` is an execution that predates this seam rather than an error: the
// value passes through, and the graph guard still refuses a transient ref, so a missed boundary
// fails loudly instead of silently persisting a dangling reference.
//
// ADR 0060: a slot or indexed write is a durability boundary *only when the receiver is durable*.
// Writing a transient value into a transient receiver keeps both inside the arena — nothing has
// escaped yet — so the value must NOT be promoted, or every `OrderedCollection`'s backing store
// would become durable the instant it is assigned. `receiver` is the object being written into;
// when it is a transient ref the write stays in the arena and the value passes through unpromoted.
async function promoted(context, value, receiver = null) {
  if (typeof context?.promote !== 'function') return value;
  if (receiver !== null && isTransientRef(receiver)) return value;
  return await context.promote(value);
}

function requireSendMessage(context, primitive, purpose = 'send hash and =') {
  if (typeof context?.sendMessage !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a message runtime to ${purpose}`);
  }
  return context.sendMessage;
}

// ADR 0054 decision 8. A host failure that has a condition class becomes an ordinary Smalltalk
// signal, so it is catchable — and resumable, since a handler's `resume:` answers the operation.
//
// Absent the condition protocol, the host error is thrown as before. That is what keeps an image
// without ADR 0054 working unchanged rather than acquiring a dependency it never installed.
async function signalHostCondition({
  images, primitiveImage, context, classId, hostError, newObjectId, maxIdentityAttempts,
}) {
  const facade = context?.conditions;
  const sendMessage = context?.sendMessage;
  if (!facade || typeof sendMessage !== 'function') throw hostError;
  const classRecord = await images.getObject(primitiveImage, classId);
  if (!classRecord) throw hostError;

  // ADR 0060 decision 2: a condition created, signalled, handled and discarded inside one execution
  // never leaves the arena, so a handled condition costs no durable object. An unhandled one
  // crosses the root boundary and is promoted there — exactly when its information must outlive
  // the execution. Minted into the arena like `basicNew`; the record form below is unchanged, so
  // promotion is a copy.
  if (typeof context?.mintObject === 'function') {
    const instanceRef = context.mintObject({
      imageId: primitiveImage,
      shape: objectRef(primitiveImage, EXCEPTION_SHAPE_ID),
      behavior: objectRef(primitiveImage, classId),
      slots: {'exception-message-text': textValue(hostError.message)},
      metadata: {},
    });
    // An ordinary send, exactly as below — the receiver is the arena ref, resolved arena-first.
    return await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: instanceRef,
      message: textValue('signal'),
      arguments: [],
    });
  }

  // ADR 0054 decision 1a: a condition is an ordinary object, so it is allocated by ordinary rules —
  // including ADR 0046's identity retry. Writing once at `expectedVersion: 0` would turn an id
  // collision into a failure where every other allocation simply picks another candidate.
  const instance = await (async () => {
    for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
      const candidate = newObjectId();
      if (typeof candidate !== 'string' || candidate.length === 0) {
        throw new TypeError('Smalltalk object identity generator must answer non-empty text');
      }
      try {
        return await images.putObject(primitiveImage, {
          id: candidate,
          shape: objectRef(primitiveImage, EXCEPTION_SHAPE_ID),
          behavior: objectRef(primitiveImage, classId),
          slots: {'exception-message-text': textValue(hostError.message)},
          metadata: {},
        }, {expectedVersion: 0});
      } catch (error) {
        if (error?.name !== 'VersionConflictError') throw error;
      }
    }
    throw new TypeError(
      `Symmetric Smalltalk could not find a free object identity in ${primitiveImage} `
      + `after ${maxIdentityAttempts} attempts`,
    );
  })();

  // An ordinary send, so the handler search, the transfer protocol and resumption are exactly the
  // ones Smalltalk code gets — this is not a second signalling path.
  return await sendMessage({
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: objectRef(primitiveImage, instance.id),
    message: textValue('signal'),
    arguments: [],
  });
}

// ADR 0051 decision 4. Every other primitive is applied as `aPrimitive value: x`, so
// `assertBlockApplicationReceiver` can demand that the activation's receiver *is* the Block. A loop
// primitive is dispatched instead, with the condition Block as receiver, so that guard cannot apply
// and something must replace it — otherwise `aLoopPrimitive value: aBlock` would arrive with the
// primitive itself as the condition, which is precisely the bypass the structural rule below closes.
//
// "Kernel-primitive Block" is the existing structural test and nothing else: the Block's CodeArtifact
// has representation `smalltalk-kernel-primitive/v1`. That is already how the dispatcher decides
// frame inheritance for a Block send, so this reuses a definition the system depends on rather than
// adding a second, weaker notion of "is a primitive" that the two could drift apart on.
//
// The Dictionary enumeration primitive shares this guard for its pair Block, for the same reason:
// a Block about to be applied on a primitive's behalf must not itself be a kernel primitive.
async function assertLoopBlock({images, value, primitive, role}) {
  // A direct `invokeBlock` leaves the receiver null, which `assertBlockApplicationReceiver` treats as
  // the legitimate direct-application case. For a loop primitive it is not legitimate at all: there
  // is no condition Block, so say that rather than failing later on an untagged value.
  if (value === null || value === undefined) {
    throw new SmalltalkPrimitiveReceiverError(
      primitive,
      `no ${role}; a loop primitive is reachable only by dispatching whileTrue: or whileFalse:`,
    );
  }
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${ref.kind} Value as the ${role}`);
  }
  const block = await images.getBlock(ref.imageId, ref.objectId);
  if (!block) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `${ref.imageId}/${ref.objectId} as the ${role}, which is not a Block`);
  }
  const code = block.code && await images.getCodeArtifact(block.code.imageId, block.code.objectId);
  if (code?.representation === SMALLTALK_KERNEL_PRIMITIVE_V1) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a kernel-primitive Block as the ${role}`);
  }
  return ref;
}

export {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  SMALLTALK_PRIMITIVE_ARITY,
  SMALLTALK_PRIMITIVE_NAMES,
  SmalltalkPrimitiveLocalityError,
  SmalltalkPrimitiveReceiverError,
  assertLocalRef,
  assertLoopBlock,
  parsePrimitiveCode,
  primitiveCodeContent,
  promoted,
  requireSendMessage,
  signalHostCondition,
};

import {base64Decode, bytesEqual, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';
import {
  VALUE_KIND,
  bytesValue,
  canonicalizeValue,
  integerValue,
  textValue,
} from '../value/index.js';
import {SmalltalkPrimitiveReceiverError} from './smalltalk-primitive-support.js';

// WS3 Text/ByteArray slice: a tiny byte-sequence primitive family over the
// native immutable Value representations.
//
// A Text Value (`{kind:'text', value}`) and an immediate bytes Value
// (`{kind:'bytes', base64}`) are *physically different models* from Array's
// indexed-object storage (ADR 0047): the bytes Value is a Value, dispatching
// through the kernel's `ByteArray` class, not an indexed image object. The
// directive is explicit — do NOT widen the ADR 0047 indexed primitives
// (`indexed-size`/`indexed-at`) to bytes Values, and do NOT create a second
// ByteArray as an indexed image object. This family is the byte-sequence
// equivalent of `symbol-intern`/`class-of`: language-owned primitives over the
// native representations.
//
// UTF-8 is the only codec here, matching the upstream Pharo portable-util
// precedent (which overrides `bytesFromString:`/`stringFromBytes:` with an
// explicit UTF-8 codec rather than a generic `asByteArray`). `asByteArray` /
// `asString` are deliberately NOT defined as UTF-8 — encoding is dialect
// policy, not a default.
//
// Refusal rules (directives): malformed UTF-8 decode is refused, never
// lossy-replaced; an ill-formed/lone-surrogate Text source is refused, never
// silently substituted.

function requireText(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.TEXT) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} Value; ${primitive} requires a Text Value`);
  }
  return normalized.value;
}

function requireBytes(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.BYTES) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} Value; ${primitive} requires a ByteArray Value`);
  }
  return base64Decode(normalized.base64);
}

// A lone surrogate is ill-formed Unicode scalar data: there is no valid UTF-8
// encoding for it, so encode must refuse rather than emit a replacement char.
function assertWellFormedText(text, primitive) {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) {
        throw new SmalltalkPrimitiveReceiverError(
          primitive, 'a Text Value containing a lone surrogate (ill-formed Unicode scalar data)',
        );
      }
      index += 1; // skip the low surrogate of a valid pair
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new SmalltalkPrimitiveReceiverError(
        primitive, 'a Text Value containing a lone surrogate (ill-formed Unicode scalar data)',
      );
    }
  }
  return text;
}

// Strict UTF-8 decode: a lossy decode substitutes U+FFFD for malformed
// sequences, so decode is validated by re-encoding and comparing — any lossy
// substitution changes the bytes and is detected. Overlong forms and
// out-of-range sequences are likewise rejected by the round-trip check.
function decodeUtf8Strict(bytes, primitive) {
  const text = utf8DecodeLossy(bytes);
  if (!bytesEqual(utf8Encode(text), bytes)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, 'a malformed UTF-8 byte sequence; decode refused');
  }
  return text;
}

async function textUtf8Bytes({value}) {
  const text = assertWellFormedText(requireText(value, 'text-utf8-bytes'), 'text-utf8-bytes');
  return bytesValue(utf8Encode(text));
}

async function byteArrayUtf8Text({value}) {
  const buffer = requireBytes(value, 'bytearray-utf8-text');
  return textValue(decodeUtf8Strict(buffer, 'bytearray-utf8-text'));
}

async function byteArraySize({value}) {
  return integerValue(requireBytes(value, 'bytearray-size').length);
}

async function byteArrayAt({value, indexValue}) {
  const buffer = requireBytes(value, 'bytearray-at');
  const normalized = canonicalizeValue(indexValue);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError('bytearray-at', `a ${normalized.kind} index; index must be an Integer Value`);
  }
  const oneBased = BigInt(normalized.value);
  // 1-based indexing, matching Array>>at: / Smalltalk collection convention.
  if (oneBased < 1n || oneBased > BigInt(buffer.length)) {
    throw new RangeError(
      `Symmetric Smalltalk bytearray-at index ${oneBased.toString()} is outside the 1..${buffer.length} range`,
    );
  }
  return integerValue(buffer[Number(oneBased) - 1]);
}

// `fromArray:` backing: an Array (or OrderedCollection's `asArray` result) of
// integer bytes -> a native bytes Value. Every element is validated 0..255 —
// a non-integer or out-of-range element is refused, never truncated.
async function arrayToByteArray({images, primitiveImage, value}) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.REF) {
    throw new SmalltalkPrimitiveReceiverError(
      'array-to-bytearray', `a ${normalized.kind} Value; the source must be an Array of integers`,
    );
  }
  const record = await images.getObject(primitiveImage, normalized.objectId);
  if (!record || !Array.isArray(record.indexed)) {
    throw new SmalltalkPrimitiveReceiverError(
      'array-to-bytearray', `${normalized.objectId}, which has no indexed integer storage`,
    );
  }
  const bytes = new Uint8Array(record.indexed.length);
  for (let index = 0; index < record.indexed.length; index += 1) {
    const element = canonicalizeValue(record.indexed[index]);
    if (element.kind !== VALUE_KIND.INTEGER) {
      throw new SmalltalkPrimitiveReceiverError(
        'array-to-bytearray', `an Array whose element ${index + 1} is a ${element.kind} Value, not an integer byte`,
      );
    }
    const byte = BigInt(element.value);
    if (byte < 0n || byte > 255n) {
      throw new RangeError(`Symmetric Smalltalk array-to-bytearray element ${index + 1} value ${byte.toString()} is not in 0..255`);
    }
    bytes[index] = Number(byte);
  }
  return bytesValue(bytes);
}

export {
  arrayToByteArray,
  byteArrayAt,
  byteArraySize,
  byteArrayUtf8Text,
  textUtf8Bytes,
};

import {
  ConditionTransfer,
  NonLocalReturnHomeError,
  NonLocalReturnTransfer,
  SmalltalkNoActiveOccurrenceError,
  SmalltalkUnhandledConditionError,
} from '../execution/conditions.js';
import {sameRefIdentity} from './smalltalk-equality.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {behaviorRefFor} from './smalltalk-lookup.js';
import {
  SMALLTALK_PRIMITIVE,
  SmalltalkPrimitiveReceiverError,
  assertLoopBlock,
  requireSendMessage,
} from './smalltalk-primitive-support.js';
import {TupleSet} from '../support/tuple-map.js';
import {
  VALUE_KIND,
  canonicalizeValue,
  isObjectRef,
  textValue,
} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// The control-transfer primitives: loops (ADR 0051), unwind protection and the condition transfer
// protocol (ADR 0054), and non-local return (ADR 0055). Everything here manipulates activations and
// scopes rather than durable object state.

// ADR 0055. `^ expr` lowers to `$nonLocalReturn value: expr`, so this primitive runs with the home
// method's frame already in hand: a kernel-primitive send INHERITS the caller's frame (ADR 0050 rule
// 2), and a closure activation RESTORES the frame it was created in (rule 3). Chained, those two
// rules hand it the home frame with no new propagation.
//
// It never catches its own transfer, because it only *borrows* that frame — decision 3a makes
// stopping the transfer the owner's job.
function nonLocalReturn({activation, context, primitive}) {
  const frame = context?.invocationFrame ?? null;
  if (!frame) {
    // No frame at all: the Block outlived the execution that created it, so its home is
    // unreachable — the same fail-closed shape ADR 0050 decision 10a gives an escaped
    // ivar-dependent closure, and for the same reason.
    throw new NonLocalReturnHomeError(
      'the Block has no home frame; it outlived the execution that created it',
    );
  }
  if (typeof context.conditions?.homeActivationState !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a condition runtime`);
  }
  const state = context.conditions.homeActivationState(frame);
  if (state === 'dead') {
    // The frame is still reachable, so its identity is known — and it is known to be finished.
    // Saying so beats the vaguer "no home", which is why the registry retains dead entries.
    const selector = context.conditions.homeActivationSelector?.(frame) ?? null;
    const behavior = frame.definingBehavior?.objectId ?? 'unknown';
    throw new NonLocalReturnHomeError(
      `the home method activation has already returned: ${behavior}${selector ? ` >> ${selector}` : ''}`,
    );
  }
  if (state !== 'live') {
    // A frame this executor never ran as a home: distinct from one that ran and returned, and the
    // reason the registry has three states rather than two.
    throw new NonLocalReturnHomeError('the frame in force is not a home method activation');
  }
  throw new NonLocalReturnTransfer(frame, canonicalizeValue(activation.arguments[0]));
}

// ADR 0054. The unwind operations and the transfer protocol.
//
// All three Block operations share one shape: establish a scope on the execution's condition
// runtime, run the protected Block, and leave the scope on the way out however that happens.
function requireConditions(context, primitive) {
  const facade = context?.conditions;
  if (!facade || typeof facade.captureAuthority !== 'function' || typeof facade.invoke !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a condition runtime`);
  }
  return facade;
}

// A condition handles another when its class is the same or an ancestor. Walked through the ordinary
// Behavior chain, so a user-defined Exception subclass participates without the runtime knowing it
// exists.
async function conditionIsKindOf({images, conditionClass, candidateClass}) {
  let current = candidateClass;
  const seen = new TupleSet(2);
  while (isObjectRef(current)) {
    if (sameRefIdentity(current, conditionClass)) return true;
    if (seen.has([current.imageId, current.objectId])) return false;
    seen.add([current.imageId, current.objectId]);
    const behavior = await images.getObject(current.imageId, current.objectId);
    if (!behavior) return false;
    const superclass = behavior.slots?.['behavior-superclass'];
    current = isObjectRef(superclass) ? superclass : null;
  }
  return false;
}

async function classOfCondition({images, primitiveImage, condition}) {
  const {behavior} = await behaviorRefFor({images, receiver: condition, dispatchImage: primitiveImage});
  return behavior;
}

async function blockOnDo({images, activation, context, primitive}) {
  const protectedBlock = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'protected block',
  });
  const [conditionClass, handlerBlock] = activation.arguments;
  if (!isObjectRef(canonicalizeValue(conditionClass))) {
    throw new SmalltalkPrimitiveReceiverError(primitive, 'a non-class as the condition class');
  }
  const handler = await assertLoopBlock({images, value: handlerBlock, primitive, role: 'handler block'});
  const facade = requireConditions(context, primitive);
  // Captured here, at establishment: the handler runs with the rights in force where `on:do:` was
  // written, never with the signaller's.
  const authorityToken = facade.captureAuthority();

  const scopeId = facade.runtime.enterHandler({
    conditionClass: canonicalizeValue(conditionClass), block: handler, authorityToken,
  });
  try {
    return await facade.invoke(authorityToken, protectedBlock, []);
  } catch (error) {
    // `return:` — including a handler's ordinary value, which means `return:` implicitly — lands
    // here, and only for *this* scope. Anything aimed at an outer scope keeps travelling.
    if (error instanceof ConditionTransfer && error.kind === 'return' && error.scopeId === scopeId) {
      return canonicalizeValue(error.value);
    }
    throw error;
  } finally {
    facade.runtime.leave(scopeId);
  }
}

async function blockEnsure({images, activation, context, primitive, onlyWhenCurtailed}) {
  const protectedBlock = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'protected block',
  });
  const cleanupBlock = await assertLoopBlock({
    images, value: activation.arguments[0], primitive, role: 'cleanup block',
  });
  const facade = requireConditions(context, primitive);
  const authorityToken = facade.captureAuthority();
  const scopeId = facade.runtime.enterProtection({kind: primitive, block: cleanupBlock, authorityToken});

  let result = null;
  let primary = null;
  try {
    result = await facade.invoke(authorityToken, protectedBlock, []);
  } catch (error) {
    primary = error;
  } finally {
    facade.runtime.leave(scopeId);
  }

  // Every non-normal exit, not only a catchable condition: a host trap crossing this scope travels
  // as an ordinary throw and must run the cleanup too. Protection that only fired for catchable
  // failures would stop working exactly when something unexpected happened.
  if (primary !== null || !onlyWhenCurtailed) {
    try {
      // The cleanup Block's own value is discarded — cleanup runs for its effect, and letting it
      // replace the answer would make adding a logging line change what the expression evaluates to.
      await facade.invoke(authorityToken, cleanupBlock, []);
    } catch (secondary) {
      // A cleanup failure is a real failure and stays catchable. It becomes the failure travelling
      // outward, retaining the one that was already unwinding so neither is lost.
      if (primary !== null && secondary && typeof secondary === 'object' && !secondary.duringUnwind) {
        secondary.duringUnwind = primary;
      }
      throw secondary;
    }
  }
  if (primary !== null) throw primary;
  return result;
}

async function conditionSignal({images, primitiveImage, activation, context, primitive}) {
  const condition = canonicalizeValue(activation.arguments[0]);
  if (!isObjectRef(condition)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${condition.kind} Value as the condition`);
  }
  const facade = requireConditions(context, primitive);
  const conditionClass = await classOfCondition({images, primitiveImage, condition});

  // A handler for class H catches a condition of class C when C is H or a subclass of it.
  const scope = await facade.runtime.findHandler(async (handled) =>
    await conditionIsKindOf({images, conditionClass: handled, candidateClass: conditionClass}));
  if (!scope) {
    throw new SmalltalkUnhandledConditionError(`${condition.imageId}/${condition.objectId}`);
  }

  const occurrence = facade.runtime.beginOccurrence(condition, scope.scopeId);
  try {
    // Disabled while it runs, so a re-signal from inside the handler delegates to an *outer*
    // handler rather than recursing into itself.
    const answer = await facade.runtime.withDisabled(
      scope,
      async () => await facade.invoke(scope.authorityToken, scope.block, [condition]),
    );
    // A handler's ordinary value means `return:`.
    throw new ConditionTransfer('return', scope.scopeId, canonicalizeValue(answer));
  } catch (error) {
    if (error instanceof ConditionTransfer && error.kind === 'resume' && error.occurrenceId === occurrence) {
      // The signalling send answers, and computation continues — which in the WASM lane is the
      // guest resuming at its effect site, with no ABI involvement at all.
      return canonicalizeValue(error.value);
    }
    throw error;
  } finally {
    facade.runtime.endOccurrence(occurrence);
  }
}

function conditionTransferOut({facade, condition, value, kind, primitive}) {
  const occurrence = facade.runtime.activeOccurrenceFor(
    (candidate) => sameRefIdentity(candidate, condition),
  );
  if (!occurrence) throw new SmalltalkNoActiveOccurrenceError(primitive);
  if (kind === 'resume') {
    throw new ConditionTransfer('resume', null, value, occurrence.occurrenceId);
  }
  throw new ConditionTransfer('return', occurrence.handlerScopeId, value);
}

// The loop itself. Every evaluation is an ordinary nested `value` send through the execution
// context, never a direct execution of the Block's code, so lexical frame restoration, authority
// attenuation, the dispatch image and cell arenas are inherited rather than reimplemented here.
//
// Constant activation depth falls out of the shape rather than from any bookkeeping: each `await`
// returns before the next send begins, so the sends are siblings from this one activation rather
// than a nesting chain, and depth does not grow with iteration count.
async function blockWhile({images, activation, context, primitive, wanted}) {
  const condition = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'condition',
  });
  const body = await assertLoopBlock({
    images, value: activation.arguments[0], primitive, role: 'body',
  });
  const sendMessage = requireSendMessage(context, primitive);

  // ADR 0051 decision 12: the loop answers the condition image's nil, rediscovered from that image's
  // current kernel rather than captured at install time — a captured nil would keep answering after
  // the image's kernel changed underneath it. Resolved before the first iteration so a broken kernel
  // fails as a kernel failure rather than after the body has already had effects.
  const conditionImage = condition.imageId;
  const kernel = await findSmalltalkKernel({images, imageId: conditionImage});
  if (!kernel) {
    throw new TypeError(
      `Symmetric Smalltalk ${primitive} primitive requires a Smalltalk kernel in ${conditionImage} to answer nil`,
    );
  }

  for (;;) {
    const verdict = canonicalizeValue(await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: condition,
      message: textValue('value'),
      arguments: [],
    }));
    // ADR 0051 decision 7: a canonical boolean, and nothing else. Accepting more would introduce a
    // second, looser notion of truth beside the polymorphism ADR 0045 established.
    if (verdict.kind !== VALUE_KIND.BOOLEAN) {
      throw new TypeError(
        `Symmetric Smalltalk ${primitive} condition answered a ${verdict.kind} Value; a Boolean is required`,
      );
    }
    if (verdict.value !== wanted) return kernel.nil;
    await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: body,
      message: textValue('value'),
      arguments: [],
    });
  }
}

export {
  blockEnsure,
  blockOnDo,
  blockWhile,
  conditionSignal,
  conditionTransferOut,
  nonLocalReturn,
  requireConditions,
};

