  SmalltalkDivideByZeroError,
  SmalltalkIntegerOperandError,
  integerOperation,
} from './smalltalk-primitives-integer.js';
import {
  blockEnsure,
  blockOnDo,
  blockWhile,
  conditionSignal,
  conditionTransferOut,
