import {isObjectRef, objectRef, textValue} from '../value/index.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {SMALLTALK_PRIMITIVE} from './smalltalk-primitive-support.js';
import {findSmalltalkKernel, readBehavior} from './smalltalk-kernel.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {ensureBlock, ensureCodeArtifact} from './smalltalk-class-builder.js';
import {SMALLTALK_KERNEL_PRIMITIVE_V1} from './smalltalk-primitives.js';
import {primitiveCodeContent} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// Class-hierarchy introspection: the durable subclass registry and the
// `subclasses`/`allSubclasses` protocol.
//
// A class's direct subclasses are ordinary durable image state, never hidden JS
// state and never a new field on the fixed Behavior shape (which would be a
// durable-schema migration touching every class). Each class has a registry
// object at a deterministic id whose indexed part holds direct-subclass refs.
// `defineClass` maintains it (see `maintainSubclassRegistries`); the
// `subclasses-of` primitive reads it into an image Array; the Smalltalk
// `subclasses`/`allSubclasses` methods compose over it with OrderedCollection.
//
// Owner: the Symmetric Smalltalk personality. No Value/generic-Object/backend
// change; the registry rides the ordinary object model.

const SUBCLASS_REGISTRY_SHAPE_ID = 'smalltalk/subclass-registry-shape/v1';
const SUBCLASSES_OF_BLOCK_ID = 'smalltalk/primitive/subclasses-of';
const SUBCLASSES_OF_CAPTURE = Object.freeze({id: SUBCLASSES_OF_BLOCK_ID, name: 'primitiveSubclassesOf'});

function subclassRegistryId(className) {
  return `smalltalk/subclasses/${className}`;
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function ensureRegistryShape(images, imageId) {
  const existing = await images.getShape(imageId, SUBCLASS_REGISTRY_SHAPE_ID);
  if (existing) return objectRef(imageId, existing.id);
  return objectRef(imageId, (await images.putShape(imageId, {
    id: SUBCLASS_REGISTRY_SHAPE_ID, slots: [], indexed: SHAPE_INDEXED.VALUES,
  })).id);
}

// The registry's shape is well-known and lazily ensured, but the registry record
// for a class is created on first append (or first explicit ensure), so a class
// nobody ever subclassed has no record at all — and absence reads as empty.
async function ensureSubclassRegistry({images, imageId, className}) {
  const shapeRef = await ensureRegistryShape(images, imageId);
  const id = subclassRegistryId(className);
  const existing = await images.getObject(imageId, id);
  if (existing) return {ref: objectRef(imageId, id), record: existing};
  const record = await images.putObject(imageId, {
    id, shape: shapeRef, behavior: null, slots: {}, indexed: [], metadata: {smalltalk: 'subclass-registry'},
  });
  return {ref: objectRef(imageId, id), record};
}

// Membership-guarded append: replaying `defineClass` never duplicates an entry.
async function appendSubclass({images, imageId, superclassName, subclassRef}) {
  const {record} = await ensureSubclassRegistry({images, imageId, className: superclassName});
  const current = Array.isArray(record.indexed) ? record.indexed : [];
  const present = current.some(
    (ref) => isObjectRef(ref) && ref.imageId === subclassRef.imageId && ref.objectId === subclassRef.objectId,
  );
  if (present) return;
  await images.putObject(imageId, {
    id: record.id,
    shape: record.shape,
    behavior: null,
    slots: record.slots ?? {},
    indexed: [...current, subclassRef],
    metadata: record.metadata ?? {smalltalk: 'subclass-registry'},
  }, {expectedVersion: record._version});
}

// `defineClass` calls this for every class it defines. It registers the CLASS
// object's superclass edge (never the metaclass's derived one) in the
// superclass's registry, and ensures this class's own empty registry. Lazy and
// tolerant: bootstrap classes are defined before the registry Shape exists, and
// absence reads as empty, so this converges on retry rather than failing the
// definition. The superclass edge is the one `defineClass` was given — `Object`
// for a default superclass, so ordinary classes register under `Object`.
async function maintainSubclassRegistries({images, imageId, className, classRef, superclassRef, nilRef}) {
  requiredText(className, 'class name');
  // Ensure this class's own (empty) registry first so every class is introspectable.
  await ensureSubclassRegistry({images, imageId, className});
  if (!isObjectRef(superclassRef) || (nilRef && superclassRef.objectId === nilRef.objectId)) return;
  // The root Object class has no superclass to register under; its superclass
  // edge is the kernel nil, handled above.
  const superclassName = (await readBehavior(images, superclassRef)).name;
  if (superclassName?.kind !== 'text' || superclassName.value.length === 0) return;
  await appendSubclass({images, imageId, superclassName: superclassName.value, subclassRef: classRef});
}

// The protocol methods, written in Smalltalk over OrderedCollection and the
// `subclasses-of` primitive. `subclasses` answers the direct set;
// `allSubclasses` walks it transitively (depth-first, order-insensitive by
// contract — membership is what callers may rely on).
const SUBCLASS_PROTOCOL_METHODS = Object.freeze([
  {
    selector: 'subclasses',
    source: `[ | arr coll |
      arr := primitiveSubclassesOf value: self.
      coll := OrderedCollection new.
      1 to: arr size do: [:i | coll add: (arr at: i)].
      ^ coll ]`,
  },
  {
    selector: 'allSubclasses',
    source: `[ | result work |
      result := OrderedCollection new.
      work := OrderedCollection new.
      self subclasses do: [:s | work add: s].
      [ work isEmpty ] whileFalse: [
        | current |
        current := work removeLast.
        result add: current.
        current subclasses do: [:s | work add: s].
      ].
      ^ result ]`,
  },
]);

async function installSmalltalkSubclassProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // The primitive Block, published on the same `smalltalk-kernel-primitive/v1`
  // seam as the other kernel primitives.
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${SUBCLASSES_OF_BLOCK_ID}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(SMALLTALK_PRIMITIVE.SUBCLASSES_OF)),
    metadata: {smalltalk: 'kernel-primitive', primitive: SMALLTALK_PRIMITIVE.SUBCLASSES_OF},
  });
  const primitiveBlock = await ensureBlock(images, imageId, {
    id: SUBCLASSES_OF_BLOCK_ID,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive: SMALLTALK_PRIMITIVE.SUBCLASSES_OF},
  });

  // The methods live on Class so every class understands them; an instance does
  // not (defence-in-depth behind the primitive's own receiver guard).
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.classClass,
    methods: SUBCLASS_PROTOCOL_METHODS.map(({selector, source}) => ({
      selector,
      source,
      captures: [{...SUBCLASSES_OF_CAPTURE, value: objectRef(imageId, primitiveBlock.id)}],
    })),
  });

  return Object.freeze({
    protocol: 'smalltalk-subclass-protocol/v1',
    subclassesOfPrimitive: objectRef(imageId, primitiveBlock.id),
    classClass: kernel.classClass,
  });
}

export {
  SUBCLASS_REGISTRY_SHAPE_ID,
  installSmalltalkSubclassProtocol,
  maintainSubclassRegistries,
  subclassRegistryId,
};

import {
  SYMBOL_CLASS_NAME,
  SYMBOL_SHAPE_ID,
  SYMBOL_SPELLING_SLOT,
} from './smalltalk-primitives-symbol.js';
import {
  SMALLTALK_PRIMITIVE,
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  primitiveCodeContent,
} from './smalltalk-primitive-support.js';
import {defineMethods, ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {objectRef, textValue} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// Symbol protocol installation: the Symbol class, its Shape, the interner primitive,
// and Object>>perform: / perform:with:.
//
// This is a primitive-backed protocol (Pattern B): primitive Blocks installed first,
// then methods that capture refs to them and send value:/value:value:.

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.SYMBOL_INTERN]: 'smalltalk/primitive/symbol-intern',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND]: 'smalltalk/primitive/perform-send',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH]: 'smalltalk/primitive/perform-send-with',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.SYMBOL_INTERN]: '$symbol',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND]: '$performSend',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH]: '$performSendWith',
});

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const codeId = `${id}:code`;
  await ensureCodeArtifact(images, imageId, {
    id: codeId,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    languageId: SYMMETRIC_SMALLTALK_ID,
    content: textValue(primitiveCodeContent(primitive)),
    dependencies: [],
    derivedFrom: [],
    metadata: {},
  });
  await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeId),
    environment: null,
    metadata: {},
  });
  return objectRef(imageId, id);
}

function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = {
    id: PRIMITIVE_BLOCK_ID[primitive],
    name: CAPTURE_NAME[primitive],
  };
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{id: capture.id, name: capture.name}],
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'binding', id: capture.id},
        message: textValue('value:'.repeat(args.length)),
        arguments: args,
      },
    },
    captures: [{id: capture.id, name: capture.name, value: objectRef(imageId, capture.id)}],
  };
}

async function installSmalltalkSymbolProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('images service is required');
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // 1. Install the Shape
  await ensureSmalltalkShape(images, imageId, {
    id: SYMBOL_SHAPE_ID,
    slots: [{id: SYMBOL_SPELLING_SLOT, name: 'spelling'}],
  });

  // 2. Install primitive Blocks
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.SYMBOL_INTERN});
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND});
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH});

  // 3. Create the Symbol class
  const {classRef: symbolClassRef} = await ensureNamedClass({
    images,
    imageId,
    name: SYMBOL_CLASS_NAME,
    superclassRef: kernel.objectClass,
    instanceShapeRef: objectRef(imageId, SYMBOL_SHAPE_ID),
  });

  // 4. Install Symbol>>asString — answers the spelling slot. Uses the class-scoped
  //    compiler so the instance variable read goes through the ordinary slot primitive.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: symbolClassRef,
    methods: [{selector: 'asString', source: '[ spelling ]'}],
  });

  // 5. Install Object>>perform: and Object>>perform:with: on the Object class
  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      capturedMethod({
        selector: 'perform:',
        primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND,
        parameters: ['aSymbol'],
        args: [{op: 'receiver'}, {op: 'argument', index: 0}],
        imageId,
      }),
      capturedMethod({
        selector: 'perform:with:',
        primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH,
        parameters: ['aSymbol', 'anObject'],
        args: [{op: 'receiver'}, {op: 'argument', index: 0}, {op: 'argument', index: 1}],
        imageId,
      }),
    ],
  });

  return Object.freeze({symbolClass: symbolClassRef});
}

export {
  installSmalltalkSymbolProtocol,
};

import {objectRef, textValue} from '../value/index.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {defineMethods} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// WS3 Text/ByteArray slice: the Smalltalk protocol over the byte-sequence
// primitive family (smalltalk-primitives-bytes.js).
//
//   Text       >> utf8Bytes        primitiveTextUtf8Bytes value: self
//   ByteArray  >> utf8Text         primitiveByteArrayUtf8Text value: self
//   ByteArray  >> size             primitiveByteArraySize value: self
//   ByteArray  >> at:              primitiveByteArrayAt value: self value: index
//   ByteArray class >> fromArray:  ^ primitiveArrayToByteArray value: anArray
//
// `Text` is a native text Value and `ByteArray` a native bytes Value — both
// dispatch through their kernel classes, so the methods land on those classes
// directly (Pattern B, like Symbol). `fromArray:` is the explicit, narrowly
// named conversion from an integer Array buffer; it validates every element.
//
// ByteArray stays immutable for this slice: no `at:put:`, and no widening of
// the ADR 0047 indexed primitives to bytes Values.

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES]: 'smalltalk/primitive/text-utf8-bytes',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT]: 'smalltalk/primitive/bytearray-utf8-text',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE]: 'smalltalk/primitive/bytearray-size',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_AT]: 'smalltalk/primitive/bytearray-at',
  [SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY]: 'smalltalk/primitive/array-to-bytearray',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES]: '$textUtf8Bytes',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT]: '$byteArrayUtf8Text',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE]: '$byteArraySize',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_AT]: '$byteArrayAt',
  [SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY]: '$arrayToByteArray',
});

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const codeId = `${id}:code`;
  await ensureCodeArtifact(images, imageId, {
    id: codeId,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    languageId: SYMMETRIC_SMALLTALK_ID,
    content: textValue(primitiveCodeContent(primitive)),
    dependencies: [],
    derivedFrom: [],
    metadata: {},
  });
  await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeId),
    environment: null,
    metadata: {},
  });
  return objectRef(imageId, id);
}

function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = {id: PRIMITIVE_BLOCK_ID[primitive], name: CAPTURE_NAME[primitive]};
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{id: capture.id, name: capture.name}],
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'binding', id: capture.id},
        message: textValue('value:'.repeat(args.length)),
        arguments: args,
      },
    },
    captures: [{id: capture.id, name: capture.name, value: objectRef(imageId, capture.id)}],
  };
}

const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

async function installSmalltalkTextByteArrayProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('images service is required');
  }
  if (lane !== 'neutral' && lane !== 'wasm') throw new TypeError(`unknown method lane: ${lane}`);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  for (const primitive of [
    SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES,
    SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT,
    SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE,
    SMALLTALK_PRIMITIVE.BYTEARRAY_AT,
    SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY,
  ]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  // Text >> utf8Bytes
  await defineMethods({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [capturedMethod({
      selector: 'utf8Bytes', primitive: SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES, args: [receiver()], imageId,
    })],
  });

  // Text >> asString answers the receiver: a Text's string form is itself. Standard,
  // general protocol (a String answers `asString` with itself in every dialect); it
  // lets a uniform `aString asString` conversion reach both Text and Symbol.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [{selector: 'asString', source: '[ ^ self ]'}],
  });

  // ByteArray >> utf8Text / size / at:
  await defineMethods({
    images, compilation, imageId, lane, classRef: kernel.byteArrayClass,
    methods: [
      capturedMethod({
        selector: 'utf8Text', primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT, args: [receiver()], imageId,
      }),
      capturedMethod({
        selector: 'size', primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE, args: [receiver()], imageId,
      }),
      capturedMethod({
        selector: 'at:',
        primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_AT,
        parameters: ['index'],
        args: [receiver(), argument(0)],
        imageId,
      }),
    ],
  });

  // ByteArray class >> fromArray: — the explicit, narrowly named conversion from
  // an integer Array buffer; the primitive validates every element 0..255.
  await defineMethods({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/metaclass/ByteArray'),
    methods: [capturedMethod({
      selector: 'fromArray:',
      primitive: SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY,
      parameters: ['anArray'],
      args: [argument(0)],
      imageId,
    })],
  });

  return Object.freeze({
    protocol: 'smalltalk-text-bytearray/v1',
    textClass: kernel.textClass,
    byteArrayClass: kernel.byteArrayClass,
  });
}

export {
  installSmalltalkTextByteArrayProtocol,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {ensureBlock, ensureCodeArtifact, ensureLexicalEnvironment} from '../graph/ensure-records.js';
import {ARRAY_BINDING_ID, NIL_BINDING_ID, SYMBOL_BINDING_ID} from './symmetric-smalltalk-semantic.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {globalDeclarations} from './smalltalk-globals.js';
import {LAGRANGE_CODE_V0} from '../code/lagrange-code-v0.js';
import {LAGRANGE_CODE_V1} from '../code/lagrange-code-v1.js';
import {CompilationService, createDefaultCodeCompilerRegistry} from '../compilation/index.js';
import {NEUTRAL_EXPRESSION_V0} from '../execution/neutral-expression-v0.js';
import {NEUTRAL_EXPRESSION_V1} from '../execution/neutral-expression-v1.js';
import {objectRef, textValue} from '../value/index.js';
import {
  executableTargetFor,
  installNestedPrototypes,
} from './smalltalk-nested-blocks.js';
import {compileSymmetricSmalltalkSemanticBlock} from './symmetric-smalltalk-semantic.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

const SYMMETRIC_SMALLTALK_SOURCE_V0 = 'symmetric-smalltalk/source-v0';
const SYMMETRIC_SMALLTALK_SYNTAX_V0 = 'symmetric-smalltalk/syntax-v0';

function compileSymmetricSmalltalkBlock(source, options = {}) {
  // `nil` needs nothing here: the semantic compiler owns that intrinsic and offers it to every
  // compilation (ADR 0056), so this wrapper cannot get it wrong or out of step.
  //
  // Globals are different: they are image state, so an image-scoped caller reads them and hands the
  // resolved declarations down. This function stays synchronous and storage-free (ADR 0057), and a
  // caller with no declarations gets exactly today's behaviour.
  const {syntax, program, representation, globalBindingIdsUsed} =
    compileSymmetricSmalltalkSemanticBlock(source, options);
  return Object.freeze({syntax, semanticProgram: program, program, representation, globalBindingIdsUsed});
}

// Deterministic per Block, so an identical retry converges like every other write here.
//
// The identity is deliberately conditional. A Block that uses only `nil` keeps ADR 0056's existing
// `${id}:nil-environment`, because renaming it would change the durable definition of every
// pre-0057 nil Block and stop reinstallation converging. A Block that uses globals gets the broader
// identity instead.
async function ensureCompilerSuppliedEnvironment({
  images, imageId, id, parent, program, globalBindingIdsUsed,
}) {
  const captures = program.captures ?? [];
  const captureIds = new Set(captures.map(({id: captureId}) => captureId));
  const usesNil = captureIds.has(NIL_BINDING_ID);
  const usesSymbol = captureIds.has(SYMBOL_BINDING_ID);
  const usesArray = captureIds.has(ARRAY_BINDING_ID);
  // Exactly the globals compilation resolved — never every published id that happens to appear
  // among the captures. An explicit caller capture may legitimately use an id that is also a
  // published binding, and substituting the binding object for the caller's value would collapse
  // two meanings onto one identity.
  //
  // The *name* comes from the semantic program's capture descriptor, not from the current namespace.
  // Namespace aliases are compile-time lookup affordances; once a name resolved to identity X, adding
  // another alias for X must not change the durable definition of an already-compiled Block on retry.
  const resolved = new Set(globalBindingIdsUsed ?? []);
  const globalCaptures = [];
  for (const bindingId of resolved) {
    const capture = captures.find(({id}) => id === bindingId);
    if (!capture) {
      throw new TypeError(`global binding ${bindingId} was resolved but is absent from the semantic capture list`);
    }
    globalCaptures.push(capture);
  }
  if (!usesNil && !usesSymbol && !usesArray && globalCaptures.length === 0) return parent;

  const bindings = {};
  if (usesNil) {
    const kernel = await findSmalltalkKernel({images, imageId});
    if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel; nil has no value there`);
    bindings[NIL_BINDING_ID] = {name: 'nil', value: kernel.nil};
  }
  if (usesSymbol) {
    bindings[SYMBOL_BINDING_ID] = {name: '$symbol', value: objectRef(imageId, 'smalltalk/primitive/symbol-intern')};
  }
  if (usesArray) {
    // The empty literal Array `#()` lowers to `new: 0` against this image's Array class. The
    // compiler carries only the intrinsic id; the image-local class ref lives here, in the
    // environment — never in the semantic artifact.
    bindings[ARRAY_BINDING_ID] = {name: '$array', value: objectRef(imageId, 'smalltalk/class/Array')};
  }
  for (const {id: bindingId, name} of globalCaptures) {
    // The image-local ref lives here, in the environment — never in the semantic artifact.
    bindings[bindingId] = {name, value: objectRef(imageId, bindingId)};
  }

  const environmentId = globalCaptures.length === 0 && !usesSymbol && !usesArray
    ? `${id}:nil-environment`
    : `${id}:compiler-environment`;
  const record = await ensureLexicalEnvironment(images, imageId, {
    id: environmentId,
    ...(parent ? {parent} : {}),
    bindings,
  });
  return objectRef(imageId, record.id);
}

function resolveCompilation(images, compilation) {
  if (compilation) {
    if (typeof compilation.compileArtifact !== 'function') throw new TypeError('compilation service must implement compileArtifact');
    return compilation;
  }
  return new CompilationService({images, compilers: createDefaultCodeCompilerRegistry()});
}

async function installSymmetricSmalltalkBlock({
  images,
  compilation = null,
  imageId,
  source,
  id = randomUUID(),
  captures = {},
  environment = null,
  metadata = {},
  // ADR 0061: which namespace this Block compiles in. Defaulting to the root reproduces ADR 0057's
  // behavior for every existing caller; a nested namespace's chain is walked to resolve globals.
  namespaceId,
} = {}) {
  if (!images || typeof images.putCodeArtifact !== 'function' || typeof images.putBlock !== 'function') {
    throw new TypeError('images service with code-artifact and block persistence is required');
  }
  const compiler = resolveCompilation(images, compilation);
  // The image-scoped seam: the namespace is read here, asynchronously, and passed into the
  // synchronous compiler as a transient name -> binding-id map. The chain walk happens inside
  // globalDeclarations; the compiler itself still only sees a flat map.
  const globals = await globalDeclarations({images, imageId, namespaceId});
  const {syntax, semanticProgram, representation, globalBindingIdsUsed} =
    compileSymmetricSmalltalkBlock(source, {captures, globals});

  // Ensure-exact-or-create, like every other deterministic-id write in this repository. These were
  // direct `put`s, which made an *identical* retry fail on the first record — so a partially
  // completed installation could not be completed by repeating it. Pre-existing and unrelated to
  // any one feature; converted here because ADR 0056 is the first thing to depend on it.
  const sourceArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:source`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SYMMETRIC_SMALLTALK_SOURCE_V0,
    content: textValue(source),
    metadata,
  });
  const syntaxArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:syntax`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SYMMETRIC_SMALLTALK_SYNTAX_V0,
    content: textValue(JSON.stringify(syntax)),
    derivedFrom: [objectRef(imageId, sourceArtifact.id)],
  });
  const semanticArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:semantic`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation,
    content: textValue(JSON.stringify(semanticProgram)),
    derivedFrom: [objectRef(imageId, syntaxArtifact.id)],
  });

  const blockPrototypes = await installNestedPrototypes({
    images,
    compilation: compiler,
    imageId,
    rootId: id,
    parentSemanticRef: objectRef(imageId, semanticArtifact.id),
    program: semanticProgram,
    representation,
  });
  const codeArtifact = await compiler.compileArtifact(
    objectRef(imageId, semanticArtifact.id),
    {
      id: `${id}:code`,
      targetRepresentation: executableTargetFor(representation),
      options: {blockPrototypes},
    },
  );
  // ADR 0056 decision 2a, generalised by ADR 0057. Only a program that actually binds something the
  // compiler supplies needs an environment, so a Block using neither `nil` nor a global keeps
  // today's path exactly and writes no extra record.
  //
  // When one is needed it *parents* the caller's rather than copying its bindings: the caller's
  // environment is a record with its own lifecycle, and a copy would be a second answer to the same
  // question that could later drift from it. The chain walk is already the composition mechanism.
  //
  // One environment, not two wrappers, when a program uses both.
  const blockEnvironment = await ensureCompilerSuppliedEnvironment({
    images, imageId, id, parent: environment, program: semanticProgram, globalBindingIdsUsed,
  });

  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeArtifact.id),
    environment: blockEnvironment,
    metadata,
  });
  return Object.freeze({
    syntax,
    semanticProgram,
    representation,
    // Transient provenance: which global bindings this compilation actually resolved. It is not
    // written to any artifact — lagrange-code stays a language-neutral representation — but callers
    // that bind captures need it, because a capture id alone never says why the capture exists.
    globalBindingIdsUsed,
    sourceArtifact,
    syntaxArtifact,
    semanticArtifact,
    codeArtifact,
    blockPrototypes,
    block,
  });
}

async function evaluateSymmetricSmalltalkBlock({runtime, arguments: args = [], ...installOptions} = {}) {
  if (!runtime?.images || !runtime?.invocations || !runtime?.executor) {
    throw new TypeError('runtime with images, invocations and executor is required');
  }
  const installed = await installSymmetricSmalltalkBlock({
    images: runtime.images,
    compilation: runtime.compilation ?? null,
    ...installOptions,
  });
  const activation = await runtime.invocations.invokeBlock(
    objectRef(installed.block.imageId, installed.block.id),
    args,
  );
  return await runtime.executor.execute(activation);
}

export {
  SYMMETRIC_SMALLTALK_SOURCE_V0,
  SYMMETRIC_SMALLTALK_SYNTAX_V0,
  compileSymmetricSmalltalkBlock,
  evaluateSymmetricSmalltalkBlock,
  installSymmetricSmalltalkBlock,
};

import {VALUE_KIND, isObjectRef} from '../value/index.js';
import {findSmalltalkKernel, isBehaviorObject} from './smalltalk-kernel.js';
import {
  MethodDictionaryValidationCache,
  SmalltalkDanglingEdgeError,
  behaviorRefFor,
  lookupSelector,
} from './smalltalk-lookup.js';
import {findSmalltalkBlockProtocol} from './smalltalk-block-protocol.js';
import {findSmalltalkBlockUnwindProtocol} from './smalltalk-conditions.js';
import {SMALLTALK_KERNEL_PRIMITIVE_V1} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['getObject', 'getShape', 'getBlock', 'getCodeArtifact']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

// The only two selectors the dispatcher recognizes for a Block beyond `value`. Mapping selector to
// protocol slot name keeps the dispatcher's knowledge to "which slot", never "which object".
const LOOP_SELECTOR = Object.freeze({
  'whileTrue:': 'whileTrue',
  'whileFalse:': 'whileFalse',
});

// ADR 0054. A separate protocol object from the loop one, so the dispatcher still knows only slot
// names and never an object id, and an image with loops but no unwind protocol stays coherent.
const UNWIND_SELECTOR = Object.freeze({
  'on:do:': {slot: 'onDo', arity: 2},
  'ensure:': {slot: 'ensure', arity: 1},
  'ifCurtailed:': {slot: 'ifCurtailed', arity: 1},
});

function blockValueSelector(argumentCount) {
  if (!Number.isInteger(argumentCount) || argumentCount < 0) throw new TypeError('argument count must be a non-negative integer');
  return argumentCount === 0 ? 'value' : Array.from({length: argumentCount}, () => 'value:').join('');
}

// The pre-ADR-0044 convention, unchanged: a behavior object whose *shape slot names* are selectors.
// Lifted here rather than reimplemented, so an already-stored object keeps answering exactly as it
// did before any kernel existed.
async function legacyLookup(images, behavior, selector) {
  const shape = await images.getShape(behavior.shape.imageId, behavior.shape.objectId);
  if (!shape) {
    throw new TypeError(`Symmetric Smalltalk behavior shape not found: ${behavior.shape.imageId}/${behavior.shape.objectId}`);
  }
  // Deliberately the pre-0044 TypeError and wording. Decision 10 preserves what an already-stored
  // object *means*, and a failure is part of that meaning: a legacy receiver that did not
  // understand a selector must still fail exactly as it did before any kernel existed.
  const methodSlot = shape.slots.find(({name}) => name === selector);
  if (!methodSlot) throw new TypeError(`Symmetric Smalltalk message not understood: ${selector}`);
  const blockRef = behavior.slots[methodSlot.id];
  if (!isObjectRef(blockRef)) {
    throw new TypeError(`Symmetric Smalltalk method slot ${methodSlot.id} must contain a Block ref`);
  }
  const block = await images.getBlock(blockRef.imageId, blockRef.objectId);
  if (!block) {
    throw new TypeError(`Symmetric Smalltalk method Block not found: ${blockRef.imageId}/${blockRef.objectId}`);
  }
  return blockRef;
}

// ADR 0045 decision 7: the key is present only when the language actually nominates a different
// receiver, so an ordinary send produces exactly the `{block}` resolution it always has.
function resolution(block, effectiveReceiver, frame = null) {
  return Object.freeze({
    ...(effectiveReceiver ? {effectiveReceiver} : {}),
    ...(frame ? {frame} : {}),
    block,
  });
}

function createSymmetricSmalltalkDispatcher() {
  // Per dispatcher, so it lives and dies with the runtime that owns it rather than leaking between
  // images or across tests. Transient runtime state: never durable, never a Value, and correct to
  // drop at any moment (ADR 0049 decision 5a).
  const validationCache = new MethodDictionaryValidationCache();
  return Object.freeze({
    languageId: SYMMETRIC_SMALLTALK_ID,

    async resolveMessage(request, context) {
      const images = assertImages(context?.images);
      if (request.languageId !== SYMMETRIC_SMALLTALK_ID) {
        throw new TypeError(`unexpected language id for Symmetric Smalltalk dispatcher: ${request.languageId}`);
      }
      if (request.message?.kind !== VALUE_KIND.TEXT) {
        throw new TypeError('Symmetric Smalltalk v0 messages must be text Values');
      }
      const selector = request.message.value;

      // ADR 0044 decision 11: a Block answers value/value: without a class. Checked first, as it
      // always has been.
      if (isObjectRef(request.receiver)) {
        const blockReceiver = await images.getBlock(request.receiver.imageId, request.receiver.objectId);
        if (blockReceiver) {
          // ADR 0051: two more operations on the classless Block personality. The protocol is
          // looked up in the *condition* Block's image — which is the receiver, and therefore
          // already the dispatch image a nested send would compute — so the image that owns the
          // send owns the loop, and the answered nil is that image's.
          //
          // The dispatcher learns a protocol tag and two slot meanings, never an object id
          // (ADR 0044 decision 9). An image with no protocol falls through to the ordinary
          // does-not-understand below, which is the coherent answer for an image whose Blocks
          // simply do not loop; a corrupt one throws out of `findSmalltalkBlockProtocol` rather
          // than being degraded to that.
          const loopSlot = LOOP_SELECTOR[selector];
          if (loopSlot && request.arguments.length === 1) {
            const protocol = await findSmalltalkBlockProtocol({images, imageId: request.receiver.imageId});
            // Decision 9: the loop primitive is the language's own host operation, so it inherits
            // the caller's frame. The condition and body do not — they are reached by ordinary
            // `value` sends, which inherit nothing.
            if (protocol) return Object.freeze({block: protocol[loopSlot], inheritsFrame: true});
          }
          const unwind = UNWIND_SELECTOR[selector];
          if (unwind && request.arguments.length === unwind.arity) {
            const protocol = await findSmalltalkBlockUnwindProtocol({images, imageId: request.receiver.imageId});
            // Same rule as the loop primitives: the unwind primitive is the language's own host
            // operation and inherits the caller's frame, while the protected, handler and cleanup
            // Blocks are invoked in their own right and inherit nothing.
            if (protocol) return Object.freeze({block: protocol[unwind.slot], inheritsFrame: true});
          }
          const expected = blockValueSelector(request.arguments.length);
          if (selector !== expected) throw new TypeError(`Symmetric Smalltalk Block does not understand: ${selector}`);
          // ADR 0050 decision 5a. A kernel-primitive Block is how a method reaches a host operation,
          // so it inherits the invoking method's frame — that is the only way the slot primitives
          // can see whose `self` they are acting on. Every *other* Block send inherits nothing: a
          // method must not lend its identity to a Block it merely happens to invoke.
          const code = await images.getCodeArtifact(blockReceiver.code.imageId, blockReceiver.code.objectId);
          return code?.representation === SMALLTALK_KERNEL_PRIMITIVE_V1
            ? Object.freeze({block: request.receiver, inheritsFrame: true})
            : Object.freeze({block: request.receiver});
        }
      }

      // Decision 5a: an immediate Value has no image of its own, so the dispatch image says which
      // kernel's Integer, Text and so on apply.
      const dispatchImage = context?.dispatchImage
        ?? (isObjectRef(request.receiver) ? request.receiver.imageId : null);
      if (!isObjectRef(request.receiver) && dispatchImage === null) {
        throw new TypeError(
          'Symmetric Smalltalk needs a dispatch image to send to an immediate Value; '
          + 'a top-level send must supply one',
        );
      }

      // ADR 0045 decision 2: for a boolean receiver this answers the dispatch image's `true`/`false`
      // singleton, which then behaves exactly like an ordinary object receiver.
      const {behavior, effectiveReceiver} = await behaviorRefFor({
        images,
        receiver: request.receiver,
        dispatchImage,
      });
      // What the method actually runs against, and therefore what every failure below should name.
      // Describing the original boolean here would report `undefined/undefined` for a bridged send
      // and, worse, would hide which singleton failed to understand the selector.
      const activeReceiver = effectiveReceiver ?? request.receiver;
      const receiverDescription = isObjectRef(activeReceiver)
        ? `${activeReceiver.imageId}/${activeReceiver.objectId}`
        : `a ${activeReceiver.kind} Value`;
      if (!behavior) {
        throw new TypeError(
          isObjectRef(activeReceiver)
            ? `Symmetric Smalltalk receiver has no behavior: ${receiverDescription}`
            : `Symmetric Smalltalk cannot dispatch a ${activeReceiver.kind} Value`,
        );
      }

      const behaviorRecord = await images.getObject(behavior.imageId, behavior.objectId);
      if (!behaviorRecord) {
        throw new TypeError(`Symmetric Smalltalk behavior not found: ${behavior.imageId}/${behavior.objectId}`);
      }

      // ADR 0044 decision 10. A behavior record means what its own shape says it means, so
      // installing a kernel reinterprets nothing that already exists.
      if (!isBehaviorObject(behaviorRecord)) {
        return resolution(await legacyLookup(images, behaviorRecord, selector), effectiveReceiver);
      }

      const kernel = await findSmalltalkKernel({images, imageId: behavior.imageId});
      if (!kernel) {
        throw new TypeError(
          `image ${behavior.imageId} holds a fixed-shape Behavior but no Smalltalk kernel to terminate lookup`,
        );
      }
      const {method: blockRef, definingBehavior} = await lookupSelector({
        images,
        behaviorRef: behavior,
        selector,
        nilRef: kernel.nil,
        receiverDescription,
        validationCache,
      });
      // A selector that resolved to a Block ref which does not load is incomplete graph state, not
      // a message the receiver failed to understand.
      const method = await images.getBlock(blockRef.imageId, blockRef.objectId);
      if (!method) throw new SmalltalkDanglingEdgeError('method', behavior, blockRef);
      // ADR 0050 decision 5b: the trusted facts of this dispatch travel in the resolution, and the
      // invocation layer turns them into a transient envelope. They never reach the activation.
      return resolution(blockRef, effectiveReceiver, {definingBehavior, self: activeReceiver});
    },
  });
}

export {blockValueSelector, createSymmetricSmalltalkDispatcher};

import {
  SymmetricSmalltalkSyntaxError,
  tokenizeSymmetricSmalltalk,
  isReservedWord,
  isNegativeIntegerLiteralAt,
} from './symmetric-smalltalk-tokenizer.js';

// One rule, one message shape, for every site that would otherwise decide independently.
function assertNotReserved(token, action) {
  if (isReservedWord(token.value)) {
    throw new SymmetricSmalltalkSyntaxError(
      `cannot ${action} ${token.value}: it is a reserved word`, token.start,
    );
  }
}

function node(kind, fields = {}) {
  return Object.freeze({kind, ...fields});
}

class Parser {
  constructor(source) {
    this.source = source;
    this.tokens = tokenizeSymmetricSmalltalk(source);
    this.index = 0;
  }

  current() {
    return this.tokens[this.index];
  }

  advance() {
    const token = this.current();
    if (token.type !== 'eof') this.index += 1;
    return token;
  }

  match(type) {
    if (this.current().type !== type) return null;
    return this.advance();
  }

  expect(type, message = `expected ${type}`) {
    const token = this.current();
    if (token.type !== type) throw new SymmetricSmalltalkSyntaxError(message, token.start);
    return this.advance();
  }

  peek(offset = 1) {
    return this.tokens[Math.min(this.index + offset, this.tokens.length - 1)];
  }

  parseSource() {
    const body = this.parseBody('eof');
    this.expect('eof', 'unexpected trailing input');
    return body;
  }

  // Assignment binds loosest and is right-associative, so `a := b := 1` assigns both and
  // `x := a foo: b` assigns the whole message result.
  parseExpression() {
    if (this.current().type === 'identifier' && this.peek().type === 'assign') {
      const target = this.advance();
      assertNotReserved(target, 'assign to');
      this.advance();
      return node('assign', {name: target.value, value: this.parseExpression()});
    }
    const expression = this.parseKeywordMessage();
    return this.parseCascadesAfter(expression);
  }

  // A cascade binds tighter than assignment: `x := self foo; bar` cascades on the *value*, so the
  // whole thing is the assigned expression, and `x` receives `self foo` — the first message's
  // answer, as Smalltalk defines a cascade's value.
  //
  // The cascaded receiver is the receiver of the first message, not the first message's answer:
  // `OrderedCollection new add: 1; add: 2` sends both `add:` to the *collection*, exactly as `;`
  // means in Smalltalk. So the cascade node keeps the receiver and each message's selector and
  // arguments, and the compiler decides how the receiver is evaluated once.
  parseCascadesAfter(expression) {
    if (expression.kind !== 'send' || this.current().type !== ';') return expression;
    const first = {selector: expression.selector, arguments: expression.arguments};
    const messages = [first];
    while (this.match(';')) {
      if (this.current().type === 'identifier') {
        messages.push({selector: this.advance().value, arguments: Object.freeze([])});
        continue;
      }
      if (this.current().type === 'binary') {
        const selector = this.advance().value;
        messages.push({selector, arguments: Object.freeze([this.parseUnaryMessage()])});
        continue;
      }
      if (this.current().type === 'keyword') {
        let selector = '';
        const argumentsList = [];
        while (this.current().type === 'keyword') {
          selector += this.advance().value;
          argumentsList.push(this.parseBinaryMessage());
        }
        messages.push({selector, arguments: Object.freeze(argumentsList)});
        continue;
      }
      throw new SymmetricSmalltalkSyntaxError('expected a message after ;', this.current().start);
    }
    return node('cascade', {receiver: expression.receiver, messages: Object.freeze(messages)});
  }

  // `| a b |` declarations followed by `.`-separated statements. A single statement with no
  // temporaries returns the bare expression, so programs that need none compile to exactly the
  // artifact they compile to today.
  parseBody(terminator) {
    const temporaries = this.parseTemporaries();
    const statements = [];
    for (;;) {
      if (this.current().type === terminator) break;
      // ADR 0055. A return is a *statement*, not an expression: `^ a foo` returns the whole send,
      // and `x := ^ 1` is not a thing. Parsing it here rather than in `parseExpression` is what
      // makes that true by construction.
      if (this.current().type === 'caret') {
        const caret = this.advance();
        statements.push(node('return', {value: this.parseExpression(), start: caret.start}));
      } else {
        statements.push(this.parseExpression());
      }
      // Statements after a return still *parse*: they are unreachable, not ill-formed, and the ADR
      // requires proving that they do not run rather than that they cannot be written.
      if (!this.match('.')) break;
    }
    if (statements.length === 0) {
      throw new SymmetricSmalltalkSyntaxError('expected at least one statement', this.current().start);
    }
    if (temporaries.length === 0 && statements.length === 1) return statements[0];
    return node('sequence', {
      temporaries: Object.freeze(temporaries),
      statements: Object.freeze(statements),
    });
  }

  parseTemporaries() {
    if (this.current().type !== '|') return [];
    this.advance();
    const names = [];
    while (this.current().type === 'identifier') {
      const token = this.advance();
      assertNotReserved(token, 'declare a temporary named');
      if (names.includes(token.value)) {
        throw new SymmetricSmalltalkSyntaxError(`duplicate temporary ${token.value}`, token.start);
      }
      names.push(token.value);
    }
    this.expect('|', 'expected | after temporary declarations');
    return names;
  }

  parseKeywordMessage() {
    let receiver = this.parseBinaryMessage();
    if (this.current().type !== 'keyword') return receiver;

    let selector = '';
    const argumentsList = [];
    while (this.current().type === 'keyword') {
      selector += this.advance().value;
      argumentsList.push(this.parseBinaryMessage());
    }
    receiver = node('send', {receiver, selector, arguments: Object.freeze(argumentsList)});
    return receiver;
  }

  parseBinaryMessage() {
    let receiver = this.parseUnaryMessage();
    while (this.current().type === 'binary') {
      const selector = this.advance().value;
      const argument = this.parseUnaryMessage();
      receiver = node('send', {
        receiver,
        selector,
        arguments: Object.freeze([argument]),
      });
    }
    return receiver;
  }

  parseUnaryMessage() {
    let receiver = this.parsePrimary();
    while (this.current().type === 'identifier') {
      const selector = this.advance().value;
      receiver = node('send', {
        receiver,
        selector,
        arguments: Object.freeze([]),
      });
    }
    return receiver;
  }

  parsePrimary() {
    const token = this.current();
    // Operand position only: a leading `-` here is a sign, never the binary
    // selector `parseBinaryMessage` consumes after a receiver. `5-3` and `a-3`
    // are unaffected because their `-` is read in binary-message position.
    if (isNegativeIntegerLiteralAt(this.tokens, this.index)) {
      this.advance(); // consume '-'
      const digits = this.advance(); // consume the integer
      return node('integer', {value: `-${digits.value}`});
    }
    if (token.type === 'integer') {
      this.advance();
      return node('integer', {value: token.value});
    }
    if (token.type === 'string') {
      this.advance();
      return node('string', {value: token.value});
    }
    if (token.type === 'symbol') {
      this.advance();
      return node('symbol', {value: token.value});
    }
    if (token.type === 'identifier') {
      this.advance();
      // The reserved words read as identifiers and are not names: each becomes its own syntax
      // node, so no later stage can mistake one for something bindable.
      if (token.value === 'self') return node('self');
      if (token.value === 'true') return node('true');
      if (token.value === 'false') return node('false');
      if (token.value === 'nil') return node('nil');
      return node('name', {name: token.value});
    }
    if (this.match('(')) {
      const expression = this.parseExpression();
      this.expect(')', 'expected )');
      return expression;
    }
    // Literal Array `#( ... )` (WS3). The authentic upstream MessagePack RED demands only the
    // empty form `#()`; element forms are a separate general facility, so a non-empty literal is
    // rejected deterministically here rather than half-parsed.
    if (this.match('arrayOpen')) {
      if (this.current().type !== ')') {
        throw new SymmetricSmalltalkSyntaxError(
          'literal Array element syntax is not supported; only the empty literal #() is', this.current().start,
        );
      }
      this.expect(')', 'expected ) to close a literal Array');
      return node('arrayLiteral', {elements: Object.freeze([])});
    }
    if (this.match('[')) return this.parseBlockAfterOpen(token.start);
    throw new SymmetricSmalltalkSyntaxError('expected expression', token.start);
  }

  parseBlockAfterOpen(start) {
    const parameters = [];
    while (this.match(':')) {
      const nameToken = this.expect('identifier', 'expected block parameter name');
      assertNotReserved(nameToken, 'declare a block parameter named');
      if (parameters.includes(nameToken.value)) {
        throw new SymmetricSmalltalkSyntaxError(`duplicate block parameter ${nameToken.value}`, nameToken.start);
      }
      parameters.push(nameToken.value);
    }
    if (parameters.length > 0) this.expect('|', 'expected | after block parameters');
    // WS3 (general language widening): an empty block `[]` is Standard Smalltalk
    // and answers nil when evaluated. Upstream dispatch uses it as the "no value"
    // idiom (`at: key ifAbsent: []`). This is block-level only: a program still
    // requires at least one statement.
    const body = this.current().type === ']' ? node('nil') : this.parseBody(']');
    const close = this.expect(']', 'expected ]');
    return node('block', {
      parameters: Object.freeze(parameters),
      body,
      start,
      end: close.end,
    });
  }
}

function parseSymmetricSmalltalk(source) {
  return new Parser(source).parseSource();
}

function parseSymmetricSmalltalkBlock(source) {
  const syntax = parseSymmetricSmalltalk(source);
  if (syntax.kind !== 'block') {
    throw new SymmetricSmalltalkSyntaxError('expected a block as the compilation unit', 0);
  }
  return syntax;
}

export {
  parseSymmetricSmalltalk,
  parseSymmetricSmalltalkBlock,
};

import {booleanValue, integerValue, textValue} from '../value/index.js';
import {LAGRANGE_CODE_V0} from '../code/lagrange-code-v0.js';
import {LAGRANGE_CODE_V1} from '../code/lagrange-code-v1.js';
import {parseSymmetricSmalltalkBlock} from './symmetric-smalltalk-parser.js';
import {isReservedWord} from './symmetric-smalltalk-tokenizer.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

function normalizeRootCaptures(captures) {
  if (!captures || typeof captures !== 'object' || Array.isArray(captures)) {
    throw new TypeError('captures must be an object mapping source name to stable binding id');
  }
  const result = new Map();
  const ids = new Set();
  for (const [name, id] of Object.entries(captures)) {
    if (!name) throw new TypeError('capture name must not be empty');
    // The fourth site of ADR 0056 decision 3, and the one the parser cannot reach: captures are
    // supplied programmatically rather than written in source.
    if (isReservedWord(name)) throw new TypeError(`capture name ${name} is a reserved word`);
    // The compiler's own intrinsic, reserved in both directions. Reserving only the name would let
    // a caller bind the *id* under another name and shadow `nil`'s meaning from outside the
    // compiler — the same reason `$nonLocalReturn` and the slot primitives reserve both.
    if (name === NIL_CAPTURE) throw new TypeError(`capture name ${NIL_CAPTURE} is reserved for the nil intrinsic`);
    if (name === SYMBOL_CAPTURE) throw new TypeError(`capture name ${SYMBOL_CAPTURE} is reserved for the symbol intrinsic`);
    // The compiler owns this whole key namespace. Reserving only the ids it happens to use would
    // let a caller supply an internal-looking name and slip past the global collision check, which
    // distinguishes its own captures by exactly this prefix.
    if (name.startsWith(GLOBAL_CAPTURE_PREFIX)) {
      throw new TypeError(`capture name ${name} is reserved: ${GLOBAL_CAPTURE_PREFIX} belongs to the compiler`);
    }
    if (typeof id !== 'string' || id.length === 0) throw new TypeError(`capture binding id for ${name} must be non-empty text`);
    if (id === NIL_BINDING_ID) throw new TypeError(`capture binding id ${NIL_BINDING_ID} is reserved for the nil intrinsic`);
    if (id === SYMBOL_BINDING_ID) throw new TypeError(`capture binding id ${SYMBOL_BINDING_ID} is reserved for the symbol intrinsic`);
    if (ids.has(id)) throw new TypeError(`duplicate capture binding id: ${id}`);
    ids.add(id);
    result.set(name, id);
  }
  return result;
}

// Which semantic representation this compilation unit needs, decided from what the program actually
// does rather than from what the parser happened to emit. A source that needs none of ADR 0043's
// semantics must still compile to exactly its lagrange-code/v0 artifact, so this asks about
// meaning: more than one statement, a declared temporary, or an assignment.
//
// A cell-mode capture is not tested for separately: capturing a mutable cell requires a temporary
// to have been declared, so temporaries already subsume it.
function needsMutableLexicalState(syntax) {
  if (!syntax || typeof syntax !== 'object') return false;
  switch (syntax.kind) {
    case 'assign':
      return true;
    case 'sequence':
      if (syntax.temporaries.length > 0 || syntax.statements.length > 1) return true;
      return syntax.statements.some((statement) => needsMutableLexicalState(statement));
    case 'block':
      return needsMutableLexicalState(syntax.body);
    // ADR 0055. A return wraps an ordinary expression, so v1 features hidden under one — an
    // assignment, a multi-statement Block — must still be seen. Omitting this case classifies
    // `^ [ | t | t := 1. t ]` as v0 and the artifact is then rejected against the closed v0 grammar.
    case 'return':
      return needsMutableLexicalState(syntax.value);
    // A cascade always lowers to hidden temporaries plus a statement sequence: the receiver must be
    // evaluated once even when it is already a plain name, because the alternative — replaying the
    // receiver expression per message — evaluates a send several times. So a cascade needs v1
    // regardless of what it is made of.
    case 'cascade':
      return true;
    case 'send':
      return needsMutableLexicalState(syntax.receiver)
        || syntax.arguments.some((argument) => needsMutableLexicalState(argument));
    // A symbol literal is an immutable compile-time value — it needs no v1 state, exactly
    // like integer, string, true, false, and nil.
    case 'symbol':
      return false;
    default:
      return false;
  }
}

// One decision for the whole tree. A nested program is embedded verbatim in its parent's `block`
// op and is also installed as its own artifact, and both readers validate against a closed grammar
// — so a v1 program cannot carry a v0-shaped child, nor the reverse.
function selectSemanticRepresentation(syntax) {
  return needsMutableLexicalState(syntax) ? LAGRANGE_CODE_V1 : LAGRANGE_CODE_V0;
}

// ADR 0050. An instance variable is not a new kind of expression: it lowers to an ordinary send of a
// language-owned primitive, reached through ordinary captures, so nothing downstream of the compiler
// learns a new concept. These names are internal to the binder and cannot collide with source names,
// which the tokenizer restricts to identifier characters.
const INSTANCE_SLOT_READ_CAPTURE = '$instanceSlotRead';
// ADR 0055: reserved for the compiler's `^` lowering, like the slot-primitive captures above.
const NON_LOCAL_RETURN_CAPTURE = '$nonLocalReturn';
// ADR 0056 decision 2. `nil` is a language-owned image object, so it cannot be a literal Value —
// the generic model has no nil kind and does not get one. It lowers to a reserved binding whose id
// is stable across images; installation supplies that image's kernel nil.
const NIL_CAPTURE = '$nil';
const NIL_BINDING_ID = 'smalltalk/intrinsic/nil';
// Symbol literals lower to a send of the spelling to the image-local interner, exactly as
// `nil` lowers to a read of the nil intrinsic. The compiled artifact carries only the canonical
// spelling as a Text literal — never an image-specific Symbol ref.
const SYMBOL_CAPTURE = '$symbol';
const SYMBOL_BINDING_ID = 'smalltalk/intrinsic/symbol';
// The empty literal Array `#()` (WS3) lowers to `new: 0` sent to the image-local Array class,
// reached through this intrinsic — exactly as Symbol lowers to a send to the interner and `nil`
// to a read of the nil intrinsic. The compiler names no class and bakes no image-local ref: the
// binding carries the id only, and installation supplies that image's Array class.
const ARRAY_CAPTURE = '$array';
const ARRAY_BINDING_ID = 'smalltalk/intrinsic/array';
// Internal capture key for a resolved global. Prefixed so it cannot collide with any source name —
// the tokenizer restricts those to identifier characters.
const GLOBAL_CAPTURE_PREFIX = '$global:';
// Internal capture key for a resolved class variable. Same prefixing rationale as globals.
const CLASS_VAR_CAPTURE_PREFIX = '$classVar:';
const INSTANCE_SLOT_WRITE_CAPTURE = '$instanceSlotWrite';

class SemanticScope {
  constructor({
    parent = null, path, parameters = [], rootCaptures = new Map(), instanceVariables = new Map(),
    methodHome = false, intrinsics = new Map(), globals = new Map(), classVariables = new Map(),
  } = {}) {
    // ADR 0057. Name -> binding id, resolved from the image's namespace by the *caller* and handed
    // in. This compiler stays synchronous and image-independent: it never reads storage, and what it
    // emits is binding identity rather than any image-specific ref.
    this.globals = parent ? parent.globals : globals;
    // Class variables: name -> binding id, resolved from the class hierarchy by the *caller*.
    // Same compiler-purity rule as globals: the compiler sees only the flat map.
    this.classVariables = parent ? parent.classVariables : classVariables;
    // Which class-variable bindings this compilation actually resolved. Transient provenance,
    // exactly like globalsUsed.
    this.classVarsUsed = parent ? parent.classVarsUsed : new Set();
    // ADR 0057. Which global bindings this compilation actually resolved. Transient compiler
    // metadata — never part of `lagrange-code` — and the only correct answer to "is this capture a
    // global?", because a capture id does not say *why* the capture exists.
    this.globalsUsed = parent ? parent.globalsUsed : new Set();
    // ADR 0055. Reserved bindings the binder makes *available* without declaring. A declaration
    // becomes a program capture whether or not the source references it, so declaring the return
    // intrinsic eagerly would give every method a dependency it may never use. Requested on first
    // lowering instead, which needs no second inspection of the source.
    this.intrinsics = parent ? parent.intrinsics : intrinsics;
    // ADR 0055. Whether this compilation has a method to return from. Carried explicitly rather
    // than inferred from the presence of instance variables — a method with no instance variables
    // still has a home, and a standalone Block with captures still has none.
    this.methodHome = methodHome || parent?.methodHome === true;
    this.parent = parent;
    this.instanceVariables = parent ? parent.instanceVariables : instanceVariables;
    this.path = path;
    this.parameters = new Map();
    parameters.forEach((name, index) => {
      this.parameters.set(name, Object.freeze({
        id: `${path}:parameter:${index}`,
        name,
        index,
      }));
    });
    this.temporaries = new Map();
    this.captures = new Map();
    if (!parent) {
      for (const [name, id] of rootCaptures) {
        this.captures.set(name, Object.freeze({id, name, source: null, mutable: false}));
      }
    }
  }

  // Declared before the statements are compiled, so `| total | total := 0` resolves.
  declareTemporaries(names) {
    names.forEach((name, index) => {
      if (this.parameters.has(name)) {
        throw new TypeError(`temporary ${name} shadows a parameter of the same activation`);
      }
      this.temporaries.set(name, Object.freeze({
        id: `${this.path}:temporary:${index}`,
        name,
      }));
    });
  }

  // Compiler-introduced bindings the source cannot name or collide with — `$` is not an identifier
  // character, so nothing reachable through `resolveName` ever reads one. A cascade uses these for
  // the shared receiver and the first message's answer.
  declareHiddenTemporary(key) {
    if (this.temporaries.has(key)) throw new TypeError(`duplicate hidden temporary ${key}`);
    const id = `${this.path}:${key}`;
    this.temporaries.set(key, Object.freeze({id, name: key}));
    return id;
  }

  addCapture(key, provided) {
    if (!this.captures.has(key)) {
      this.captures.set(key, Object.freeze({
        id: provided.id,
        name: provided.name,
        source: provided.value,
        mutable: provided.mutable === true,
      }));
    }
    return this.captures.get(key);
  }

  // ADR 0050 decision 3: lexical bindings first, and the instance variable only where resolution
  // would otherwise raise `unbound Symmetric Smalltalk name` — never earlier. A parameter named `x`
  // therefore shadows an instance variable named `x`.
  instanceSlot(name) {
    return this.instanceVariables.get(name) ?? null;
  }

  // Built in the *originating* scope, so `self` and the primitive capture resolve through this
  // scope's own chain. That is what makes an instance variable inside a nested Block mean the
  // defining method's receiver (ADR 0050 decision 10).
  canReturn() {
    return this.methodHome === true;
  }

  instanceSlotRead(slotId) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(INSTANCE_SLOT_READ_CAPTURE),
      message: textValue('value:value:'),
      arguments: Object.freeze([this.resolveSelf(), Object.freeze({op: 'literal', value: textValue(slotId)})]),
    });
  }

  // ADR 0055. `^ expr` lowers to `$nonLocalReturn value: expr` — an ordinary send, so
  // `lagrange-code` gains no operation for it. `resolveName` walks the capture chain exactly as it
  // does for the slot primitives, so a nested Block inherits the binding by ordinary propagation.
  rootScope() {
    let scope = this;
    while (scope.parent) scope = scope.parent;
    return scope;
  }

  // Seeds the reserved binding at the root the first time a `^` is lowered, then resolves it by the
  // ordinary capture walk — so a nested Block inherits it exactly as it inherits anything else.
  requireIntrinsic(name) {
    const root = this.rootScope();
    const id = root.intrinsics.get(name);
    if (!id) throw new TypeError(`no ${name} intrinsic is available in this compilation`);
    if (!root.captures.has(name)) {
      root.captures.set(name, Object.freeze({id, name, source: null, mutable: false}));
    }
    return this.resolveName(name);
  }

  nonLocalReturn(valueExpression) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.requireIntrinsic(NON_LOCAL_RETURN_CAPTURE),
      message: textValue('value:'),
      arguments: Object.freeze([valueExpression]),
    });
  }

  instanceSlotWrite(slotId, valueExpression) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(INSTANCE_SLOT_WRITE_CAPTURE),
      message: textValue('value:value:value:'),
      arguments: Object.freeze([
        this.resolveSelf(),
        Object.freeze({op: 'literal', value: textValue(slotId)}),
        valueExpression,
      ]),
    });
  }

  resolveName(name) {
    const parameter = this.parameters.get(name);
    if (parameter) return Object.freeze({op: 'argument', index: parameter.index});
    const temporary = this.temporaries.get(name);
    if (temporary) return Object.freeze({op: 'binding', id: temporary.id});
    const capture = this.captures.get(name);
    if (capture) return Object.freeze({op: 'binding', id: capture.id});
    const provided = this.parent ? this.parent.provideName(name) : null;
    if (provided) return Object.freeze({op: 'binding', id: this.addCapture(name, provided).id});
    const slotId = this.instanceSlot(name);
    if (slotId) return this.instanceSlotRead(slotId);
    // Class variables resolve after instance variables and before globals. A subclass method
    // can read an ancestor's class var; an unrelated class cannot resolve it by name.
    const classVar = this.resolveClassVariable(name);
    if (classVar) return classVar;
    // Globals resolve LAST, so no future publication can change what a name already means inside a
    // method that binds it lexically or as an instance variable.
    const global = this.resolveGlobal(name);
    if (global) return global;
    throw new TypeError(`unbound Symmetric Smalltalk name: ${name}`);
  }

  // A global read is a `value` send to the binding — an ordinary send, so `lagrange-code` gains
  // nothing. The capture is requested on first use, so a method mentioning no global carries none,
  // and a nested Block that is the only user still acquires it through the ordinary capture walk.
  resolveGlobal(name) {
    const bindingId = this.globals.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    // An explicit caller capture must not silently share a durable binding id with a resolved
    // global: two different meanings collapsing onto one environment key is exactly the sort of
    // aliasing that answers the wrong object.
    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(GLOBAL_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the global binding id ${bindingId}`);
      }
    }

    // Keyed by the *binding*, not by the source name. Keying by name would make the capture shadow
    // the global on every later read — `resolveName` finds a capture before it reaches global
    // resolution, so the second `Array` in a method would answer the binding object rather than the
    // class. It also makes an alias free: two names resolving to one binding share one capture,
    // which the closed capture grammar requires.
    const key = `${GLOBAL_CAPTURE_PREFIX}${bindingId}`;
    this.globalsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value'),
      arguments: Object.freeze([]),
    });
  }

  // A class-variable read is a `value` send to the binding — an ordinary send, exactly like a
  // global read. The capture is keyed by the binding identity, not the source name.
  resolveClassVariable(name) {
    const bindingId = this.classVariables.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    // Same collision check as globals: an explicit caller capture must not silently share a
    // durable binding id with a resolved class variable.
    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(CLASS_VAR_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the class-variable binding id ${bindingId}`);
      }
    }

    const key = `${CLASS_VAR_CAPTURE_PREFIX}${bindingId}`;
    this.classVarsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value'),
      arguments: Object.freeze([]),
    });
  }

  // A class-variable write is a `value:` send to the binding — an ordinary send. Unlike globals,
  // class variables are mutable shared state, so assignment lowers to `value: newValue`.
  resolveClassVariableWrite(name, valueExpression) {
    const bindingId = this.classVariables.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(CLASS_VAR_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the class-variable binding id ${bindingId}`);
      }
    }

    const key = `${CLASS_VAR_CAPTURE_PREFIX}${bindingId}`;
    this.classVarsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value:'),
      arguments: Object.freeze([valueExpression]),
    });
  }

  // Assignment needs a cell, so only a temporary — or a capture that resolves to one — qualifies.
  // Parameters and the receiver are not assignable, and a root capture names a durable environment
  // binding rather than a cell, which ADR 0043 decision 2 keeps out of assignment's reach.
  // Resolution finds the binding *first* and checks write legality *second*; it never keeps
  // searching for something assignable. So a parameter named `x` shadows an instance variable named
  // `x` for writes too, and `x := 5` stays illegal rather than becoming a slot write.
  resolveWrite(name) {
    if (this.parameters.has(name)) throw new TypeError(`cannot assign to parameter ${name}`);
    const temporary = this.temporaries.get(name);
    if (temporary) return {kind: 'binding', id: temporary.id};
    const existing = this.captures.get(name);
    if (existing) {
      if (!existing.mutable) throw new TypeError(`cannot assign to captured binding ${name}`);
      return {kind: 'binding', id: existing.id};
    }
    const provided = this.parent ? this.parent.provideName(name) : null;
    if (provided) {
      if (provided.mutable !== true) throw new TypeError(`cannot assign to captured binding ${name}`);
      return {kind: 'binding', id: this.addCapture(name, provided).id};
    }
    const slotId = this.instanceSlot(name);
    if (slotId) return {kind: 'instance', slotId};
    // Class variables are writable: assignment lowers to a `value:` send on the binding.
    if (this.classVariables.has(name)) {
      return {kind: 'classVariable', name};
    }
    // ADR 0057: assignment never reaches a global, and the check sits *last* so it matches the read
    // order — a temporary or instance variable of the same name shadows a global for writes exactly
    // as it does for reads. A known global then gets a diagnosis saying what is actually wrong,
    // rather than being reported as an unbound name; nothing is lowered and no setter exists.
    if (this.globals.has(name)) {
      throw new TypeError(`global assignment is not supported: ${name}`);
    }
    throw new TypeError(`unbound Symmetric Smalltalk name: ${name}`);
  }

  resolveSelf() {
    if (!this.parent) return Object.freeze({op: 'receiver'});
    const provided = this.parent.provideSelf();
    const capture = this.addCapture('$self', provided);
    return Object.freeze({op: 'binding', id: capture.id});
  }

  provideName(name) {
    const parameter = this.parameters.get(name);
    if (parameter) {
      return Object.freeze({
        id: parameter.id,
        name: parameter.name,
        mutable: false,
        value: Object.freeze({op: 'argument', index: parameter.index}),
      });
    }
    // A temporary is the one thing a nested Block must reach by cell rather than by snapshot.
    const temporary = this.temporaries.get(name);
    if (temporary) {
      return Object.freeze({
        id: temporary.id,
        name: temporary.name,
        mutable: true,
        value: Object.freeze({op: 'binding', id: temporary.id}),
      });
    }
    const capture = this.captures.get(name);
    if (capture) {
      return Object.freeze({
        id: capture.id,
        name: capture.name,
        mutable: capture.mutable,
        value: Object.freeze({op: 'binding', id: capture.id}),
      });
    }
    if (!this.parent) return null;
    // Ask upward directly rather than going through `resolveName`. Since ADR 0050 `resolveName` may
    // answer an *instance variable* — an expression, not a capture — and then there is nothing here
    // for a descendant to capture. Answering null in that case is right: the originating scope
    // resolves the instance variable itself, which is what makes the read reach the defining
    // method's receiver from any depth.
    const provided = this.parent.provideName(name);
    if (!provided) return null;
    const inherited = this.addCapture(name, provided);
    return Object.freeze({
      id: inherited.id,
      name: inherited.name,
      mutable: inherited.mutable,
      value: Object.freeze({op: 'binding', id: inherited.id}),
    });
  }

  provideSelf() {
    if (!this.parent) {
      return Object.freeze({
        id: `${this.path}:self`,
        name: 'self',
        mutable: false,
        value: Object.freeze({op: 'receiver'}),
      });
    }
    this.resolveSelf();
    const capture = this.captures.get('$self');
    return Object.freeze({
      id: capture.id,
      name: capture.name,
      mutable: capture.mutable,
      value: Object.freeze({op: 'binding', id: capture.id}),
    });
  }

  parameterDescriptors() {
    return Object.freeze([...this.parameters.values()].map(({id, name}) => Object.freeze({id, name})));
  }

  temporaryDescriptors() {
    return Object.freeze([...this.temporaries.values()].map(({id, name}) => Object.freeze({id, name})));
  }

  captureDescriptors(representation) {
    return Object.freeze([...this.captures.values()].map(({id, name, mutable}) => (
      representation === LAGRANGE_CODE_V1
        ? Object.freeze({id, mode: mutable ? 'cell' : 'snapshot', name})
        : Object.freeze({id, name})
    )));
  }

  // What the enclosing activation must supply when it creates the Block. A cell-mode capture
  // deliberately carries no value expression: there is nothing to evaluate, which is what stops a
  // snapshot reappearing under a different name.
  captureInitializers(representation) {
    const entries = [...this.captures.values()].filter(({source}) => source !== null);
    return Object.freeze(entries.map(({id, name, source, mutable}) => {
      if (representation !== LAGRANGE_CODE_V1) return Object.freeze({id, name, value: source});
      return mutable
        ? Object.freeze({id, mode: 'cell', name})
        : Object.freeze({id, mode: 'snapshot', name, value: source});
    }));
  }
}

// `receiverExpression` is already lowered: cascades compile their receiver once into a hidden
// temporary and hand every message the same binding read.
function compileSend(receiverExpression, selector, args, scope, state) {
  return Object.freeze({
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: receiverExpression,
    message: textValue(selector),
    arguments: Object.freeze(args.map((entry) => compileExpression(entry, scope, state))),
  });
}

function compileExpression(syntax, scope, state) {
  switch (syntax.kind) {
    case 'integer':
      return Object.freeze({op: 'literal', value: integerValue(syntax.value)});
    case 'string':
      return Object.freeze({op: 'literal', value: textValue(syntax.value)});
    case 'self':
      return scope.resolveSelf();
    // ADR 0056 decision 1: the canonical boolean Values themselves, not the kernel singletons. The
    // singleton is only ever a *dispatch* personality (ADR 0045), so compiling the literal to a ref
    // would undo that separation at the source level.
    case 'true':
      return Object.freeze({op: 'literal', value: booleanValue(true)});
    case 'false':
      return Object.freeze({op: 'literal', value: booleanValue(false)});
    // Requested lazily, so a program that never writes `nil` carries no binding for it and its
    // installer writes no environment (ADR 0055's rule, applied again).
    case 'nil':
      return scope.requireIntrinsic(NIL_CAPTURE);
    // A symbol literal lowers to an ordinary send of the canonical spelling to the interner
    // primitive, reached through the intrinsic capture walk. The artifact carries only the
    // spelling as a Text literal — no image-specific Symbol ref, no new lagrange-code op.
    case 'symbol':
      return Object.freeze({
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: scope.requireIntrinsic(SYMBOL_CAPTURE),
        message: textValue('value:'),
        arguments: Object.freeze([Object.freeze({op: 'literal', value: textValue(syntax.value)})]),
      });
    // Literal Array `#( )` (WS3). The authentic upstream RED demands only the empty form, which
    // lowers to `new: 0` sent to the image-local Array class through the `$array` intrinsic —
    // composed from the existing Array allocation machinery, exactly as Symbol lowers to a send
    // to the interner. The compiler names no class and bakes no image-local ref (the intrinsic
    // binding carries the id; installation supplies the class). No new lagrange-code op, no
    // generic Value array-literal kind, no literal carrying nested Smalltalk objects. Element
    // forms are a separate facility; the parser rejects them deterministically until demanded.
    case 'arrayLiteral': {
      if (syntax.elements.length !== 0) {
        throw new TypeError('literal Array element syntax is not supported; only the empty literal #() is');
      }
      return Object.freeze({
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: scope.requireIntrinsic(ARRAY_CAPTURE),
        message: textValue('new:'),
        arguments: Object.freeze([Object.freeze({op: 'literal', value: integerValue(0)})]),
      });
    }
    case 'name':
      return scope.resolveName(syntax.name);
    case 'return': {
      // A Block compiled with no method context has no home to return from, and never could have —
      // that is a fact about the compilation, so it is reported here rather than at invocation. It
      // is deliberately distinct from an escaped method Block, which compiled legitimately and
      // fails later because its home died.
      if (!scope.canReturn()) {
        throw new TypeError('non-local return requires a method home: `^` is only valid inside a method');
      }
      return scope.nonLocalReturn(compileExpression(syntax.value, scope, state));
    }
    case 'assign': {
      const target = scope.resolveWrite(syntax.name);
      const value = compileExpression(syntax.value, scope, state);
      if (target.kind === 'instance') return scope.instanceSlotWrite(target.slotId, value);
      if (target.kind === 'classVariable') return scope.resolveClassVariableWrite(target.name, value);
      return Object.freeze({op: 'binding-write', id: target.id, value});
    }
    case 'send':
      return compileSend(
        compileExpression(syntax.receiver, scope, state), syntax.selector, syntax.arguments, scope, state,
      );
    // `receiver m1; m2; m3` lowers to ordinary v1 state and sends — the IR gains no cascade op:
    //
    //   $recv := <receiver>.
    //   $first := $recv m1.
    //   $recv m2.
    //   $recv m3.
    //   $first
    //
    // which is exactly the cascade contract: the receiver is evaluated once, every message goes to
    // that object in source order, and the cascade answers the first message's value. Hidden
    // temporaries carry both, so nothing the source wrote is rewritten and no name can collide.
    case 'cascade': {
      const receiverId = scope.declareHiddenTemporary(`$cascadeReceiver:${state.nextCascade}`);
      const answerId = scope.declareHiddenTemporary(`$cascadeAnswer:${state.nextCascade}`);
      state.nextCascade += 1;
      const receiverRead = Object.freeze({op: 'binding', id: receiverId});
      const statements = [
        Object.freeze({
          op: 'binding-write',
          id: receiverId,
          value: compileExpression(syntax.receiver, scope, state),
        }),
        ...syntax.messages.map(({selector, arguments: args}, index) => {
          const send = compileSend(receiverRead, selector, args, scope, state);
          return index === 0
            ? Object.freeze({op: 'binding-write', id: answerId, value: send})
            : send;
        }),
        Object.freeze({op: 'binding', id: answerId}),
      ];
      return Object.freeze({op: 'sequence', statements: Object.freeze(statements)});
    }
    case 'block': {
      const blockId = `${state.path}/block:${state.nextBlock}`;
      state.nextBlock += 1;
      const nested = compileBlockSyntax(syntax, {
        parent: scope,
        path: blockId,
        representation: state.representation,
      });
      return Object.freeze({
        op: 'block',
        blockId,
        captures: nested.captureInitializers,
        program: nested.program,
      });
    }
    // Temporaries belong to the activation, so a sequence is only ever a Block body and is
    // compiled by compileBlockSyntax. Reaching here would mean a scope had gone missing.
    case 'sequence':
      throw new TypeError('a statement sequence may only appear as a block body');
    default:
      throw new TypeError(`unsupported Symmetric Smalltalk syntax kind: ${syntax.kind}`);
  }
}

function compileBody(syntax, scope, state) {
  if (syntax.kind !== 'sequence') return compileExpression(syntax, scope, state);
  scope.declareTemporaries(syntax.temporaries);
  const statements = Object.freeze(syntax.statements.map((statement) => compileExpression(statement, scope, state)));
  return statements.length === 1 ? statements[0] : Object.freeze({op: 'sequence', statements});
}

function compileBlockSyntax(syntax, {
  parent = null,
  path = 'root',
  rootCaptures = new Map(),
  instanceVariables = new Map(),
  representation = LAGRANGE_CODE_V0,
  methodHome = false,
  intrinsics = new Map(),
  globals = new Map(),
  classVariables = new Map(),
} = {}) {
  const scope = new SemanticScope({
    parent, path, parameters: syntax.parameters, rootCaptures, instanceVariables, methodHome,
    intrinsics, globals, classVariables,
  });
  const state = {path, nextBlock: 0, nextCascade: 0, representation};
  const body = compileBody(syntax.body, scope, state);
  const program = representation === LAGRANGE_CODE_V1
    ? Object.freeze({
      parameters: scope.parameterDescriptors(),
      temporaries: scope.temporaryDescriptors(),
      captures: scope.captureDescriptors(representation),
      body,
    })
    : Object.freeze({
      parameters: scope.parameterDescriptors(),
      captures: scope.captureDescriptors(representation),
      body,
    });
  return Object.freeze({
    program,
    captureInitializers: scope.captureInitializers(representation),
    globalBindingIdsUsed: Object.freeze([...scope.globalsUsed]),
    classVariableBindingIdsUsed: Object.freeze([...scope.classVarsUsed]),
  });
}

function compileSymmetricSmalltalkSemanticBlock(source, {
  captures = {}, instanceVariables = {}, methodHome = false, intrinsics = {}, globals = {},
  classVariables = {},
} = {}) {
  // ADR 0056: `nil` is the compiler's own intrinsic, so it is supplied here rather than by each
  // caller. Centralised for two reasons — every Symmetric Smalltalk compilation can write `nil`
  // whatever entry point it came through, and no caller can redefine what `nil` means. A caller may
  // still add intrinsics of its own; it may not replace this one, and saying so beats silently
  // winning an ordering race with it.
  if (Object.hasOwn(intrinsics, NIL_CAPTURE)) {
    throw new TypeError(`the ${NIL_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  if (Object.hasOwn(intrinsics, SYMBOL_CAPTURE)) {
    throw new TypeError(`the ${SYMBOL_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  if (Object.hasOwn(intrinsics, ARRAY_CAPTURE)) {
    throw new TypeError(`the ${ARRAY_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  const syntax = parseSymmetricSmalltalkBlock(source);
  const representation = selectSemanticRepresentation(syntax);
  const compiled = compileBlockSyntax(syntax, {
    path: 'root',
    rootCaptures: normalizeRootCaptures(captures),
    instanceVariables: new Map(Object.entries(instanceVariables)),
    representation,
    methodHome,
    intrinsics: new Map([
      ...Object.entries(intrinsics),
      [NIL_CAPTURE, NIL_BINDING_ID],
      [SYMBOL_CAPTURE, SYMBOL_BINDING_ID],
      [ARRAY_CAPTURE, ARRAY_BINDING_ID],
    ]),
    globals: new Map(Object.entries(globals)),
    classVariables: new Map(Object.entries(classVariables)),
  });
  return Object.freeze({
    syntax,
    program: compiled.program,
    representation,
    globalBindingIdsUsed: compiled.globalBindingIdsUsed,
    classVariableBindingIdsUsed: compiled.classVariableBindingIdsUsed,
  });
}

export {
  ARRAY_BINDING_ID,
  ARRAY_CAPTURE,
  CLASS_VAR_CAPTURE_PREFIX,
  INSTANCE_SLOT_READ_CAPTURE,
  NIL_BINDING_ID,
  NIL_CAPTURE,
  NON_LOCAL_RETURN_CAPTURE,
  INSTANCE_SLOT_WRITE_CAPTURE,
  SYMBOL_BINDING_ID,
  SYMBOL_CAPTURE,
  compileSymmetricSmalltalkSemanticBlock,
  needsMutableLexicalState,
  selectSemanticRepresentation,
};

const BINARY_SELECTOR_CHARS = new Set('+-*/=<>~&,@%?!\\'.split(''));

// Symbol literal characters. `#` begins a symbol; what follows determines the form:
// identifier chars (unary), keyword sequence (`#at:put:`), or binary selector chars (`#+`).
// Quoted symbols are deliberately not supported.

// ADR 0056 decision 3. Reserved pseudo-literals: they read as identifiers but are not names, so
// nothing may declare, capture, shadow or assign to one.
//
// Owned here, in one place, because the checks that enforce it are spread across block parameters,
// temporaries, assignment targets and explicit captures — four sites that would otherwise drift, as
// they already had: `self` was refused as a temporary and as an assignment target but accepted as a
// block parameter.
const RESERVED_WORDS = Object.freeze(new Set(['self', 'true', 'false', 'nil']));

function isReservedWord(name) {
  return RESERVED_WORDS.has(name);
}

class SymmetricSmalltalkSyntaxError extends SyntaxError {
  constructor(message, position) {
    super(`${message} at ${position}`);
    this.name = 'SymmetricSmalltalkSyntaxError';
    this.position = position;
  }
}

// WS3 (general language widening): a negative integer literal such as `-32` is
// Standard Smalltalk syntax, and the runtime's `0 - 32` already evaluates to a
// negative Value, so the literal is not new semantics — it is the canonical
// spelling of a value that already exists. The tokenizer still emits `-` as a
// binary selector so that `5-3`, `a-3` and `5 - 3` keep their binary-send
// meaning; the parser calls this only at an operand position (the start of a
// primary), where a leading `-` can only be a sign. `-16r1F` is covered too.
function isNegativeIntegerLiteralAt(tokens, index) {
  const minus = tokens[index];
  const next = tokens[index + 1];
  return Boolean(
    minus && minus.type === 'binary' && minus.value === '-'
    && next && next.type === 'integer',
  );
}

function isIdentifierStart(char) {
  return /[A-Za-z_]/.test(char ?? '');
}

function isIdentifierPart(char) {
  return /[A-Za-z0-9_]/.test(char ?? '');
}

function tokenizeSymmetricSmalltalk(source) {
  if (typeof source !== 'string') throw new TypeError('source must be text');
  const tokens = [];
  let index = 0;

  const push = (type, value, start = index) => tokens.push(Object.freeze({type, value, start, end: index}));

  while (index < source.length) {
    const char = source[index];

    if (/\s/.test(char)) {
      index += 1;
      continue;
    }

    if (char === '"') {
      const start = index;
      index += 1;
      while (index < source.length && source[index] !== '"') index += 1;
      if (index >= source.length) throw new SymmetricSmalltalkSyntaxError('unterminated comment', start);
      index += 1;
      continue;
    }

    // Symbol literal: `#` followed by identifier chars (unary), a keyword sequence
    // (`#at:put:`), or binary selector chars (`#+`). The token carries the canonical
    // selector text. No quoted/arbitrary symbol syntax.
    if (char === '#') {
      const start = index;
      index += 1; // consume '#'
      if (index >= source.length) {
        throw new SymmetricSmalltalkSyntaxError('bare # is not a valid symbol literal', start);
      }
      const next = source[index];
      // Literal Array `#( ... )` (WS3): `#(` opens a literal Array, distinct from a symbol.
      // `#[ ... ]` (byte-array literal) is deliberately NOT this facility — its resulting class
      // and element restrictions differ, and it is classified separately when upstream demands it.
      if (next === '(') {
        index += 1; // consume '('
        push('arrayOpen', '(', start);
        continue;
      }
      if (next === '[') {
        throw new SymmetricSmalltalkSyntaxError(
          '#[ is byte-array literal syntax, which is not the #() literal-Array facility', start,
        );
      }
      if (isIdentifierStart(next)) {
        // Unary or keyword symbol: read identifier chars, then optionally ':' sequences
        let value = '';
        while (index < source.length) {
          if (isIdentifierPart(source[index])) {
            value += source[index];
            index += 1;
            continue;
          }
          if (source[index] === ':' && source[index + 1] !== '=') {
            value += ':';
            index += 1;
            continue;
          }
          break;
        }
        push('symbol', value, start);
        continue;
      }
      if (BINARY_SELECTOR_CHARS.has(next)) {
        let value = '';
        while (index < source.length && BINARY_SELECTOR_CHARS.has(source[index])) {
          value += source[index];
          index += 1;
        }
        push('symbol', value, start);
        continue;
      }
      throw new SymmetricSmalltalkSyntaxError(
        `invalid symbol literal: #${next}`, start,
      );
    }

    if (char === "'") {
      const start = index;
      index += 1;
      let value = '';
      let closed = false;
      while (index < source.length) {
        if (source[index] === "'") {
          if (source[index + 1] === "'") {
            value += "'";
            index += 2;
            continue;
          }
          index += 1;
          closed = true;
          break;
        }
        value += source[index];
        index += 1;
      }
      if (!closed) throw new SymmetricSmalltalkSyntaxError('unterminated string', start);
      push('string', value, start);
      continue;
    }

    if (/[0-9]/.test(char)) {
      const start = index;
      while (/[0-9]/.test(source[index] ?? '')) index += 1;
      // ADR 0057 workstream 3. `<base>r<digits>` is a radix integer literal (`16rFF`, `2r1010`).
      // Radix is source syntax, never runtime representation: the token carries the canonical
      // decimal text an ordinary literal would, so the parser, the semantic layer and the durable
      // Value model (which accepts only `/^-?\d+$/`) never learn a radix existed. A leading `-` is
      // a binary selector send in source order (`0 - 16r80`), not part of the literal.
      if (source[index] === 'r' || source[index] === 'R') {
        const baseText = source.slice(start, index);
        const base = Number.parseInt(baseText, 10);
        index += 1; // consume the `r`
        const digitsStart = index;
        while (/[0-9A-Za-z]/.test(source[index] ?? '')) index += 1;
        const digits = source.slice(digitsStart, index);
        if (digits === '' || !/^\d+$/.test(baseText) || base < 2 || base > 36) {
          throw new SymmetricSmalltalkSyntaxError(`malformed radix literal ${baseText}r${digits}`, start);
        }
        // Per-digit validation catches `2r102`, which a bulk parse would silently truncate.
        let value = 0n;
        const radix = BigInt(base);
        for (const digitChar of digits) {
          const digit = Number.parseInt(digitChar, 36);
          if (digit >= base) {
            throw new SymmetricSmalltalkSyntaxError(
              `digit ${digitChar} is out of range for radix ${base} in ${baseText}r${digits}`, start,
            );
          }
          value = value * radix + BigInt(digit);
        }
        push('integer', value.toString(10), start);
        continue;
      }
      push('integer', source.slice(start, index), start);
      continue;
    }

    if (isIdentifierStart(char)) {
      const start = index;
      index += 1;
      while (isIdentifierPart(source[index])) index += 1;
      const name = source.slice(start, index);
      // `:` only makes a keyword when it is not the start of `:=`.
      if (source[index] === ':' && source[index + 1] !== '=') {
        index += 1;
        push('keyword', `${name}:`, start);
      } else {
        push('identifier', name, start);
      }
      continue;
    }

    if (BINARY_SELECTOR_CHARS.has(char)) {
      const start = index;
      index += 1;
      while (BINARY_SELECTOR_CHARS.has(source[index])) index += 1;
      push('binary', source.slice(start, index), start);
      continue;
    }

    if (char === ':' && source[index + 1] === '=') {
      const start = index;
      index += 2;
      push('assign', ':=', start);
      continue;
    }

    // ADR 0055: `^` is syntax, not a binary selector, so it gets its own token and cannot be
    // absorbed into an adjacent operator the way `^=` otherwise would be.
    if (char === '^') {
      const start = index;
      index += 1;
      push('caret', '^', start);
      continue;
    }

    if ('[]()|:.;'.includes(char)) {
      const start = index;
      index += 1;
      push(char, char, start);
      continue;
    }

    throw new SymmetricSmalltalkSyntaxError(`unexpected character ${JSON.stringify(char)}`, index);
  }

  tokens.push(Object.freeze({type: 'eof', value: '', start: index, end: index}));
  return Object.freeze(tokens);
}

