function preflightProgram(program) {
  try {
    return compileWasmModule(program);
  } catch (error) {
    if (!isWasmTailEffectRestrictionError(error)) throw error;
    return compileResumableWasmModule(program);
  }
}

function preflightEntries(entries) {
